**`src/main.zig`**
```zig
const std = @import("std");
const mem = @import("runtime/memory.zig");
const nccl = @import("runtime/nccl.zig");
const checkpoint = @import("runtime/checkpoint.zig");
const efla = @import("model/efla.zig");
const tokenizer = @import("model/tokenizer.zig");
const muon = @import("optimizer/muon.zig");
const lion = @import("optimizer/lion.zig");
const harness = @import("eval/harness.zig");

pub const TrainingConfig = struct {
    num_gpus: u32 = 8,
    model_dim: u32 = 120_000,
    num_layers: u32 = 96,
    num_heads: u32 = 96,
    head_dim: u32 = 1_250,
    ffn_dim: u32 = 480_000,
    vocab_size: u32 = 131_072,
    max_seq_len: u64 = 50_000_000,
    batch_size: u32 = 1,
    micro_batch_size: u32 = 1,
    grad_accum_steps: u32 = 64,
    learning_rate: f32 = 1e-4,
    weight_decay: f32 = 0.1,
    warmup_steps: u64 = 2_000,
    total_steps: u64 = 500_000,
    checkpoint_interval: u64 = 1_000,
    log_interval: u64 = 10,
    precision: mem.Precision = .mxfp8,
    optimizer_precision: mem.Precision = .fp8,
    use_cpu_offload: bool = true,
    use_nvme_offload: bool = true,
    nvme_path: []const u8 = "/mnt/nvme/offload",
    checkpoint_path: []const u8 = "/mnt/nfs/checkpoints",
    sequence_parallel: bool = true,
    tensor_parallel_degree: u32 = 8,
    zero_stage: u32 = 3,
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const config = TrainingConfig{};

    var comm = try nccl.NcclComm.init(config.num_gpus, allocator);
    defer comm.deinit();

    var memory_manager = try mem.MemoryManager.init(
        config.num_gpus,
        config.use_cpu_offload,
        config.use_nvme_offload,
        config.nvme_path,
        allocator,
    );
    defer memory_manager.deinit();

    var tok = try tokenizer.EntropyTokenizer.init(
        config.vocab_size,
        131_072,
        allocator,
    );
    defer tok.deinit();

    var model = try efla.EFLAModel.init(config, &memory_manager, &comm, allocator);
    defer model.deinit();

    var optimizer_2d = try muon.MuonOptimizer.init(
        model.get2DParams(),
        config.learning_rate,
        config.weight_decay,
        config.optimizer_precision,
        allocator,
    );
    defer optimizer_2d.deinit();

    var optimizer_1d = try lion.LionOptimizer.init(
        model.get1DParams(),
        config.learning_rate,
        config.weight_decay,
        config.optimizer_precision,
        allocator,
    );
    defer optimizer_1d.deinit();

    var ckpt_manager = try checkpoint.CheckpointManager.init(
        config.checkpoint_path,
        config.checkpoint_interval,
        allocator,
    );
    defer ckpt_manager.deinit();

    var global_step: u64 = 0;
    if (try ckpt_manager.findLatest()) |step| {
        global_step = step;
        try ckpt_manager.load(step, &model, &optimizer_2d, &optimizer_1d);
        std.log.info("Resumed from checkpoint step {}", .{global_step});
    }

    var eval = try harness.EvalHarness.init(config, &tok, allocator);
    defer eval.deinit();

    var data_loader = try DataLoader.init(
        config.max_seq_len,
        config.num_gpus,
        config.sequence_parallel,
        allocator,
    );
    defer data_loader.deinit();

    std.log.info("Starting training: 1T param EFLA on 8xB200", .{});
    std.log.info("Config: dim={} layers={} heads={} ctx={}M", .{
        config.model_dim,
        config.num_layers,
        config.num_heads,
        config.max_seq_len / 1_000_000,
    });

    while (global_step < config.total_steps) : (global_step += 1) {
        const lr = computeLearningRate(
            global_step,
            config.warmup_steps,
            config.total_steps,
            config.learning_rate,
        );

        var grad_accum_loss: f64 = 0.0;

        var accum_step: u32 = 0;
        while (accum_step < config.grad_accum_steps) : (accum_step += 1) {
            const batch = try data_loader.nextBatch();
            const loss = try model.forwardBackward(batch, accum_step == 0);
            grad_accum_loss += loss;
        }

        grad_accum_loss /= @as(f64, @floatFromInt(config.grad_accum_steps));

        try comm.allReduceGrads(model.getGradBuffer());

        try model.clipGradients(1.0);

        optimizer_2d.setLearningRate(lr);
        optimizer_1d.setLearningRate(lr);
        try optimizer_2d.step(model.get2DParams(), model.get2DGrads());
        try optimizer_1d.step(model.get1DParams(), model.get1DGrads());

        model.zeroGrads();

        if (global_step % config.log_interval == 0) {
            const tokens_per_sec = data_loader.getTokensPerSec();
            std.log.info(
                "step={} loss={d:.4} lr={e:.3} tok/s={d:.0}",
                .{ global_step, grad_accum_loss, lr, tokens_per_sec },
            );
        }

        if (global_step % config.checkpoint_interval == 0 and global_step > 0) {
            try ckpt_manager.save(global_step, &model, &optimizer_2d, &optimizer_1d);
        }

        if (global_step % 10_000 == 0 and global_step > 0) {
            const eval_results = try eval.runNeedleInHaystack(&model, 10_000_000);
            std.log.info("Eval NIAH@10M: {d:.4}", .{eval_results.accuracy});
        }
    }

    std.log.info("Training complete at step {}", .{global_step});
}

fn computeLearningRate(step: u64, warmup: u64, total: u64, peak_lr: f32) f32 {
    if (step < warmup) {
        return peak_lr * @as(f32, @floatFromInt(step)) / @as(f32, @floatFromInt(warmup));
    }
    const progress = @as(f32, @floatFromInt(step - warmup)) /
        @as(f32, @floatFromInt(total - warmup));
    const cosine = 0.5 * (1.0 + @cos(std.math.pi * progress));
    return peak_lr * cosine * 0.1 + peak_lr * 0.0;
}

pub const DataLoader = struct {
    seq_len: u64,
    num_gpus: u32,
    sequence_parallel: bool,
    allocator: std.mem.Allocator,
    token_buffer: []u32,
    file_handle: ?std.fs.File,
    bytes_read: u64,
    last_time: i64,
    last_tokens: u64,

    pub fn init(
        seq_len: u64,
        num_gpus: u32,
        sequence_parallel: bool,
        allocator: std.mem.Allocator,
    ) !DataLoader {
        const token_buffer = try allocator.alloc(u32, seq_len);
        return DataLoader{
            .seq_len = seq_len,
            .num_gpus = num_gpus,
            .sequence_parallel = sequence_parallel,
            .allocator = allocator,
            .token_buffer = token_buffer,
            .file_handle = null,
            .bytes_read = 0,
            .last_time = std.time.milliTimestamp(),
            .last_tokens = 0,
        };
    }

    pub fn deinit(self: *DataLoader) void {
        self.allocator.free(self.token_buffer);
        if (self.file_handle) |f| f.close();
    }

    pub fn nextBatch(self: *DataLoader) ![]u32 {
        if (self.file_handle == null) {
            self.file_handle = try std.fs.openFileAbsolute(
                "/mnt/data/train_tokens.bin",
                .{ .mode = .read_only },
            );
        }
        const file = self.file_handle.?;
        const bytes_needed = self.seq_len * @sizeOf(u32);
        const buf = std.mem.sliceAsBytes(self.token_buffer);
        const bytes_read_now = try file.readAll(buf[0..bytes_needed]);
        if (bytes_read_now < bytes_needed) {
            try file.seekTo(0);
            _ = try file.readAll(buf[0..bytes_needed]);
        }
        self.bytes_read += bytes_needed;
        self.last_tokens += self.seq_len;
        return self.token_buffer;
    }

    pub fn getTokensPerSec(self: *DataLoader) f64 {
        const now = std.time.milliTimestamp();
        const elapsed_ms = now - self.last_time;
        if (elapsed_ms == 0) return 0.0;
        const tps = @as(f64, @floatFromInt(self.last_tokens)) /
            (@as(f64, @floatFromInt(elapsed_ms)) / 1000.0);
        self.last_time = now;
        self.last_tokens = 0;
        return tps;
    }
};
