**`src/runtime/memory.zig`**
```zig
const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cuda_fp8.h");
});

pub const Precision = enum {
    fp32,
    bf16,
    fp16,
    fp8,
    fp4,
    mxfp8,
    mxfp4,
};

pub const TensorDescriptor = struct {
    ptr: *anyopaque,
    num_elements: usize,
    precision: Precision,
    device_id: i32,
    is_cpu: bool,
    is_nvme: bool,
    nvme_offset: u64,
    size_bytes: usize,
};

pub const MemoryBlock = struct {
    gpu_ptr: ?*anyopaque,
    cpu_ptr: ?*anyopaque,
    size_bytes: usize,
    device_id: i32,
    pinned: bool,

    pub fn allocGPU(size: usize, device_id: i32) !MemoryBlock {
        var ptr: ?*anyopaque = null;
        const err = c.cudaSetDevice(device_id);
        if (err != c.cudaSuccess) return error.CudaSetDeviceFailed;
        const err2 = c.cudaMalloc(&ptr, size);
        if (err2 != c.cudaSuccess) return error.CudaMallocFailed;
        return MemoryBlock{
            .gpu_ptr = ptr,
            .cpu_ptr = null,
            .size_bytes = size,
            .device_id = device_id,
            .pinned = false,
        };
    }

    pub fn allocPinned(size: usize, device_id: i32) !MemoryBlock {
        var ptr: ?*anyopaque = null;
        const err = c.cudaMallocHost(&ptr, size);
        if (err != c.cudaSuccess) return error.CudaMallocHostFailed;
        return MemoryBlock{
            .gpu_ptr = null,
            .cpu_ptr = ptr,
            .size_bytes = size,
            .device_id = device_id,
            .pinned = true,
        };
    }

    pub fn freeGPU(self: *MemoryBlock) void {
        if (self.gpu_ptr) |ptr| {
            _ = c.cudaFree(ptr);
            self.gpu_ptr = null;
        }
    }

    pub fn freeCPU(self: *MemoryBlock) void {
        if (self.cpu_ptr) |ptr| {
            if (self.pinned) {
                _ = c.cudaFreeHost(ptr);
            }
            self.cpu_ptr = null;
        }
    }

    pub fn copyHostToDevice(self: *MemoryBlock, stream: c.cudaStream_t) !void {
        if (self.cpu_ptr == null or self.gpu_ptr == null) return error.NullPointer;
        const err = c.cudaMemcpyAsync(
            self.gpu_ptr.?,
            self.cpu_ptr.?,
            self.size_bytes,
            c.cudaMemcpyHostToDevice,
            stream,
        );
        if (err != c.cudaSuccess) return error.CudaMemcpyFailed;
    }

    pub fn copyDeviceToHost(self: *MemoryBlock, stream: c.cudaStream_t) !void {
        if (self.cpu_ptr == null or self.gpu_ptr == null) return error.NullPointer;
        const err = c.cudaMemcpyAsync(
            self.cpu_ptr.?,
            self.gpu_ptr.?,
            self.size_bytes,
            c.cudaMemcpyDeviceToHost,
            stream,
        );
        if (err != c.cudaSuccess) return error.CudaMemcpyFailed;
    }
};

pub const NVMeOffloadManager = struct {
    base_path: []const u8,
    file_handles: std.ArrayList(std.fs.File),
    current_offset: u64,
    allocator: std.mem.Allocator,

    pub fn init(base_path: []const u8, allocator: std.mem.Allocator) !NVMeOffloadManager {
        try std.fs.makeDirAbsolute(base_path) catch |err| {
            if (err != error.PathAlreadyExists) return err;
        };
        return NVMeOffloadManager{
            .base_path = base_path,
            .file_handles = std.ArrayList(std.fs.File).init(allocator),
            .current_offset = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *NVMeOffloadManager) void {
        for (self.file_handles.items) |f| f.close();
        self.file_handles.deinit();
    }

    pub fn writeAsync(self: *NVMeOffloadManager, data: []const u8, layer_id: u32) !u64 {
        const filename = try std.fmt.allocPrint(
            self.allocator,
            "{s}/layer_{d}.bin",
            .{ self.base_path, layer_id },
        );
        defer self.allocator.free(filename);

        const file = try std.fs.createFileAbsolute(filename, .{ .truncate = true });
        try self.file_handles.append(file);
        try file.writeAll(data);

        const offset = self.current_offset;
        self.current_offset += data.len;
        return offset;
    }

    pub fn readAsync(self: *NVMeOffloadManager, buffer: []u8, layer_id: u32) !void {
        const filename = try std.fmt.allocPrint(
            self.allocator,
            "{s}/layer_{d}.bin",
            .{ self.base_path, layer_id },
        );
        defer self.allocator.free(filename);

        const file = try std.fs.openFileAbsolute(filename, .{});
        defer file.close();
        _ = try file.readAll(buffer);
    }
};

pub const ZeROShardManager = struct {
    num_gpus: u32,
    local_rank: u32,
    param_shards: std.ArrayList(TensorDescriptor),
    grad_shards: std.ArrayList(TensorDescriptor),
    optim_shards: std.ArrayList(TensorDescriptor),
    allocator: std.mem.Allocator,

    pub fn init(num_gpus: u32, local_rank: u32, allocator: std.mem.Allocator) ZeROShardManager {
        return ZeROShardManager{
            .num_gpus = num_gpus,
            .local_rank = local_rank,
            .param_shards = std.ArrayList(TensorDescriptor).init(allocator),
            .grad_shards = std.ArrayList(TensorDescriptor).init(allocator),
            .optim_shards = std.ArrayList(TensorDescriptor).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ZeROShardManager) void {
        self.param_shards.deinit();
        self.grad_shards.deinit();
        self.optim_shards.deinit();
    }

    pub fn shardSize(total_elements: usize, num_gpus: u32) usize {
        return (total_elements + num_gpus - 1) / num_gpus;
    }

    pub fn localShardStart(self: *ZeROShardManager, total_elements: usize) usize {
        const shard = shardSize(total_elements, self.num_gpus);
        return self.local_rank * shard;
    }

    pub fn localShardEnd(self: *ZeROShardManager, total_elements: usize) usize {
        const shard = shardSize(total_elements, self.num_gpus);
        const start = self.local_rank * shard;
        return @min(start + shard, total_elements);
    }

    pub fn registerParam(
        self: *ZeROShardManager,
        ptr: *anyopaque,
        total_elements: usize,
        precision: Precision,
        device_id: i32,
    ) !void {
        const elem_size = precisionBytes(precision);
        const start = self.localShardStart(total_elements);
        const end = self.localShardEnd(total_elements);
        const shard_elements = end - start;
        const byte_offset = start * elem_size;
        const shard_ptr: *anyopaque = @ptrFromInt(@intFromPtr(ptr) + byte_offset);
        try self.param_shards.append(TensorDescriptor{
            .ptr = shard_ptr,
            .num_elements = shard_elements,
            .precision = precision,
            .device_id = device_id,
            .is_cpu = false,
            .is_nvme = false,
            .nvme_offset = 0,
            .size_bytes = shard_elements * elem_size,
        });
    }
};

pub fn precisionBytes(p: Precision) usize {
    return switch (p) {
        .fp32 => 4,
        .bf16, .fp16 => 2,
        .fp8, .mxfp8 => 1,
        .fp4, .mxfp4 => 1,
    };
}

pub const MemoryManager = struct {
    num_gpus: u32,
    use_cpu_offload: bool,
    use_nvme_offload: bool,
    nvme_manager: ?NVMeOffloadManager,
    zero_shards: []ZeROShardManager,
    streams: []c.cudaStream_t,
    allocator: std.mem.Allocator,
    total_gpu_memory_bytes: usize,
    allocated_gpu_bytes: usize,

    pub fn init(
        num_gpus: u32,
        use_cpu_offload: bool,
        use_nvme_offload: bool,
        nvme_path: []const u8,
        allocator: std.mem.Allocator,
    ) !MemoryManager {
        const zero_shards = try allocator.alloc(ZeROShardManager, num_gpus);
        for (zero_shards, 0..) |*shard, i| {
            shard.* = ZeROShardManager.init(num_gpus, @intCast(i), allocator);
        }

        const streams = try allocator.alloc(c.cudaStream_t, num_gpus);
        for (streams, 0..) |*stream, i| {
            _ = c.cudaSetDevice(@intCast(i));
            const err = c.cudaStreamCreateWithFlags(stream, c.cudaStreamNonBlocking);
            if (err != c.cudaSuccess) return error.CudaStreamCreateFailed;
        }

        var nvme_mgr: ?NVMeOffloadManager = null;
        if (use_nvme_offload) {
            nvme_mgr = try NVMeOffloadManager.init(nvme_path, allocator);
        }

        const bytes_per_gpu: usize = 192 * 1024 * 1024 * 1024;

        return MemoryManager{
            .num_gpus = num_gpus,
            .use_cpu_offload = use_cpu_offload,
            .use_nvme_offload = use_nvme_offload,
            .nvme_manager = nvme_mgr,
            .zero_shards = zero_shards,
            .streams = streams,
            .allocator = allocator,
            .total_gpu_memory_bytes = bytes_per_gpu * num_gpus,
            .allocated_gpu_bytes = 0,
        };
    }

    pub fn deinit(self: *MemoryManager) void {
        for (self.zero_shards) |*shard| shard.deinit();
        self.allocator.free(self.zero_shards);
        for (self.streams, 0..) |stream, i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaStreamDestroy(stream);
        }
        self.allocator.free(self.streams);
        if (self.nvme_manager) |*nm| nm.deinit();
    }

    pub fn allocOnGPU(
        self: *MemoryManager,
        size_bytes: usize,
        device_id: i32,
    ) !MemoryBlock {
        self.allocated_gpu_bytes += size_bytes;
        return MemoryBlock.allocGPU(size_bytes, device_id);
    }

    pub fn allocPinned(self: *MemoryManager, size_bytes: usize, device_id: i32) !MemoryBlock {
        return MemoryBlock.allocPinned(size_bytes, device_id);
    }

    pub fn getStream(self: *MemoryManager, device_id: i32) c.cudaStream_t {
        return self.streams[@intCast(device_id)];
    }

    pub fn syncAll(self: *MemoryManager) !void {
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            const err = c.cudaStreamSynchronize(self.streams[i]);
            if (err != c.cudaSuccess) return error.CudaSyncFailed;
        }
    }

    pub fn memoryUsageReport(self: *MemoryManager) void {
        const gb = 1024 * 1024 * 1024;
        std.log.info(
            "Memory: allocated={d}GB / total={d}GB",
            .{
                self.allocated_gpu_bytes / gb,
                self.total_gpu_memory_bytes / gb,
            },
        );
    }
};
