**`src/runtime/nccl.zig`**
```zig
const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("nccl.h");
});

pub const NcclError = error{
    NcclInitFailed,
    NcclAllReduceFailed,
    NcclBroadcastFailed,
    NcclAllGatherFailed,
    NcclReduceScatterFailed,
    NcclBarrierFailed,
    NcclSendFailed,
    NcclRecvFailed,
    CudaSetDeviceFailed,
};

fn checkNccl(err: c.ncclResult_t) NcclError!void {
    if (err != c.ncclSuccess) return error.NcclInitFailed;
}

pub const NcclComm = struct {
    comms: []c.ncclComm_t,
    streams: []c.cudaStream_t,
    num_gpus: u32,
    allocator: std.mem.Allocator,

    pub fn init(num_gpus: u32, allocator: std.mem.Allocator) !NcclComm {
        const dev_list = try allocator.alloc(c_int, num_gpus);
        defer allocator.free(dev_list);
        for (dev_list, 0..) |*d, i| d.* = @intCast(i);

        const comms = try allocator.alloc(c.ncclComm_t, num_gpus);
        const streams = try allocator.alloc(c.cudaStream_t, num_gpus);

        for (0..num_gpus) |i| {
            const err = c.cudaSetDevice(@intCast(i));
            if (err != c.cudaSuccess) return error.CudaSetDeviceFailed;
            const serr = c.cudaStreamCreate(&streams[i]);
            if (serr != c.cudaSuccess) return error.CudaSetDeviceFailed;
        }

        const ncerr = c.ncclCommInitAll(comms.ptr, @intCast(num_gpus), dev_list.ptr);
        try checkNccl(ncerr);

        return NcclComm{
            .comms = comms,
            .streams = streams,
            .num_gpus = num_gpus,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *NcclComm) void {
        for (self.comms) |comm| _ = c.ncclCommDestroy(comm);
        for (self.streams, 0..) |stream, i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaStreamDestroy(stream);
        }
        self.allocator.free(self.comms);
        self.allocator.free(self.streams);
    }

    pub fn allReduceSum(
        self: *NcclComm,
        send_buf: *anyopaque,
        recv_buf: *anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclAllReduce(
            send_buf,
            recv_buf,
            count,
            dtype,
            c.ncclSum,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }

    pub fn allReduceGrads(self: *NcclComm, grad_buffer: GradBuffer) !void {
        try checkNccl(c.ncclGroupStart());
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            const count = grad_buffer.size / @sizeOf(f32);
            const err = c.ncclAllReduce(
                grad_buffer.ptrs[i],
                grad_buffer.ptrs[i],
                count,
                c.ncclFloat32,
                c.ncclSum,
                self.comms[i],
                self.streams[i],
            );
            try checkNccl(err);
        }
        try checkNccl(c.ncclGroupEnd());
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaStreamSynchronize(self.streams[i]);
        }
    }

    pub fn reduceScatter(
        self: *NcclComm,
        send_buf: *anyopaque,
        recv_buf: *anyopaque,
        recv_count: usize,
        dtype: c.ncclDataType_t,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclReduceScatter(
            send_buf,
            recv_buf,
            recv_count,
            dtype,
            c.ncclSum,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }

    pub fn allGather(
        self: *NcclComm,
        send_buf: *anyopaque,
        recv_buf: *anyopaque,
        send_count: usize,
        dtype: c.ncclDataType_t,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclAllGather(
            send_buf,
            recv_buf,
            send_count,
            dtype,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }

    pub fn broadcast(
        self: *NcclComm,
        buf: *anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        root: c_int,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclBroadcast(
            buf,
            buf,
            count,
            dtype,
            root,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }

    pub fn syncAll(self: *NcclComm) void {
        for (self.streams, 0..) |stream, i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaStreamSynchronize(stream);
        }
    }

    pub fn send(
        self: *NcclComm,
        buf: *anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        peer: c_int,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclSend(
            buf,
            count,
            dtype,
            peer,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }

    pub fn recv(
        self: *NcclComm,
        buf: *anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        peer: c_int,
        gpu_id: u32,
    ) !void {
        _ = c.cudaSetDevice(@intCast(gpu_id));
        const err = c.ncclRecv(
            buf,
            count,
            dtype,
            peer,
            self.comms[gpu_id],
            self.streams[gpu_id],
        );
        try checkNccl(err);
    }
};

pub const GradBuffer = struct {
    ptrs: []*anyopaque,
    size: usize,
    num_gpus: u32,
};
