const std = @import("std");
const efla = @import("../model/efla.zig");
const muon = @import("../optimizer/muon.zig");
const lion = @import("../optimizer/lion.zig");

pub const CheckpointManifest = struct {
    step: u64,
    model_files: [][]const u8,
    optimizer_2d_file: []const u8,
    optimizer_1d_file: []const u8,
    rng_state: u64,
    loss_at_step: f64,
    timestamp: i64,
};

pub const CheckpointManager = struct {
    base_path: []const u8,
    interval: u64,
    allocator: std.mem.Allocator,
    manifest_list: std.ArrayList(u64),

    pub fn init(base_path: []const u8, interval: u64, allocator: std.mem.Allocator) !CheckpointManager {
        std.fs.makeDirAbsolute(base_path) catch |err| {
            if (err != error.PathAlreadyExists) return err;
        };
        return CheckpointManager{
            .base_path = base_path,
            .interval = interval,
            .allocator = allocator,
            .manifest_list = std.ArrayList(u64).init(allocator),
        };
    }

    pub fn deinit(self: *CheckpointManager) void {
        self.manifest_list.deinit();
    }

    pub fn findLatest(self: *CheckpointManager) !?u64 {
        const manifest_index = try std.fmt.allocPrint(
            self.allocator,
            "{s}/manifest_index.txt",
            .{self.base_path},
        );
        defer self.allocator.free(manifest_index);

        const file = std.fs.openFileAbsolute(manifest_index, .{}) catch return null;
        defer file.close();

        var buf: [64]u8 = undefined;
        const n = try file.readAll(&buf);
        if (n == 0) return null;

        const step_str = std.mem.trim(u8, buf[0..n], &std.ascii.whitespace);
        return try std.fmt.parseInt(u64, step_str, 10);
    }

    pub fn save(
        self: *CheckpointManager,
        step: u64,
        model: *efla.EFLAModel,
        opt_2d: *muon.MuonOptimizer,
        opt_1d: *lion.LionOptimizer,
    ) !void {
        const step_dir = try std.fmt.allocPrint(
            self.allocator,
            "{s}/step_{d}",
            .{ self.base_path, step },
        );
        defer self.allocator.free(step_dir);

        std.fs.makeDirAbsolute(step_dir) catch |err| {
            if (err != error.PathAlreadyExists) return err;
        };

        for (model.layers, 0..) |layer, i| {
            const layer_file = try std.fmt.allocPrint(
                self.allocator,
                "{s}/layer_{d}.bin",
                .{ step_dir, i },
            );
            defer self.allocator.free(layer_file);
            const f = try std.fs.createFileAbsolute(layer_file, .{});
            defer f.close();
            try layer.serialize(f.writer());
        }

        const opt2d_file = try std.fmt.allocPrint(
            self.allocator,
            "{s}/muon_state.bin",
            .{step_dir},
        );
        defer self.allocator.free(opt2d_file);
        const f2d = try std.fs.createFileAbsolute(opt2d_file, .{});
        defer f2d.close();
        try opt_2d.serialize(f2d.writer());

        const opt1d_file = try std.fmt.allocPrint(
            self.allocator,
            "{s}/lion_state.bin",
            .{step_dir},
        );
        defer self.allocator.free(opt1d_file);
        const f1d = try std.fs.createFileAbsolute(opt1d_file, .{});
        defer f1d.close();
        try opt_1d.serialize(f1d.writer());

        const manifest_index = try std.fmt.allocPrint(
            self.allocator,
            "{s}/manifest_index.txt",
            .{self.base_path},
        );
        defer self.allocator.free(manifest_index);
        const mf = try std.fs.createFileAbsolute(manifest_index, .{});
        defer mf.close();
        try mf.writer().print("{d}", .{step});

        try self.manifest_list.append(step);
        std.log.info("Checkpoint saved at step {}", .{step});

        if (self.manifest_list.items.len > 3) {
            const old_step = self.manifest_list.orderedRemove(0);
            const old_dir = try std.fmt.allocPrint(
                self.allocator,
                "{s}/step_{d}",
                .{ self.base_path, old_step },
            );
            defer self.allocator.free(old_dir);
            std.fs.deleteTreeAbsolute(old_dir) catch {};
        }
    }

    pub fn load(
        self: *CheckpointManager,
        step: u64,
        model: *efla.EFLAModel,
        opt_2d: *muon.MuonOptimizer,
        opt_1d: *lion.LionOptimizer,
    ) !void {
        const step_dir = try std.fmt.allocPrint(
            self.allocator,
            "{s}/step_{d}",
            .{ self.base_path, step },
        );
        defer self.allocator.free(step_dir);

        for (model.layers, 0..) |*layer, i| {
            const layer_file = try std.fmt.allocPrint(
                self.allocator,
                "{s}/layer_{d}.bin",
                .{ step_dir, i },
            );
            defer self.allocator.free(layer_file);
            const f = try std.fs.openFileAbsolute(layer_file, .{});
            defer f.close();
            try layer.deserialize(f.reader());
        }

        const opt2d_file = try std.fmt.allocPrint(
            self.allocator,
            "{s}/muon_state.bin",
            .{step_dir},
        );
        defer self.allocator.free(opt2d_file);
        const f2d = try std.fs.openFileAbsolute(opt2d_file, .{});
        defer f2d.close();
        try opt_2d.deserialize(f2d.reader());

        const opt1d_file = try std.fmt.allocPrint(
            self.allocator,
            "{s}/lion_state.bin",
            .{step_dir},
        );
        defer self.allocator.free(opt1d_file);
        const f1d = try std.fs.openFileAbsolute(opt1d_file, .{});
        defer f1d.close();
        try opt_1d.deserialize(f1d.reader());

        std.log.info("Checkpoint loaded from step {}", .{step});
    }
};
