```zig
const std = @import("std");

pub const TokenizerConfig = struct {
    vocab_size: u32,
    max_token_length: u32 = 32,
    entropy_threshold: f32 = 3.5,
    eod_token: u32 = 2,
    bos_token: u32 = 1,
    unk_token: u32 = 0,
    pad_token: u32 = 3,
};

pub const TrieNode = struct {
    children: std.HashMap(u8, *TrieNode, std.hash_map.AutoContext(u8), 80),
    token_id: ?u32,
    is_terminal: bool,
    entropy_score: f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !*TrieNode {
        const node = try allocator.create(TrieNode);
        node.* = TrieNode{
            .children = std.HashMap(u8, *TrieNode, std.hash_map.AutoContext(u8), 80).init(allocator),
            .token_id = null,
            .is_terminal = false,
            .entropy_score = 0.0,
            .allocator = allocator,
        };
        return node;
    }

    pub fn deinit(self: *TrieNode) void {
        var it = self.children.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.deinit();
        }
        self.children.deinit();
        self.allocator.destroy(self);
    }

    pub fn insert(self: *TrieNode, text: []const u8, token_id: u32, allocator: std.mem.Allocator) !void {
        if (text.len == 0) {
            self.token_id = token_id;
            self.is_terminal = true;
            return;
        }
        const byte = text[0];
        const child = self.children.get(byte) orelse blk: {
            const new_child = try TrieNode.init(allocator);
            try self.children.put(byte, new_child);
            break :blk new_child;
        };
        try child.insert(text[1..], token_id, allocator);
    }

    pub fn longestMatch(self: *TrieNode, text: []const u8) ?struct { len: usize, token_id: u32 } {
        var best_match: ?struct { len: usize, token_id: u32 } = null;
        var node = self;
        for (text, 0..) |byte, i| {
            const child = node.children.get(byte) orelse break;
            node = child;
            if (node.is_terminal and node.token_id != null) {
                best_match = .{ .len = i + 1, .token_id = node.token_id.? };
            }
        }
        return best_match;
    }
};

pub const VocabEntry = struct {
    text: []const u8,
    token_id: u32,
    frequency: u64,
    entropy: f32,
};

pub const EntropyTokenizer = struct {
    config: TokenizerConfig,
    vocab: std.ArrayList(VocabEntry),
    trie_root: *TrieNode,
    id_to_token: std.ArrayList([]const u8),
    merge_ranks: std.HashMap(u64, u32, std.hash_map.AutoContext(u64), 80),
    allocator: std.mem.Allocator,

    pub fn init(vocab_size: u32, max_token_length: u32, allocator: std.mem.Allocator) !EntropyTokenizer {
        const config = TokenizerConfig{
            .vocab_size = vocab_size,
            .max_token_length = max_token_length,
        };
        const trie_root = try TrieNode.init(allocator);
        return EntropyTokenizer{
            .config = config,
            .vocab = std.ArrayList(VocabEntry).init(allocator),
            .trie_root = trie_root,
            .id_to_token = std.ArrayList([]const u8).init(allocator),
            .merge_ranks = std.HashMap(u64, u32, std.hash_map.AutoContext(u64), 80).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EntropyTokenizer) void {
        for (self.vocab.items) |entry| {
            self.allocator.free(entry.text);
        }
        self.vocab.deinit();
        self.trie_root.deinit();
        self.id_to_token.deinit();
        self.merge_ranks.deinit();
    }

    pub fn loadFromFile(self: *EntropyTokenizer, path: []const u8) !void {
        const file = try std.fs.openFileAbsolute(path, .{});
        defer file.close();

        var buf_reader = std.io.bufferedReader(file.reader());
        var reader = buf_reader.reader();

        var line_buf: [4096]u8 = undefined;
        var token_id: u32 = 4;

        while (try reader.readUntilDelimiterOrEof(&line_buf, '\n')) |line| {
            const trimmed = std.mem.trim(u8, line, &std.ascii.whitespace);
            if (trimmed.len == 0) continue;

            var parts = std.mem.split(u8, trimmed, "\t");
            const token_text = parts.next() orelse continue;
            const freq_str = parts.next() orelse "1";
            const freq = std.fmt.parseInt(u64, freq_str, 10) catch 1;

            const owned_text = try self.allocator.dupe(u8, token_text);
            const entropy = computeTokenEntropy(token_text);

            if (entropy >= self.config.entropy_threshold or token_id < 256) {
                try self.vocab.append(VocabEntry{
                    .text = owned_text,
                    .token_id = token_id,
                    .frequency = freq,
                    .entropy = entropy,
                });
                try self.trie_root.insert(owned_text, token_id, self.allocator);
                try self.id_to_token.append(owned_text);
                token_id += 1;

                if (token_id >= self.config.vocab_size) break;
            }
        }
    }

    pub fn encode(self: *EntropyTokenizer, text: []const u8, output: *std.ArrayList(u32)) !void {
        try output.append(self.config.bos_token);
        var pos: usize = 0;
        while (pos < text.len) {
            if (self.trie_root.longestMatch(text[pos..])) |match| {
                try output.append(match.token_id);
                pos += match.len;
            } else {
                const byte_token = self.byteTokenId(text[pos]);
                try output.append(byte_token);
                pos += 1;
            }
        }
    }

    pub fn encodeWithEOD(self: *EntropyTokenizer, text: []const u8, output: *std.ArrayList(u32)) !void {
        try self.encode(text, output);
        try output.append(self.config.eod_token);
    }

    pub fn decode(self: *EntropyTokenizer, tokens: []const u32, output: *std.ArrayList(u8)) !void {
        for (tokens) |tid| {
            if (tid == self.config.bos_token or tid == self.config.eod_token) continue;
            if (tid == self.config.pad_token) continue;
            if (tid < self.id_to_token.items.len) {
                try output.appendSlice(self.id_to_token.items[tid]);
            } else {
                try output.append('?');
            }
        }
    }

    fn byteTokenId(self: *EntropyTokenizer, byte: u8) u32 {
        _ = self;
        return @as(u32, byte) + 4;
    }

    pub fn packDocumentsToChunks(
        self: *EntropyTokenizer,
        documents: []const []const u8,
        chunk_size: u64,
        output_path: []const u8,
    ) !void {
        const file = try std.fs.createFileAbsolute(output_path, .{});
        defer file.close();

        var buf_writer = std.io.bufferedWriter(file.writer());
        var writer = buf_writer.writer();

        var current_chunk = std.ArrayList(u32).init(self.allocator);
        defer current_chunk.deinit();

        var encoded_doc = std.ArrayList(u32).init(self.allocator);
        defer encoded_doc.deinit();

        for (documents) |doc| {
            encoded_doc.clearRetainingCapacity();
            try self.encodeWithEOD(doc, &encoded_doc);

            for (encoded_doc.items) |token| {
                try current_chunk.append(token);
                if (current_chunk.items.len >= chunk_size) {
                    for (current_chunk.items) |t| {
                        try writer.writeInt(u32, t, .little);
                    }
                    current_chunk.clearRetainingCapacity();
                }
            }
        }

        if (current_chunk.items.len > 0) {
            while (current_chunk.items.len < chunk_size) {
                try current_chunk.append(self.config.pad_token);
            }
            for (current_chunk.items) |t| {
                try writer.writeInt(u32, t, .little);
            }
        }

        try buf_writer.flush();
    }
};

fn computeTokenEntropy(text: []const u8) f32 {
    if (text.len == 0) return 0.0;
    var counts: [256]u32 = [_]u32{0} ** 256;
    for (text) |byte| counts[byte] += 1;
    var entropy: f32 = 0.0;
    const len_f: f32 = @floatFromInt(text.len);
    for (counts) |count| {
        if (count == 0) continue;
        const p: f32 = @as(f32, @floatFromInt(count)) / len_f;
        entropy -= p * @log2(p);
    }
    return entropy;
}

pub const StreamingPacker = struct {
    tokenizer: *EntropyTokenizer,
    chunk_size: u64,
    output_file: std.fs.File,
    current_chunk: std.ArrayList(u32),
    total_tokens_written: u64,
    total_chunks_written: u64,
    allocator: std.mem.Allocator,

    pub fn init(
        tokenizer: *EntropyTokenizer,
        chunk_size: u64,
        output_path: []const u8,
        allocator: std.mem.Allocator,
    ) !StreamingPacker {
        const file = try std.fs.createFileAbsolute(output_path, .{});
        const current_chunk = try std.ArrayList(u32).initCapacity(allocator, @intCast(chunk_size));
        return StreamingPacker{
            .tokenizer = tokenizer,
            .chunk_size = chunk_size,
            .output_file = file,
            .current_chunk = current_chunk,
            .total_tokens_written = 0,
            .total_chunks_written = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StreamingPacker) void {
        self.output_file.close();
        self.current_chunk.deinit();
    }

    pub fn addDocument(self: *StreamingPacker, text: []const u8) !void {
        var encoded = std.ArrayList(u32).init(self.allocator);
        defer encoded.deinit();
        try self.tokenizer.encodeWithEOD(text, &encoded);

        for (encoded.items) |token| {
            try self.current_chunk.append(token);
            if (self.current_chunk.items.len >= self.chunk_size) {
                try self.flushChunk();
            }
        }
    }

    pub fn flushChunk(self: *StreamingPacker) !void {
        var writer = self.output_file.writer();
        for (self.current_chunk.items) |t| {
            try writer.writeInt(u32, t, .little);
        }
        self.total_tokens_written += self.current_chunk.items.len;
        self.total_chunks_written += 1;
        self.current_chunk.clearRetainingCapacity();
        std.log.info(
            "Packed chunk {}: total tokens = {}",
            .{ self.total_chunks_written, self.total_tokens_written },
        );
    }

    pub fn finalize(self: *StreamingPacker) !void {
        if (self.current_chunk.items.len > 0) {
            while (self.current_chunk.items.len < self.chunk_size) {
                try self.current_chunk.append(self.tokenizer.config.pad_token);
            }
            try self.flushChunk();
        }
    }
};
