const std = @import("std");
const mem = @import("../runtime/memory.zig");
const efla = @import("../model/efla.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cublas_v2.h");
});

pub const MuonConfig = struct {
    learning_rate: f32 = 1e-4,
    momentum: f32 = 0.95,
    nesterov: bool = true,
    weight_decay: f32 = 0.1,
    ns_steps: u32 = 5,
    ns_eps: f32 = 1e-7,
    precision: mem.Precision = .fp8,
    grad_scale: f32 = 65504.0,
};

pub const MuonParamState = struct {
    momentum_buf: mem.MemoryBlock,
    num_rows: usize,
    num_cols: usize,
    device_id: i32,
};

pub const MuonOptimizer = struct {
    config: MuonConfig,
    param_states: std.ArrayList(MuonParamState),
    step_count: u64,
    cublas_handle: c.cublasHandle_t,
    allocator: std.mem.Allocator,

    pub fn init(
        params: efla.ParamList,
        learning_rate: f32,
        weight_decay: f32,
        precision: mem.Precision,
        allocator: std.mem.Allocator,
    ) !MuonOptimizer {
        const config = MuonConfig{
            .learning_rate = learning_rate,
            .weight_decay = weight_decay,
            .precision = precision,
        };

        var handle: c.cublasHandle_t = undefined;
        _ = c.cublasCreate(&handle);
        _ = c.cublasSetMathMode(handle, c.CUBLAS_TENSOR_OP_MATH);

        var param_states = std.ArrayList(MuonParamState).init(allocator);
        for (params.blocks) |block| {
            const momentum_buf = try mem.MemoryBlock.allocGPU(block.size_bytes, block.device_id);
            _ = c.cudaSetDevice(block.device_id);
            _ = c.cudaMemset(momentum_buf.gpu_ptr.?, 0, block.size_bytes);
            try param_states.append(MuonParamState{
                .momentum_buf = momentum_buf,
                .num_rows = 1,
                .num_cols = block.num_elements,
                .device_id = block.device_id,
            });
        }

        return MuonOptimizer{
            .config = config,
            .param_states = param_states,
            .step_count = 0,
            .cublas_handle = handle,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *MuonOptimizer) void {
        for (self.param_states.items) |*state| {
            state.momentum_buf.freeGPU();
        }
        self.param_states.deinit();
        _ = c.cublasDestroy(self.cublas_handle);
    }

    pub fn setLearningRate(self: *MuonOptimizer, lr: f32) void {
        self.config.learning_rate = lr;
    }

    pub fn step(
        self: *MuonOptimizer,
        params: efla.ParamList,
        grads: efla.GradList,
    ) !void {
        self.step_count += 1;

        for (params.blocks, grads.blocks, self.param_states.items) |param, grad, *state| {
            _ = c.cudaSetDevice(state.device_id);

            launchMuonNewtonSchulz5(
                @as([*]f32, @ptrCast(grad.gpu_ptr.?)),
                state.num_rows,
                state.num_cols,
                self.config.ns_steps,
                self.config.ns_eps,
                state.device_id,
                @as(c.cudaStream_t, @ptrFromInt(0)),
            );

            launchMuonMomentumUpdate(
                @as([*]f32, @ptrCast(state.momentum_buf.gpu_ptr.?)),
                @as([*]f32, @ptrCast(grad.gpu_ptr.?)),
                self.config.momentum,
                param.num_elements,
                state.device_id,
                @as(c.cudaStream_t, @ptrFromInt(0)),
            );

            launchMuonParamUpdate(
                @as([*]f32, @ptrCast(param.gpu_ptr.?)),
                @as([*]f32, @ptrCast(state.momentum_buf.gpu_ptr.?)),
                @as([*]f32, @ptrCast(grad.gpu_ptr.?)),
                self.config.learning_rate,
                self.config.weight_decay,
                self.config.nesterov,
                param.num_elements,
                state.device_id,
                @as(c.cudaStream_t, @ptrFromInt(0)),
            );
        }
    }

    pub fn serialize(self: *const MuonOptimizer, writer: anytype) !void {
        try writer.writeInt(u64, self.step_count, .little);
        try writer.writeAll(std.mem.asBytes(&self.config));
        for (self.param_states.items) |state| {
            var cpu_buf = try std.heap.page_allocator.alloc(u8, state.momentum_buf.size_bytes);
            defer std.heap.page_allocator.free(cpu_buf);
            _ = c.cudaMemcpy(
                cpu_buf.ptr,
                state.momentum_buf.gpu_ptr.?,
                state.momentum_buf.size_bytes,
                c.cudaMemcpyDeviceToHost,
            );
            try writer.writeInt(u64, state.momentum_buf.size_bytes, .little);
            try writer.writeAll(cpu_buf);
        }
    }

    pub fn deserialize(self: *MuonOptimizer, reader: anytype) !void {
        self.step_count = try reader.readInt(u64, .little);
