const std = @import("std");
const mem = @import("../runtime/memory.zig");
const efla = @import("../model/efla.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const LionConfig = struct {
    learning_rate: f32 = 1e-4,
    beta1: f32 = 0.9,
    beta2: f32 = 0.99,
    weight_decay: f32 = 0.1,
    precision: mem.Precision = .fp8,
    grad_scale: f32 = 65504.0,
};

pub const LionParamState = struct {
    momentum_buf: mem.MemoryBlock,
    num_elements: usize,
    device_id: i32,
};

pub const LionOptimizer = struct {
    config: LionConfig,
    param_states: std.ArrayList(LionParamState),
    step_count: u64,
    allocator: std.mem.Allocator,

    pub fn init(
        params: efla.ParamList,
        learning_rate: f32,
        weight_decay: f32,
        precision: mem.Precision,
        allocator: std.mem.Allocator,
    ) !LionOptimizer {
        const config = LionConfig{
            .learning_rate = learning_rate,
            .weight_decay = weight_decay,
            .precision = precision,
        };

        var param_states = std.ArrayList(LionParamState).init(allocator);
        for (params.blocks) |block| {
            const elem_bytes = mem.precisionBytes(precision);
            const momentum_size = block.num_elements * elem_bytes;
            const momentum_buf = try mem.MemoryBlock.allocGPU(momentum_size, block.device_id);
            _ = c.cudaSetDevice(block.device_id);
            _ = c.cudaMemset(momentum_buf.gpu_ptr.?, 0, momentum_size);
            try param_states.append(LionParamState{
                .momentum_buf = momentum_buf,
                .num_elements = block.num_elements,
                .device_id = block.device_id,
            });
        }

        return LionOptimizer{
            .config = config,
            .param_states = param_states,
            .step_count = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *LionOptimizer) void {
        for (self.param_states.items) |*state| {
            state.momentum_buf.freeGPU();
        }
        self.param_states.deinit();
    }

    pub fn setLearningRate(self: *LionOptimizer, lr: f32) void {
        self.config.learning_rate = lr;
    }

    pub fn step(
        self: *LionOptimizer,
        params: efla.ParamList,
        grads: efla.GradList,
    ) !void {
        self.step_count += 1;

        for (params.blocks, grads.blocks, self.param_states.items) |param, grad, *state| {
            _ = c.cudaSetDevice(state.device_id);

            launchLionStep(
                @as([*]f32, @ptrCast(param.gpu_ptr.?)),
                @as([*]f32, @ptrCast(state.momentum_buf.gpu_ptr.?)),
                @as([*]f32, @ptrCast(grad.gpu_ptr.?)),
                self.config.learning_rate,
                self.config.beta1,
                self.config.beta2,
                self.config.weight_decay,
                state.num_elements,
                state.device_id,
                @as(c.cudaStream_t, @ptrFromInt(0)),
            );
        }
    }

    pub fn serialize(self: *const LionOptimizer, writer: anytype) !void {
        try writer.writeInt(u64, self.step_count, .little);
        try writer.writeAll(std.mem.asBytes(&self.config));
        for (self.param_states.items) |state| {
            var cpu_buf = try std.heap.page_allocator.alloc(u8, state.momentum_buf.size_bytes);
            defer std.heap.page_allocator.free(cpu_buf);
            _ = c.cudaMemcpy(
                cpu_buf.ptr,
                state.momentum_buf.gpu_ptr.?,
                state.momentum_buf.size_bytes,
                c.cudaMemcpyDeviceToHost,
            );
            try writer.writeInt(u64, state.momentum_buf.size_bytes, .little);
            try writer.writeAll(cpu_buf);
        }
    }

    pub fn deserialize(self: *LionOptimizer, reader: anytype) !void {
        self.step_count = try reader.readInt(u64, .little);
        _ = try reader.readAll(std.mem.asBytes(&self.config));
        for (self.param_states.items) |*state| {
            const size = try reader.readInt(u64, .little);
            var cpu_buf = try std.heap.page_allocator.alloc(u8, size);
            defer std.heap.page_allocator.free(cpu_buf);
            _ = try reader.readAll(cpu_buf);
            _ = c.cudaMemcpy(
                state.momentum_buf.gpu_ptr.?,
                cpu_buf.ptr,
                size,
                c.cudaMemcpyHostToDevice,
            );
        }
    }
};

