```zig
const std = @import("std");
const efla = @import("../model/efla.zig");
const tokenizer = @import("../model/tokenizer.zig");
const mem = @import("../runtime/memory.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const EvalConfig = struct {
    niah_context_lengths: []const u64 = &[_]u64{
        1_000_000,
        5_000_000,
        10_000_000,
        25_000_000,
        50_000_000,
    },
    niah_num_needles: u32 = 10,
    niah_num_trials: u32 = 50,
    long_summary_lengths: []const u64 = &[_]u64{ 1_000_000, 5_000_000 },
    batch_size: u32 = 1,
};

pub const NIAHResult = struct {
    context_length: u64,
    accuracy: f64,
    mean_retrieval_position_error: f64,
    num_trials: u32,
};

pub const EvalResults = struct {
    niah_results: std.ArrayList(NIAHResult),
    accuracy: f64,
    perplexity: f64,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) EvalResults {
        return EvalResults{
            .niah_results = std.ArrayList(NIAHResult).init(allocator),
            .accuracy = 0.0,
            .perplexity = 0.0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EvalResults) void {
        self.niah_results.deinit();
    }
};

pub const EvalHarness = struct {
    config: EvalConfig,
    training_config: anytype,
    tok: *tokenizer.EntropyTokenizer,
    rng: std.Random.DefaultPrng,
    allocator: std.mem.Allocator,

    pub fn init(
        training_config: anytype,
        tok: *tokenizer.EntropyTokenizer,
        allocator: std.mem.Allocator,
    ) !EvalHarness {
        return EvalHarness{
            .config = EvalConfig{},
            .training_config = training_config,
            .tok = tok,
            .rng = std.Random.DefaultPrng.init(42),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EvalHarness) void {
        _ = self;
    }

    pub fn runNeedleInHaystack(
        self: *EvalHarness,
        model: *efla.EFLAModel,
        context_length: u64,
    ) !EvalResults {
        var results = EvalResults.init(self.allocator);
        var total_correct: u64 = 0;
        var total_trials: u64 = 0;

        for (0..self.config.niah_num_trials) |trial_idx| {
            const haystack = try self.generateHaystack(context_length - 100, trial_idx);
            defer self.allocator.free(haystack);

            const needle_pos = self.rng.random().intRangeAtMost(
                usize,
                1000,
                haystack.len - 1000,
            );

            const needle_key = try std.fmt.allocPrint(
                self.allocator,
                "SECRET_NEEDLE_{d}",
                .{trial_idx},
            );
            defer self.allocator.free(needle_key);

            const needle_val = try std.fmt.allocPrint(
                self.allocator,
                "ANSWER_{d}",
                .{trial_idx * 17 + 42},
            );
            defer self.allocator.free(needle_val);

            const full_text = try std.mem.concat(self.allocator, u8, &[_][]const u8{
                haystack[0..needle_pos],
                " [",
                needle_key,
                " = ",
                needle_val,
                "] ",
                haystack[needle_pos..],
                "\n\nWhat is ",
                needle_key,
                "? Answer:",
            });
            defer self.allocator.free(full_text);

            var encoded = std.ArrayList(u32).init(self.allocator);
            defer encoded.deinit();
            try self.tok.encode(full_text, &encoded);

            const tokens_to_use = encoded.items[0..@min(encoded.items.len, @intCast(context_length))];

            const predicted_token = try self.runModelInference(model, tokens_to_use);

            var expected_encoded = std.ArrayList(u32).init(self.allocator);
            defer expected_encoded.deinit();
            try self.tok.encode(needle_val, &expected_encoded);

            if (expected_encoded.items.len > 0 and
                predicted_token == expected_encoded.items[0])
            {
                total_correct += 1;
            }
            total_trials += 1;
        }

        const accuracy = @as(f64, @floatFromInt(total_correct)) /
            @as(f64, @floatFromInt(total_trials));

        try results.niah_results.append(NIAHResult{
            .context_length = context_length,
            .accuracy = accuracy,
            .mean_retrieval_position_error = 0.0,
            .num_trials = @intCast(total_trials),
        });
        results.accuracy = accuracy;

        return results;
    }

    fn runModelInference(self: *EvalHarness, model: *efla.EFLAModel, tokens: []u32) !u32 {
        _ = self;
        const logits_size = model.config.vocab_size * @sizeOf(f32);
        var logits_buf = try model.mm.allocOnGPU(logits_size, 0);
        defer logits_buf.freeGPU();

        var hidden_buf = try model.mm.allocOnGPU(
            model.config.model_dim * @sizeOf(f32),
            0,
        );
        defer hidden_buf.freeGPU();

        var token_gpu = try model.mm.allocOnGPU(tokens.len * @sizeOf(u32), 0);
        defer token_gpu.freeGPU();

        _ = c.cudaMemcpy(
            token_gpu.gpu_ptr.?,
            tokens.ptr,
            tokens.len * @sizeOf(u32),
            c.cudaMemcpyHostToDevice,
        );

        var logits_cpu = try self.allocator.alloc(f32, model.config.vocab_size);
        defer self.allocator.free(logits_cpu);

        _ = c.cudaMemcpy(
            logits_cpu.ptr,
            logits_buf.gpu_ptr.?,
            logits_size,
            c.cudaMemcpyDeviceToHost,
        );

        var best_token: u32 = 0;
        var best_logit: f32 = -std.math.inf(f32);
        for (logits_cpu, 0..) |logit, idx| {
            if (logit > best_logit) {
                best_logit = logit;
                best_token = @intCast(idx);
            }
        }
        return best_token;
    }

    fn generateHaystack(self: *EvalHarness, length_chars: u64, seed: usize) ![]u8 {
        const sentences = [_][]const u8{
            "The quick brown fox jumps over the lazy dog. ",
            "Artificial intelligence is transforming the world in unprecedented ways. ",
            "Deep learning models require massive amounts of compute and data. ",
            "Language models can generate coherent text across many domains. ",
            "Research in machine learning continues to accelerate rapidly. ",
            "Hardware accelerators enable training of billion parameter models. ",
            "Distributed training across multiple GPUs is now standard practice. ",
            "Attention mechanisms allow models to focus on relevant context. ",
            "Linear time sequence models may replace transformers for long contexts. ",
            "Custom silicon and memory hierarchies drive efficiency gains. ",
        };

        var result = std.ArrayList(u8).init(self.allocator);
        var rng = std.Random.DefaultPrng.init(@intCast(seed));

        while (result.items.len < length_chars) {
            const idx = rng.random().intRangeLessThan(usize, 0, sentences.len);
            try result.appendSlice(sentences[idx]);
        }
        return result.toOwnedSlice();
    }

    pub fn computePerplexity(
        self: *EvalHarness,
        model: *efla.EFLAModel,
        eval_tokens: []const u32,
    ) !f64 {
        _ = self;
        var total_log_prob: f64 = 0.0;
        var total_tokens: u64 = 0;
        const chunk_size: usize = 4096;
        var offset: usize = 0;

        while (offset + 1 < eval_tokens.len) {
            const end = @min(offset + chunk_size, eval_tokens.len - 1);
            const chunk = eval_tokens[offset..end];

            const logits_size = chunk.len * model.config.vocab_size * @sizeOf(f32);
            var logits_buf = try model.mm.allocOnGPU(logits_size, 0);
            defer logits_buf.freeGPU();

            var logits_cpu = try self.allocator.alloc(f32, chunk.len * model.config.vocab_size);
            defer self.allocator.free(logits_cpu);

            _ = c.cudaMemcpy(
                logits_cpu.ptr,
                logits_buf.gpu_ptr.?,
                logits_size,
                c.cudaMemcpyDeviceToHost,
            );

            for (chunk, 0..) |_, t| {
                if (offset + t + 1 >= eval_tokens.len) break;
                const target = eval_tokens[offset + t + 1];
                const logit_offset = t * model.config.vocab_size;
                var max_logit: f32 = -std.math.inf(f32);
                for (logits_cpu[logit_offset .. logit_offset + model.config.vocab_size]) |l| {
                    if (l > max_logit) max_logit = l;
                }
                var sum_exp: f64 = 0.0;
                for (logits_cpu[logit_offset .. logit_offset + model.config.vocab_size]) |l| {
                    sum_exp += @exp(@as(f64, l - max_logit));
                }
                const log_prob = @as(f64, logits_cpu[logit_offset + target] - max_logit) -
                    @log(sum_exp);
                total_log_prob += log_prob;
                total_tokens += 1;
            }
            offset = end;
        }

        if (total_tokens == 0) return 0.0;
        const avg_nll = -total_log_prob / @as(f64, @floatFromInt(total_tokens));
        return @exp(avg_nll);
    }
};
