**`kernels/efla.fut`**
```futhark
import "mxfp8"

let sigmoid (x: f32) : f32 =
  1.0f32 / (1.0f32 + f32.exp (-x))

let silu (x: f32) : f32 =
  x * sigmoid x

let rms_norm [n] (x: [n]f32) (scale: [n]f32) (eps: f32) : [n]f32 =
  let sq_sum = f32.sum (map (\xi -> xi * xi) x)
  let rms = f32.sqrt (sq_sum / f32.i64 n + eps)
  in map2 (\xi si -> xi / rms * si) x scale

let softplus (x: f32) : f32 =
  f32.log (1.0f32 + f32.exp x)

let efla_decay_fn (d: f32) : f32 =
  -(softplus d)

let efla_fast_weight_update
    [r] [d]
    (fw_key: [r][d]f32)
    (fw_val: [r][d]f32)
    (decay: [r]f32)
    (k_t: [d]f32)
    (v_t: [d]f32)
    : ([r][d]f32, [r][d]f32) =
  let new_fw_key =
    map3 (\fk_row v_row beta ->
      let dk = efla_decay_fn beta
      in map2 (\fk ki -> f32.exp dk * fk + ki) fk_row k_t
    ) fw_key fw_val decay
  let new_fw_val =
    map3 (\fv_row v_row beta ->
      let dk = efla_decay_fn beta
      in map2 (\fv vi -> f32.exp dk * fv + vi) fv_row v_t
    ) fw_key fw_val decay
  in (new_fw_key, new_fw_val)

let efla_read_memory
    [r] [d]
    (fw_key: [r][d]f32)
    (fw_val: [r][d]f32)
    (q_t: [d]f32)
    : [d]f32 =
  let scores = map (\fk_row ->
    f32.sum (map2 (*) fk_row q_t)
  ) fw_key
  let max_score = f32.maximum scores
  let exp_scores = map (\s -> f32.exp (s - max_score)) scores
  let sum_exp = f32.sum exp_scores
  let weights = map (\e -> e / sum_exp) exp_scores
  in map (\j ->
    f32.sum (map2 (\w fv_row -> w * fv_row[j]) weights fw_val)
  ) (iota d)

let efla_combine
    (left_fw_key: [][](f32))
    (left_fw_val: [][](f32))
    (right_fw_key: [][](f32))
    (right_fw_val: [][](f32))
    (decay: []f32)
    : ([][](f32), [][](f32)) =
  let r = length decay
  let d = length left_fw_key[0]
  let combined_key =
    map3 (\lk rk beta ->
      let dk = efla_decay_fn beta
      in map2 (\l ri -> f32.exp dk * l + ri) lk rk
    ) left_fw_key right_fw_key decay
  let combined_val =
    map3 (\lv rv beta ->
      let dk = efla_decay_fn beta
      in map2 (\l ri -> f32.exp dk * l + ri) lv rv
    ) left_fw_val right_fw_val decay
  in (combined_key, combined_val)

entry efla_forward_chunk
    [seq] [d_model] [n_heads] [head_d] [r]
    (hidden: [seq][d_model]f32)
    (qkv_weight: [d_model][n_heads * 3 * head_d]f32)
    (fw_key_init: [n_heads][r][head_d]f32)
    (fw_val_init: [n_heads][r][head_d]f32)
    (decay: [n_heads][r]f32)
    (out_weight: [n_heads * head_d][d_model]f32)
    (norm_scale: [d_model]f32)
    : ([seq][d_model]f32, [n_heads][r][head_d]f32, [n_heads][r][head_d]f32) =
  let normed = map (\h -> rms_norm h norm_scale 1e-6f32) hidden
  let qkv_all = map (\h ->
    map (\w_col -> f32.sum (map2 (*) h w_col)) (transpose qkv_weight)
  ) normed
  let outputs_and_states =
    loop (states_key, states_val, acc_out) =
      (fw_key_init, fw_val_init, replicate seq (replicate d_model 0.0f32))
    for t < seq do
      let qkv_t = qkv_all[t]
      let head_outputs =
        map3 (\head_idx fk fv ->
          let q_start = head_idx * 3 * head_d
          let k_start = q_start + head_d
          let v_start = k_start + head_d
          let q_t = qkv_t[q_start : q_start + head_d]
          let k_t = qkv_t[k_start : k_start + head_d]
          let v_t = qkv_t[v_start : v_start + head_d]
          let read_out = efla_read_memory fk fv q_t
          let (nfk, nfv) = efla_fast_weight_update fk fv decay[head_idx] k_t v_t
          in (read_out, nfk, nfv)
        ) (iota n_heads) states_key states_val
      let new_states_key = map (\(_, nfk, _) -> nfk) head_outputs
      let new_states_val = map (\(_, _, nfv) -> nfv) head_outputs
      let concat_heads = flatten (map (\(ro, _, _) -> ro) head_outputs)
      let out_t = map (\w_col -> f32.sum (map2 (*) concat_heads w_col)) (transpose out_weight)
      let new_acc = acc_out with [t] = out_t
      in (new_states_key, new_states_val, new_acc)
  in (outputs_and_states.2, outputs_and_states.0, outputs_and_states.1)

entry efla_backward_chunk
    [seq] [d_model] [n_heads] [head_d] [r]
    (hidden: [seq][d_model]f32)
    (qkv_weight: [d_model][n_heads * 3 * head_d]f32)
    (fw_key_fwd: [n_heads][r][head_d]f32)
    (fw_val_fwd: [n_heads][r][head_d]f32)
    (decay: [n_heads][r]f32)
    (out_weight: [n_heads * head_d][d_model]f32)
    (norm_scale: [d_model]f32)
    (grad_output: [seq][d_model]f32)
    : ([d_model][n_heads * 3 * head_d]f32,
       [n_heads * head_d][d_model]f32,
       [seq][d_model]f32) =
  let grad_qkv_weight = replicate d_model (replicate (n_heads * 3 * head_d) 0.0f32)
  let grad_out_weight = replicate (n_heads * head_d) (replicate d_model 0.0f32)
  let grad_hidden = replicate seq (replicate d_model 0.0f32)
  in (grad_qkv_weight, grad_out_weight, grad_hidden)

entry swiglu_ffn_forward
    [seq] [d] [ffn_d]
    (hidden: [seq][d]f32)
    (up_weight: [d][ffn_d]f32)
    (gate_weight: [d][ffn_d]f32)
    (down_weight: [ffn_d][d]f32)
    (norm_scale: [d]f32)
    : [seq][d]f32 =
  let normed = map (\h -> rms_norm h norm_scale 1e-6f32) hidden
  let intermediate = map (\h ->
    let up = map (\w -> f32.sum (map2 (*) h w)) (transpose up_weight)
    let gate = map (\w -> f32.sum (map2 (*) h w)) (transpose gate_weight)
    in map2 (\u g -> u * silu g) up gate
  ) normed
  let out = map (\inter ->
    map (\w -> f32.sum (map2 (*) inter w)) (transpose down_weight)
  ) intermediate
  let residual_out = map2 (map2 (+)) hidden out
  in residual_out

entry cross_entropy_loss
    [seq] [vocab]
    (logits: [seq][vocab]f32)
    (targets: [seq]i32)
    : f32 =
  let losses = map2 (\logit_row target ->
    let max_l = f32.maximum logit_row
    let shifted = map (\l -> l - max_l) logit_row
    let exp_sum = f32.sum (map f32.exp shifted)
    let log_sum_exp = max_l + f32.log exp_sum
    in log_sum_exp - logit_row[target]
  ) logits targets
  in f32.sum losses / f32.i64 seq

entry embedding_forward
    [seq] [vocab] [d]
    (tokens: [seq]i32)
    (embed_table: [vocab][d]f32)
    : [seq][d]f32 =
  map (\t -> embed_table[t]) tokens

entry compute_rms_norm_grad
    [seq] [d]
    (hidden: [seq][d]f32)
    (grad_out: [seq][d]f32)
    (scale: [d]f32)
    (eps: f32)
    : ([seq][d]f32, [d]f32) =
  let grad_hidden = map2 (\h go ->
    let sq_sum = f32.sum (map (\xi -> xi * xi) h)
    let rms = f32.sqrt (sq_sum / f32.i64 d + eps)
    let rms_inv = 1.0f32 / rms
    in map2 (\gi si -> gi * si * rms_inv) go scale
  ) hidden grad_out
  let grad_scale = map (\j ->
    f32.sum (map2 (\h go ->
      let sq_sum = f32.sum (map (\xi -> xi * xi) h)
      let rms = f32.sqrt (sq_sum / f32.i64 d + eps)
      in h[j] / rms * go[j]
    ) hidden grad_out)
  ) (iota d)
  in (grad_hidden, grad_scale)
