let fp32_to_e4m3 (x: f32) : u8 =
  let bits = f32.to_bits x
  let sign = (bits >> 31u32) & 1u32
  let exp_bits = (bits >> 23u32) & 0xFFu32
  let mant_bits = bits & 0x7FFFFFu32
  let e4m3_exp_bias: u32 = 7u32
  let fp32_exp_bias: u32 = 127u32
  let biased_exp =
    if exp_bits == 0u32
    then 0u32
    else
      let true_exp = i32.u32 exp_bits - i32.u32 fp32_exp_bias
      let e4m3_biased = true_exp + i32.u32 e4m3_exp_bias
      in if e4m3_biased <= 0i32 then 0u32
         else if e4m3_biased >= 15i32 then 15u32
         else u32.i32 e4m3_biased
  let mant3 = mant_bits >> 20u32
  in u8.u32 ((sign << 7u32) | (biased_exp << 3u32) | mant3)

let e4m3_to_fp32 (x: u8) : f32 =
  let xu = u32.u8 x
  let sign = (xu >> 7u32) & 1u32
  let exp4 = (xu >> 3u32) & 0xFu32
  let mant3 = xu & 0x7u32
  let e4m3_exp_bias: u32 = 7u32
  let fp32_exp_bias: u32 = 127u32
  in if exp4 == 0u32 && mant3 == 0u32
     then 0.0f32
     else
       let true_exp = i32.u32 exp4 - i32.u32 e4m3_exp_bias
       let fp32_biased = u32.i32 (true_exp + i32.u32 fp32_exp_bias)
       let fp32_mant = mant3 << 20u32
       let fp32_bits = (sign << 31u32) | (fp32_biased << 23u32) | fp32_mant
       in f32.from_bits fp32_bits

let fp32_to_e5m2 (x: f32) : u8 =
  let bits = f32.to_bits x
  let sign = (bits >> 31u32) & 1u32
  let exp_bits = (bits >> 23u32) & 0xFFu32
  let mant_bits = bits & 0x7FFFFFu32
  let e5m2_exp_bias: u32 = 15u32
  let fp32_exp_bias: u32 = 127u32
  let biased_exp =
    if exp_bits == 0u32
    then 0u32
    else
      let true_exp = i32.u32 exp_bits - i32.u32 fp32_exp_bias
      let e5m2_biased = true_exp + i32.u32 e5m2_exp_bias
      in if e5m2_biased <= 0i32 then 0u32
         else if e5m2_biased >= 31i32 then 30u32
         else u32.i32 e5m2_biased
  let mant2 = mant_bits >> 21u32
  in u8.u32 ((sign << 7u32) | (biased_exp << 2u32) | mant2)

let e5m2_to_fp32 (x: u8) : f32 =
  let xu = u32.u8 x
  let sign = (xu >> 7u32) & 1u32
  let exp5 = (xu >> 2u32) & 0x1Fu32
  let mant2 = xu & 0x3u32
  let e5m2_exp_bias: u32 = 15u32
  let fp32_exp_bias: u32 = 127u32
  in if exp5 == 0u32 && mant2 == 0u32
     then 0.0f32
     else
       let true_exp = i32.u32 exp5 - i32.u32 e5m2_exp_bias
       let fp32_biased = u32.i32 (true_exp + i32.u32 fp32_exp_bias)
       let fp32_mant = mant2 << 21u32
       let fp32_bits = (sign << 31u32) | (fp32_biased << 23u32) | fp32_mant
       in f32.from_bits fp32_bits

let mxfp8_block_scale (xs: [32]f32) : f32 =
  let max_abs = f32.maximum (map f32.abs xs)
  in if max_abs == 0.0f32 then 1.0f32
     else max_abs / 448.0f32

entry quantize_mxfp8_e4m3 [n] (xs: [n]f32) : ([n]u8, [n]u8) =
  let num_blocks = (n + 31) / 32
  let padded_size = num_blocks * 32
  let padded = xs ++ replicate (padded_size - n) 0.0f32
  let blocks = unflatten num_blocks 32 padded
  let scales = map mxfp8_block_scale blocks
  let quantized = map2 (\block scale ->
    map (\x -> fp32_to_e4m3 (x / scale)) block
  ) blocks scales
  let flat_quantized = flatten quantized
  let flat_scales_per_elem = flatten (map (\(s, _) ->
    replicate 32 (fp32_to_e4m3 s)
  ) (zip scales (iota num_blocks)))
  in (flat_quantized[:n], flat_scales_per_elem[:n])

entry dequantize_mxfp8_e4m3 [n] (quantized: [n]u8) (scale_bytes: [n]u8) : [n]f32 =
  map2 (\q s ->
    e4m3_to_fp32 q * e4m3_to_fp32 s
  ) quantized scale_bytes

entry quantize_mxfp8_e5m2 [n] (xs: [n]f32) : ([n]u8, [n]u8) =
  let num_blocks = (n + 31) / 32
  let padded_size = num_blocks * 32
  let padded = xs ++ replicate (padded_size - n) 0.0f32
  let blocks = unflatten num_blocks 32 padded
  let scales = map mxfp8_block_scale blocks
  let quantized = map2 (\block scale ->
    map (\x -> fp32_to_e5m2 (x / scale)) block
  ) blocks scales
  let flat_quantized = flatten quantized
  let flat_scales_per_elem = flatten (map (\(s, _) ->
    replicate 32 (fp32_to_e5m2 s)
  ) (zip scales (iota num_blocks)))
  in (flat_quantized[:n], flat_scales_per_elem[:n])

entry dequantize_mxfp8_e5m2 [n] (quantized: [n]u8) (scale_bytes: [n]u8) : [n]f32 =
  map2 (\q s ->
    e5m2_to_fp32 q * e5m2_to_fp32 s
  ) quantized scale_bytes

entry mxfp8_matmul_e4m3
    [m] [k] [n]
    (a_quant: [m][k]u8)
    (a_scales: [m][k]u8)
    (b_quant: [k][n]u8)
    (b_scales: [k][n]u8)
    : [m][n]f32 =
  map (\i ->
    map (\j ->
      f32.sum (map2 (\ki kj ->
        let a_val = e4m3_to_fp32 a_quant[i][ki] * e4m3_to_fp32 a_scales[i][ki]
        let b_val = e4m3_to_fp32 b_quant[ki][j] * e4m3_to_fp32 b_scales[ki][j]
        in a_val * b_val
      ) (iota k) (iota k))
    ) (iota n)
  ) (iota m)

entry fp4_pack_two (x: f32) (y: f32) : u8 =
  let sign_x = if x < 0.0f32 then 1u8 else 0u8
  let sign_y = if y < 0.0f32 then 1u8 else 0u8
  let abs_x = f32.abs x
  let abs_y = f32.abs y
  let quant_fp4 (v: f32) : u8 =
    if v >= 4.0f32 then 6u8
    else if v >= 2.0f32 then 5u8
    else if v >= 1.0f32 then 4u8
    else if v >= 0.5f32 then 3u8
    else if v >= 0.25f32 then 2u8
    else if v >= 0.0625f32 then 1u8
    else 0u8
  let nibble_x = quant_fp4 abs_x | (sign_x << 3u8)
  let nibble_y = quant_fp4 abs_y | (sign_y << 3u8)
  in (nibble_x << 4u8) | nibble_y

let fp4_dequant (nibble: u8) : f32 =
  let sign = if (nibble & 8u8) != 0u8 then -1.0f32 else 1.0f32
  let mag = nibble & 7u8
  let abs_val =
    if mag == 0u8 then 0.0f32
    else if mag == 1u8 then 0.0625f32
    else if mag == 2u8 then 0.25f32
    else if mag == 3u8 then 0.5f32
    else if mag == 4u8 then 1.0f32
    else if mag == 5u8 then 2.0f32
    else if mag == 6u8 then 4.0f32
    else 8.0f32
  in sign * abs_val

entry fp4_unpack (packed: u8) : (f32, f32) =
  let nibble_x = (packed >> 4u8) & 0xFu8
  let nibble_y = packed & 0xFu8
  in (fp4_dequant nibble_x, fp4_dequant nibble_y)

entry quantize_weights_fp4 [n] (weights: [n]f32) : ([n / 2]u8, f32) =
  let max_abs = f32.maximum (map f32.abs weights)
  let scale = if max_abs == 0.0f32 then 1.0f32 else max_abs / 4.0f32
  let scaled = map (\w -> w / scale) weights
  let pairs = unflatten (n / 2) 2 scaled
  let packed = map (\pair -> fp4_pack_two pair[0] pair[1]) pairs
  in (packed, scale)

entry dequantize_weights_fp4 [n] (packed: [n]u8) (scale: f32) : [n * 2]f32 =
  let unpacked = map fp4_unpack packed
  let flat = flatten (map (\(a, b) -> [a * scale, b * scale]) unpacked)
  in flat

entry compute_absmax_scale [n] (xs: [n]f32) (target_max: f32) : f32 =
  let max_abs = f32.maximum (map f32.abs xs)
  in if max_abs == 0.0f32 then 1.0f32 else max_abs / target_max

entry apply_dynamic_loss_scale [n] (grads: [n]f32) (loss_scale: f32) : [n]f32 =
  map (\g -> g / loss_scale) grads

entry check_grad_overflow [n] (grads: [n]f32) : bool =
  any (\g -> !(f32.isfinite g)) grads

entry clip_grad_norm [n] (grads: [n]f32) (max_norm: f32) : [n]f32 =
  let norm_sq = f32.sum (map (\g -> g * g) grads)
  let norm = f32.sqrt norm_sq
  in if norm > max_norm
     then map (\g -> g * max_norm / norm) grads
     else grads
