        capture_output=True,
        text=True,
        env=env,
    )
    if ret.returncode != 0:
        print("ZIG BUILD STDERR:", ret.stderr)
        raise RuntimeError("Zig build failed")
    print(ret.stdout)

    print("[4/5] Preparing data directories...")
    pathlib.Path("/mnt/nfs/checkpoints").mkdir(parents=True, exist_ok=True)
    pathlib.Path("/mnt/data").mkdir(parents=True, exist_ok=True)

    print("[5/5] Launching training...")
    train_cmd = [str(workspace / "zig-out" / "bin" / "underdog-llm")]
    if resume_from_step > 0:
        train_cmd += ["--resume", str(resume_from_step)]

    env["LD_PRELOAD"] = str(workspace / "kernels" / "libcudakernels.so")
    env["CUDA_VISIBLE_DEVICES"] = "0,1,2,3,4,5,6,7"
    env["OMP_NUM_THREADS"] = "8"
    env["MALLOC_TRIM_THRESHOLD_"] = "0"

    process = subprocess.Popen(
        train_cmd,
        cwd=workspace,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        bufsize=1,
    )

    for line in process.stdout:
        print(line, end="", flush=True)

    process.wait()
    if process.returncode != 0:
        raise RuntimeError(f"Training process exited with code {process.returncode}")

    print("Training completed successfully.")
    return {"status": "complete"}


