__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__device__ __forceinline__ float block_reduce_sum(float val) {
    __shared__ float smem[32];
    int lane = threadIdx.x % warpSize;
    int wid  = threadIdx.x / warpSize;
    val = warp_reduce_sum(val);
    if (lane == 0) smem[wid] = val;
    __syncthreads();
    val = (threadIdx.x < (blockDim.x / warpSize)) ? smem[lane] : 0.0f;
    if (wid == 0) val = warp_reduce_sum(val);
    return val;
}

__global__ void embedding_forward_kernel(
    const uint32_t* __restrict__ tokens,
    const float* __restrict__ embed_table,
    float* __restrict__ output,
    int seq_len,
    unsigned int model_dim
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= seq_len || d >= (int)model_dim) return;
    uint32_t tok_id = tokens[t];
    output[t * model_dim + d] = embed_table[tok_id * model_dim + d];
}

