}

__global__ void rms_norm_kernel(
    float* __restrict__ hidden,
    const float* __restrict__ scale,
    const float* __restrict__ bias,
    int seq_len,
    unsigned int model_dim,
    float eps
) {
    int t = blockIdx.x;
    if (t >= seq_len) return;

    float* x = hidden + t * model_dim;
    __shared__ float smem[1024];

    float thread_sum = 0.0f;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        float v = x[d];
        thread_sum += v * v;
    }

    smem[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride)
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        __syncthreads();
    }

    float rms = sqrtf(smem[0] / (float)model_dim + eps);
    float rms_inv = 1.0f / rms;

    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        x[d] = x[d] * rms_inv * scale[d] + bias[d];
    }
}

extern "C" void launchRMSNorm(
    float* hidden,
    float* scale,
    float* bias,
    int seq_len,
    unsigned int model_dim,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = min((int)model_dim, 1024);
    rms_norm_kernel<<<seq_len, threads, 0, stream>>>(
        hidden, scale, bias, seq_len, model_dim, 1e-6f
    );
}

__device__ __forceinline__ float efla_softplus(float x) {
    return log1pf(expf(x));
}

__device__ __forceinline__ float efla_decay(float d) {
    return -efla_softplus(d);
}

__global__ void efla_associative_scan_kernel(
    const float* __restrict__ hidden_in,
    const float* __restrict__ qkv_weight,
    const float* __restrict__ fw_key,
    const float* __restrict__ fw_val,
    const float* __restrict__ fw_decay,
    const float* __restrict__ out_weight,
    float* __restrict__ hidden_out,
    int seq_len,
    unsigned int model_dim,
    unsigned int num_heads,
    unsigned int head_dim,
    unsigned int low_rank
) {
    int head = blockIdx.x;
    if (head >= (int)num_heads) return;

    extern __shared__ float smem_efla[];
    float* s_fw_key = smem_efla;
    float* s_fw_val = s_fw_key + low_rank * head_dim;
    float* s_decay  = s_fw_val + low_rank * head_dim;
    float* s_qkv    = s_decay  + low_rank;
    float* s_out    = s_qkv + 3 * head_dim;

    int r = low_rank;
    int hd = head_dim;

    for (int ri = threadIdx.x; ri < (int)(r * hd); ri += blockDim.x) {
        s_fw_key[ri] = fw_key[head * r * hd + ri];
        s_fw_val[ri] = fw_val[head * r * hd + ri];
    }
    for (int ri = threadIdx.x; ri < (int)r; ri += blockDim.x) {
        s_decay[ri] = fw_decay[head * r + ri];
    }
    __syncthreads();

    for (int t = 0; t < seq_len; t++) {
        const float* h_t = hidden_in + t * model_dim;

        for (int qi = threadIdx.x; qi < 3 * hd; qi += blockDim.x) {
            float acc = 0.0f;
            int col = head * 3 * hd + qi;
            for (int d = 0; d < (int)model_dim; d++) {
                acc += h_t[d] * qkv_weight[d * num_heads * 3 * hd + col];
            }
            s_qkv[qi] = acc;
        }
        __syncthreads();

        float* q_t = s_qkv;
        float* k_t = s_qkv + hd;
        float* v_t = s_qkv + 2 * hd;

        for (int ri = threadIdx.x; ri < (int)r; ri += blockDim.x) {
            float beta = s_decay[ri];
            float dk = efla_decay(beta);
            float ek = expf(dk);
            for (int di = 0; di < hd; di++) {
                s_fw_key[ri * hd + di] = ek * s_fw_key[ri * hd + di] + k_t[di];
                s_fw_val[ri * hd + di] = ek * s_fw_val[ri * hd + di] + v_t[di];
            }
        }
        __syncthreads();

        float max_score = -CUDART_INF_F;
        for (int ri = 0; ri < (int)r; ri++) {
            float score = 0.0f;
            for (int di = 0; di < hd; di++) {
                score += s_fw_key[ri * hd + di] * q_t[di];
            }
            if (score > max_score) max_score = score;
        }

        float sum_exp = 0.0f;
        for (int ri = 0; ri < (int)r; ri++) {
            float score = 0.0f;
            for (int di = 0; di < hd; di++) {
                score += s_fw_key[ri * hd + di] * q_t[di];
            }
            sum_exp += expf(score - max_score);
        }

        for (int di = threadIdx.x; di < hd; di += blockDim.x) {
            float out_di = 0.0f;
            for (int ri = 0; ri < (int)r; ri++) {
                float score = 0.0f;
                for (int dj = 0; dj < hd; dj++) {
                    score += s_fw_key[ri * hd + dj] * q_t[dj];
                }
                float w = expf(score - max_score) / (sum_exp + 1e-8f);
                out_di += w * s_fw_val[ri * hd + di];
            }
            s_out[di] = out_di;
        }
        __syncthreads();

        float* h_out_t = hidden_out + t * model_dim;
        for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
            float acc = 0.0f;
            for (int di = 0; di < hd; di++) {
                int row = head * hd + di;
                acc += s_out[di] * out_weight[row * model_dim + d];
            }
            atomicAdd(&h_out_t[d], acc);
        }
        __syncthreads();
    }

    for (int ri = threadIdx.x; ri < (int)(r * hd); ri += blockDim.x) {
        const_cast<float*>(fw_key)[head * r * hd + ri] = s_fw_key[ri];
        const_cast<float*>(fw_val)[head * r * hd + ri] = s_fw_val[ri];
    }
}

extern "C" void launchEFLAAssociativeScan(
    float* hidden,
    float* qkv_weight,
    float* fw_key,
    float* fw_val,
    float* fw_decay,
    float* out_weight,
    int seq_len,
    unsigned int model_dim,
    unsigned int num_heads,
    unsigned int head_dim,
    unsigned int low_rank,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);

    float* hidden_out;
    size_t out_size = (size_t)seq_len * model_dim * sizeof(float);
    cudaMalloc(&hidden_out, out_size);
    cudaMemset(hidden_out, 0, out_size);

    int threads = 128;
    size_t smem = (2 * low_rank * head_dim + low_rank + 3 * head_dim + head_dim) * sizeof(float);

    efla_associative_scan_kernel<<<num_heads, threads, smem, stream>>>(
        hidden, qkv_weight, fw_key, fw_val, fw_decay, out_weight,
        hidden_out, seq_len, model_dim, num_heads, head_dim, low_rank
    );

    cudaMemcpyAsync(hidden, hidden_out, out_size, cudaMemcpyDeviceToDevice, stream);
    cudaStreamSynchronize(stream);
    cudaFree(hidden_out);
}

__device__ __forceinline__ float silu_fwd(float x) {
    return x / (1.0f + expf(-x));
}

__global__ void swiglu_ffn_kernel(
    float* __restrict__ hidden,
    const float* __restrict__ ffn_up,
    const float* __restrict__ ffn_gate,
    const float* __restrict__ ffn_down,
    int seq_len,
    unsigned int model_dim,
    unsigned int ffn_dim
) {
    int t = blockIdx.x;
    if (t >= seq_len) return;

    extern __shared__ float smem_ffn[];
    float* s_intermediate = smem_ffn;
    float* s_hidden_in = s_intermediate + ffn_dim;

    const float* h_t = hidden + t * model_dim;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x)
        s_hidden_in[d] = h_t[d];
    __syncthreads();

    for (int f = threadIdx.x; f < (int)ffn_dim; f += blockDim.x) {
        float up_val = 0.0f;
        float gate_val = 0.0f;
        for (int d = 0; d < (int)model_dim; d++) {
            float hd = s_hidden_in[d];
            up_val   += hd * ffn_up[d * ffn_dim + f];
            gate_val += hd * ffn_gate[d * ffn_dim + f];
        }
        s_intermediate[f] = up_val * silu_fwd(gate_val);
    }
    __syncthreads();

    float* h_out_t = hidden + t * model_dim;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        float acc = 0.0f;
        for (int f = 0; f < (int)ffn_dim; f++) {
            acc += s_intermediate[f] * ffn_down[f * model_dim + d];
        }
        h_out_t[d] = s_hidden_in[d] + acc;
    }
}

extern "C" void launchSwiGLUFFN(
    float* hidden,
    float* ffn_up,
    float* ffn_gate,
    float* ffn_down,
    int seq_len,
    unsigned int model_dim,
    unsigned int ffn_dim,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = 256;
    size_t smem = (ffn_dim + model_dim) * sizeof(float);
    swiglu_ffn_kernel<<<seq_len, threads, smem, stream>>>(
        hidden, ffn_up, ffn_gate, ffn_down, seq_len, model_dim, ffn_dim
    );
}

__global__ void lm_head_and_loss_kernel(
    const float* __restrict__ hidden,
    const float* __restrict__ lm_head,
    const uint32_t* __restrict__ target_tokens,
    float* __restrict__ logits_out,
    float* __restrict__ loss_out,
    int seq_len,
    unsigned int model_dim,
    unsigned int vocab_size
) {
    int t = blockIdx.x;
    if (t >= seq_len - 1) return;

    const float* h_t = hidden + t * model_dim;
    float* logits_t = logits_out + t * vocab_size;

    for (int v = threadIdx.x; v < (int)vocab_size; v += blockDim.x) {
        float acc = 0.0f;
        for (int d = 0; d < (int)model_dim; d++) {
            acc += h_t[d] * lm_head[v * model_dim + d];
        }
        logits_t[v] = acc;
    }
    __syncthreads();

    __shared__ float s_max;
    __shared__ float s_sum;

    if (threadIdx.x == 0) {
        s_max = -CUDART_INF_F;
        for (int v = 0; v < (int)vocab_size; v++) {
            if (logits_t[v] > s_max) s_max = logits_t[v];
        }
        s_sum = 0.0f;
        for (int v = 0; v < (int)vocab_size; v++) {
            s_sum += expf(logits_t[v] - s_max);
        }
        uint32_t target = target_tokens[t + 1];
        float log_prob = logits_t[target] - s_max - logf(s_sum + 1e-10f);
        atomicAdd(loss_out, -log_prob / (float)(seq_len - 1));
    }
}

extern "C" void launchLMHeadAndLoss(
    float* hidden,
    float* lm_head,
    uint32_t* target_tokens,
    float* logits_out,
    float* loss_out,
    int seq_len,
    unsigned int model_dim,
    unsigned int vocab_size,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    cudaMemsetAsync(loss_out, 0, sizeof(float), stream);
    int threads = 256;
    lm_head_and_loss_kernel<<<seq_len, threads, 0, stream>>>(
        hidden, lm_head, target_tokens, logits_out, loss_out,
        seq_len, model_dim, vocab_size
    );
}

__global__ void gradient_clip_kernel(
    float* __restrict__ grads,
    size_t num_elements,
    float max_norm
) {
    extern __shared__ float smem_gc[];

    float thread_sq = 0.0f;
    for (size_t i = threadIdx.x + blockIdx.x * blockDim.x;
         i < num_elements;
         i += blockDim.x * gridDim.x) {
        thread_sq += grads[i] * grads[i];
    }

    smem_gc[threadIdx.x] = thread_sq;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_gc[threadIdx.x] += smem_gc[threadIdx.x + s];
        __syncthreads();
    }

    __shared__ float total_norm_sq;
    if (threadIdx.x == 0) atomicAdd(&total_norm_sq, smem_gc[0]);
    __syncthreads();

    float norm = sqrtf(total_norm_sq);
    if (norm > max_norm) {
        float scale = max_norm / (norm + 1e-8f);
        for (size_t i = threadIdx.x + blockIdx.x * blockDim.x;
             i < num_elements;
             i += blockDim.x * gridDim.x) {
            grads[i] *= scale;
        }
    }
}

extern "C" void launchGradientClip(
    float* grads,
    size_t num_elements,
    float max_norm,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = 512;
    int blocks = min((int)((num_elements + threads - 1) / threads), 1024);
    size_t smem = threads * sizeof(float);
    gradient_clip_kernel<<<blocks, threads, smem, stream>>>(
        grads, num_elements, max_norm
    );
}
