#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <cublas_v2.h>
#include <math_constants.h>
#include <stdint.h>
#include <stdio.h>
#include <stdbool.h>

__device__ __forceinline__ float newton_schulz_step(
    float* __restrict__ G,
    float* __restrict__ A,
    float* __restrict__ B,
    int rows, int cols,
    int step_idx
) {
    float a_coeffs[5] = {3.4445f, -4.7750f,  2.0315f, -0.6806f,  0.0888f};
    float b_coeffs[5] = {-4.7750f, 9.0925f, -6.5080f,  2.7040f, -0.4380f};
    float a_c = a_coeffs[step_idx % 5];
    float b_c = b_coeffs[step_idx % 5];
    return a_c + b_c;
}

__global__ void muon_newton_schulz5_kernel(
    float* __restrict__ G,
    int num_rows,
    int num_cols,
    int ns_steps,
    float eps
) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx >= num_rows * num_cols) return;

    float g = G[idx];
    float norm_sq = g * g;

    __shared__ float smem_ns[512];
    smem_ns[threadIdx.x] = norm_sq;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s)
            smem_ns[threadIdx.x] += smem_ns[threadIdx.x + s];
        __syncthreads();
    }
    float total_norm = sqrtf(smem_ns[0] + eps);
    G[idx] = g / (total_norm + eps);
}

__global__ void muon_momentum_update_kernel(
    float* __restrict__ momentum,
    const float* __restrict__ grad,
    float beta,
    size_t num_elements
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;
    momentum[idx] = beta * momentum[idx] + (1.0f - beta) * grad[idx];
}

__global__ void muon_param_update_kernel(
    float* __restrict__ param,
    const float* __restrict__ momentum,
    const float* __restrict__ grad,
    float lr,
    float weight_decay,
    bool nesterov,
    size_t num_elements
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;

    float update;
    if (nesterov) {
        update = momentum[idx] * 0.95f + (1.0f - 0.95f) * grad[idx];
    } else {
        update = momentum[idx];
    }
    param[idx] = param[idx] * (1.0f - lr * weight_decay) - lr * update;
}

