__global__ void lion_step_kernel(
    float* __restrict__ param,
    float* __restrict__ momentum,
    const float* __restrict__ grad,
    float lr,
    float beta1,
    float beta2,
    float weight_decay,
    size_t num_elements
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;

    float m = momentum[idx];
    float g = grad[idx];

    float update = beta1 * m + (1.0f - beta1) * g;
    float sign_update = (update > 0.0f) ? 1.0f : ((update < 0.0f) ? -1.0f : 0.0f);

    param[idx] = param[idx] * (1.0f - lr * weight_decay) - lr * sign_update;

    momentum[idx] = beta2 * m + (1.0f - beta2) * g;
}

extern "C" void launchLionStep(
