    );
}

__global__ void quantize_fp8_e4m3_kernel(
    const float* __restrict__ input,
    uint8_t* __restrict__ output,
    float* __restrict__ scale_out,
    size_t num_elements,
    int block_size
) {
    int block_id = blockIdx.x;
    int start = block_id * block_size;
    int end = min(start + block_size, (int)num_elements);

    __shared__ float smem_q[512];
    float thread_max = 0.0f;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float v = fabsf(input[i]);
        if (v > thread_max) thread_max = v;
    }
    smem_q[threadIdx.x] = thread_max;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s && smem_q[threadIdx.x + s] > smem_q[threadIdx.x])
            smem_q[threadIdx.x] = smem_q[threadIdx.x + s];
        __syncthreads();
    }

    float max_val = smem_q[0];
    float scale = (max_val == 0.0f) ? 1.0f : max_val / 448.0f;
    if (threadIdx.x == 0) scale_out[block_id] = scale;
    __syncthreads();

    float inv_scale = 1.0f / scale;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float v = input[i] * inv_scale;
        v = fmaxf(-448.0f, fminf(448.0f, v));

        uint32_t bits = __float_as_uint(v);
        uint32_t sign = (bits >> 31) & 1;
        uint32_t exp_bits = (bits >> 23) & 0xFF;
        uint32_t mant_bits = bits & 0x7FFFFF;

        uint32_t e4m3_exp_bias = 7;
        uint32_t fp32_exp_bias = 127;
        uint32_t biased_exp = 0;
        if (exp_bits != 0) {
            int true_exp = (int)exp_bits - (int)fp32_exp_bias;
            int e4m3_biased = true_exp + (int)e4m3_exp_bias;
            if (e4m3_biased <= 0) biased_exp = 0;
            else if (e4m3_biased >= 15) biased_exp = 15;
            else biased_exp = (uint32_t)e4m3_biased;
        }
        uint32_t mant3 = mant_bits >> 20;
        output[i] = (uint8_t)((sign << 7) | (biased_exp << 3) | mant3);
    }
}

__global__ void dequantize_fp8_e4m3_kernel(
    const uint8_t* __restrict__ input,
    const float* __restrict__ scales,
    float* __restrict__ output,
    size_t num_elements,
    int block_size
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;

    uint8_t q = input[idx];
    uint32_t xu = (uint32_t)q;
    uint32_t sign = (xu >> 7) & 1;
    uint32_t exp4 = (xu >> 3) & 0xF;
    uint32_t mant3 = xu & 0x7;

    float val;
    if (exp4 == 0 && mant3 == 0) {
        val = 0.0f;
    } else {
        uint32_t e4m3_exp_bias = 7;
        uint32_t fp32_exp_bias = 127;
        int true_exp = (int)exp4 - (int)e4m3_exp_bias;
        uint32_t fp32_biased = (uint32_t)(true_exp + (int)fp32_exp_bias);
        uint32_t fp32_mant = mant3 << 20;
        uint32_t fp32_bits = (sign << 31) | (fp32_biased << 23) | fp32_mant;
        val = __uint_as_float(fp32_bits);
    }

    int block_id = (int)(idx / block_size);
    output[idx] = val * scales[block_id];
}

extern "C" void launchQuantizeFP8E4M3(
