__global__ void adam_w_fp8_state_kernel(
    float* __restrict__ param,
    uint8_t* __restrict__ m1_quant,
    uint8_t* __restrict__ m2_quant,
    float* __restrict__ m1_scale,
    float* __restrict__ m2_scale,
    const float* __restrict__ grad,
    float lr,
    float beta1,
    float beta2,
    float weight_decay,
    float eps,
    uint64_t step,
    size_t num_elements,
    int block_size
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;

    int blk = (int)(idx / block_size);

    uint8_t m1q = m1_quant[idx];
    uint8_t m2q = m2_quant[idx];

    uint32_t m1xu = (uint32_t)m1q;
    uint32_t sign1 = (m1xu >> 7) & 1;
    uint32_t exp1_4 = (m1xu >> 3) & 0xF;
    uint32_t mant1_3 = m1xu & 0x7;
    float m1_val = 0.0f;
    if (!(exp1_4 == 0 && mant1_3 == 0)) {
        int true_exp1 = (int)exp1_4 - 7;
        uint32_t fp32_b1 = (uint32_t)(true_exp1 + 127);
        uint32_t fp32_bits1 = (sign1 << 31) | (fp32_b1 << 23) | (mant1_3 << 20);
        m1_val = __uint_as_float(fp32_bits1);
    }
    m1_val *= m1_scale[blk];

    uint32_t m2xu = (uint32_t)m2q;
    uint32_t exp2_4 = (m2xu >> 3) & 0xF;
    uint32_t mant2_3 = m2xu & 0x7;
    float m2_val = 0.0f;
    if (!(exp2_4 == 0 && mant2_3 == 0)) {
        int true_exp2 = (int)exp2_4 - 7;
        uint32_t fp32_b2 = (uint32_t)(true_exp2 + 127);
        uint32_t fp32_bits2 = (fp32_b2 << 23) | (mant2_3 << 20);
        m2_val = __uint_as_float(fp32_bits2);
    }
    m2_val *= m2_scale[blk];

    float g = grad[idx];
    float new_m1 = beta1 * m1_val + (1.0f - beta1) * g;
    float new_m2 = beta2 * m2_val + (1.0f - beta2) * g * g;

    float bc1 = 1.0f - powf(beta1, (float)step);
    float bc2 = 1.0f - powf(beta2, (float)step);
    float m1_hat = new_m1 / bc1;
    float m2_hat = new_m2 / bc2;

    param[idx] = param[idx] * (1.0f - lr * weight_decay) -
                 lr * m1_hat / (sqrtf(m2_hat) + eps);

    float abs_m1 = fabsf(new_m1);
    float scale1 = (abs_m1 == 0.0f) ? 1.0f : abs_m1 / 448.0f;
    float inv_s1 = 1.0f / scale1;
    float v1 = new_m1 * inv_s1;
    v1 = fmaxf(-448.0f, fminf(448.0f, v1));
    uint32_t b1 = __float_as_uint(v1);
    uint32_t sg1 = (b1 >> 31) & 1;
    uint32_t e1 = (b1 >> 23) & 0xFF;
    uint32_t mn1 = b1 & 0x7FFFFF;
    uint32_t be1 = 0;
    if (e1 != 0) {
        int te1 = (int)e1 - 127;
        int ke1 = te1 + 7;
        if (ke1 <= 0) be1 = 0;
        else if (ke1 >= 15) be1 = 15;
        else be1 = (uint32_t)ke1;
    }
    m1_quant[idx] = (uint8_t)((sg1 << 7) | (be1 << 3) | (mn1 >> 20));
    atomicExch(&m1_scale[blk], scale1);

    float abs_m2 = fabsf(new_m2);
    float scale2 = (abs_m2 == 0.0f) ? 1.0f : abs_m2 / 448.0f;
    float inv_s2 = 1.0f / scale2;
    float v2 = new_m2 * inv_s2;
    v2 = fmaxf(0.0f, fminf(448.0f, v2));
    uint32_t b2 = __float_as_uint(v2);
    uint32_t e2 = (b2 >> 23) & 0xFF;
    uint32_t mn2 = b2 & 0x7FFFFF;
    uint32_t be2 = 0;
    if (e2 != 0) {
        int te2 = (int)e2 - 127;
        int ke2 = te2 + 7;
        if (ke2 <= 0) be2 = 0;
        else if (ke2 >= 15) be2 = 15;
        else be2 = (uint32_t)ke2;
    }
    m2_quant[idx] = (uint8_t)((be2 << 3) | (mn2 >> 20));
    atomicExch(&m2_scale[blk], scale2);
}

extern "C" void launchAdamWFP8States(
    float* param,
    uint8_t* m1_quant,
    uint8_t* m2_quant,
    float* m1_scale,
    float* m2_scale,
    float* grad,
    float lr,
    float beta1,
    float beta2,
