__global__ void embedding_backward_kernel(
    const uint32_t* __restrict__ tokens,
    const float* __restrict__ grad_output,
    float* __restrict__ grad_embed,
    int seq_len,
    unsigned int model_dim
) {
    int t = blockIdx.x;
    if (t >= seq_len) return;
    uint32_t tok_id = tokens[t];
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        atomicAdd(&grad_embed[tok_id * model_dim + d], grad_output[t * model_dim + d]);
    }
}

