__global__ void rms_norm_backward_kernel(
    const float* __restrict__ hidden_fwd,
    const float* __restrict__ grad_out,
    const float* __restrict__ scale,
    float* __restrict__ grad_hidden,
    float* __restrict__ grad_scale,
    int seq_len,
    unsigned int model_dim,
    float eps
) {
    int t = blockIdx.x;
    if (t >= seq_len) return;

    const float* h = hidden_fwd + t * model_dim;
    const float* go = grad_out + t * model_dim;
    float* gh = grad_hidden + t * model_dim;

    __shared__ float smem_rn[1024];

    float sq_sum = 0.0f;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x)
        sq_sum += h[d] * h[d];
    smem_rn[threadIdx.x] = sq_sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_rn[threadIdx.x] += smem_rn[threadIdx.x + s];
        __syncthreads();
    }
    float rms = sqrtf(smem_rn[0] / (float)model_dim + eps);
    float rms_inv = 1.0f / rms;

    float dot_gos = 0.0f;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x)
        dot_gos += go[d] * scale[d] * h[d];
    smem_rn[threadIdx.x] = dot_gos;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_rn[threadIdx.x] += smem_rn[threadIdx.x + s];
        __syncthreads();
    }
    float sum_dot = smem_rn[0];

    float inv_n = 1.0f / (float)model_dim;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        float dL_dx = rms_inv * scale[d] * go[d] -
                      rms_inv * h[d] * rms_inv * rms_inv * sum_dot * h[d] * inv_n;
        gh[d] = dL_dx;
        atomicAdd(&grad_scale[d], go[d] * h[d] * rms_inv);
    }
}

extern "C" void launchRMSNormBackward(
    float* hidden_fwd,
    float* grad_out,
    float* scale,
    float* grad_hidden,
    float* grad_scale,
    int seq_len,
    unsigned int model_dim,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = min((int)model_dim, 1024);
    rms_norm_backward_kernel<<<seq_len, threads, 0, stream>>>(
        hidden_fwd, grad_out, scale, grad_hidden, grad_scale,
        seq_len, model_dim, 1e-6f
    );
}

__global__ void cross_entropy_backward_kernel(
    float* __restrict__ logits,
    const uint32_t* __restrict__ targets,
    float* __restrict__ grad_logits,
    int seq_len,
    unsigned int vocab_size
) {
    int t = blockIdx.x;
    if (t >= seq_len - 1) return;

    float* logits_t = logits + t * vocab_size;
    float* grad_t = grad_logits + t * vocab_size;

    __shared__ float smem_ce[512];

    float max_logit = -CUDART_INF_F;
    for (int v = threadIdx.x; v < (int)vocab_size; v += blockDim.x) {
        if (logits_t[v] > max_logit) max_logit = logits_t[v];
    }
    smem_ce[threadIdx.x] = max_logit;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s && smem_ce[threadIdx.x + s] > smem_ce[threadIdx.x])
            smem_ce[threadIdx.x] = smem_ce[threadIdx.x + s];
        __syncthreads();
    }
    float global_max = smem_ce[0];

    float sum_exp = 0.0f;
    for (int v = threadIdx.x; v < (int)vocab_size; v += blockDim.x)
        sum_exp += expf(logits_t[v] - global_max);
    smem_ce[threadIdx.x] = sum_exp;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_ce[threadIdx.x] += smem_ce[threadIdx.x + s];
        __syncthreads();
    }
    float total_exp = smem_ce[0];

    uint32_t target = targets[t + 1];
    float inv_seq = 1.0f / (float)(seq_len - 1);
    for (int v = threadIdx.x; v < (int)vocab_size; v += blockDim.x) {
        float softmax_v = expf(logits_t[v] - global_max) / (total_exp + 1e-10f);
        float indicator = ((uint32_t)v == target) ? 1.0f : 0.0f;
        grad_t[v] = (softmax_v - indicator) * inv_seq;
    }
}

extern "C" void launchCrossEntropyBackward(
    float* logits,
    uint32_t* targets,
    float* grad_logits,
    int seq_len,
    unsigned int vocab_size,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = 512;
    cross_entropy_backward_kernel<<<seq_len, threads, 0, stream>>>(
        logits, targets, grad_logits, seq_len, vocab_size
    );
}

__global__ void apply_rotary_emb_kernel(
    float* __restrict__ qkv,
    int seq_len,
    int num_heads,
    int head_dim,
    int offset
) {
    int t = blockIdx.x;
    int h = blockIdx.y;
    if (t >= seq_len || h >= num_heads) return;

    float* q = qkv + t * num_heads * 3 * head_dim + h * 3 * head_dim;
    float* k = q + head_dim;

    int half_hd = head_dim / 2;
    for (int d = threadIdx.x; d < half_hd; d += blockDim.x) {
        float theta = powf(10000.0f, -2.0f * (float)d / (float)head_dim);
        float angle = (float)(t + offset) * theta;
        float cos_a = cosf(angle);
        float sin_a = sinf(angle);

        float q0 = q[d];
        float q1 = q[d + half_hd];
        q[d]          = q0 * cos_a - q1 * sin_a;
        q[d + half_hd] = q0 * sin_a + q1 * cos_a;

        float k0 = k[d];
        float k1 = k[d + half_hd];
        k[d]          = k0 * cos_a - k1 * sin_a;
        k[d + half_hd] = k0 * sin_a + k1 * cos_a;
    }
}

extern "C" void launchRotaryEmbedding(
    float* qkv,
    int seq_len,
    int num_heads,
    int head_dim,
    int offset,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    dim3 grid(seq_len, num_heads);
    int threads = min(head_dim / 2, 256);
    apply_rotary_emb_kernel<<<grid, threads, 0, stream>>>(
        qkv, seq_len, num_heads, head_dim, offset
    );
}

__global__ void layer_norm_kernel(
    float* __restrict__ hidden,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int seq_len,
    unsigned int model_dim,
    float eps
) {
    int t = blockIdx.x;
    if (t >= seq_len) return;

    float* x = hidden + t * model_dim;
    __shared__ float smem_ln[1024];

    float sum = 0.0f;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x)
        sum += x[d];
    smem_ln[threadIdx.x] = sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_ln[threadIdx.x] += smem_ln[threadIdx.x + s];
        __syncthreads();
    }
    float mean = smem_ln[0] / (float)model_dim;

    float var_sum = 0.0f;
    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        float diff = x[d] - mean;
        var_sum += diff * diff;
    }
    smem_ln[threadIdx.x] = var_sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) smem_ln[threadIdx.x] += smem_ln[threadIdx.x + s];
        __syncthreads();
    }
    float variance = smem_ln[0] / (float)model_dim;
    float inv_std = 1.0f / sqrtf(variance + eps);

    for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x) {
        x[d] = (x[d] - mean) * inv_std * weight[d] + bias[d];
    }
}

extern "C" void launchLayerNorm(
    float* hidden,
    float* weight,
    float* bias,
    int seq_len,
    unsigned int model_dim,
    int device_id,
    cudaStream_t stream
) {
    cudaSetDevice(device_id);
    int threads = min((int)model_dim, 1024);
    layer_norm_kernel<<<seq_len, threads, 0, stream>>>(
        hidden, weight, bias, seq_len, model_dim, 1e-5f
    );
}

__global__ void zero_pad_sequence_kernel(
    float* __restrict__ hidden,
    const uint32_t* __restrict__ lengths,
    int seq_len,
    unsigned int model_dim
) {
    int t = blockIdx.x;
    int batch = blockIdx.y;
    if (t >= seq_len) return;

    uint32_t actual_len = lengths[batch];
    if ((uint32_t)t >= actual_len) {
        float* h_t = hidden + batch * seq_len * model_dim + t * model_dim;
        for (int d = threadIdx.x; d < (int)model_dim; d += blockDim.x)
            h_t[d] = 0.0f;
    }
}

