def _build_project(workspace: pathlib.Path, optimize: str = "ReleaseFast") -> None:
    env = os.environ.copy()
    env["PKG_CONFIG_PATH"] = "/usr/local/cuda/lib64/pkgconfig"

    print(f"[build] Compiling Futhark EFLA kernel...")
    ret = subprocess.run(
        ["futhark", "cuda", "--library",
         str(workspace / "kernels" / "efla.fut"),
         "-o", str(workspace / "kernels" / "efla_futhark")],
        cwd=workspace, capture_output=True, text=True, env=env,
    )
    if ret.returncode != 0:
        print("FUTHARK EFLA STDERR:\n", ret.stderr)
        raise RuntimeError("Futhark EFLA compilation failed")
    print("[build] Futhark EFLA: OK")

    print(f"[build] Compiling Futhark MXFP8 kernel...")
    ret = subprocess.run(
        ["futhark", "cuda", "--library",
         str(workspace / "kernels" / "mxfp8.fut"),
         "-o", str(workspace / "kernels" / "mxfp8_futhark")],
        cwd=workspace, capture_output=True, text=True, env=env,
    )
    if ret.returncode != 0:
        print("FUTHARK MXFP8 STDERR:\n", ret.stderr)
        raise RuntimeError("Futhark MXFP8 compilation failed")
    print("[build] Futhark MXFP8: OK")

    print("[build] Compiling custom CUDA kernels...")
    nvcc_cmd = [
        "nvcc",
        "-O3",
        "-arch=sm_90a",
        "--generate-code=arch=compute_90a,code=sm_90a",
        "-std=c++17",
        "--use_fast_math",
        "-Xcompiler", "-fPIC,-O3,-march=native",
        "-I/usr/local/cuda/include",
        "-I", str(workspace / "include"),
        "-lcublas", "-lnccl", "-lcurand",
        "-shared",
        str(workspace / "kernels" / "efla_kernels.cu"),
        str(workspace / "kernels" / "optimizer_kernels.cu"),
        "-o", str(workspace / "kernels" / "libcudakernels.so"),
    ]
    ret = subprocess.run(nvcc_cmd, cwd=workspace, capture_output=True, text=True, env=env)
    if ret.returncode != 0:
        print("NVCC STDERR:\n", ret.stderr)
        raise RuntimeError("CUDA kernel compilation failed")
    print("[build] CUDA kernels: OK")

    print(f"[build] Building Zig project ({optimize})...")
    ret = subprocess.run(
        ["zig", "build", f"-Doptimize={optimize}"],
        cwd=workspace, capture_output=True, text=True, env=env,
    )
    if ret.returncode != 0:
        print("ZIG BUILD STDERR:\n", ret.stderr)
        raise RuntimeError("Zig build failed")
    print("[build] Zig build: OK")


