def train_1t_llm(resume_from_step: int = 0, config_override: dict = None):
    workspace = pathlib.Path("/workspace/underdog-llm")

    pathlib.Path("/mnt/nfs/checkpoints").mkdir(parents=True, exist_ok=True)
    pathlib.Path("/mnt/data").mkdir(parents=True, exist_ok=True)

    _build_project(workspace, optimize="ReleaseFast")

    env = os.environ.copy()
    env["LD_LIBRARY_PATH"] = (
        str(workspace / "kernels") + ":" + env.get("LD_LIBRARY_PATH", "")
    )
    env["LD_PRELOAD"] = str(workspace / "kernels" / "libcudakernels.so")
    env["CUDA_VISIBLE_DEVICES"] = "0,1,2,3,4,5,6,7"

    train_cmd = [str(workspace / "zig-out" / "bin" / "underdog-llm")]
    if resume_from_step > 0:
        train_cmd += ["--resume", str(resume_from_step)]
    if config_override:
        for k, v in config_override.items():
            train_cmd += [f"--{k}", str(v)]

    print(f"[train] Launching: {' '.join(train_cmd)}")
    process = subprocess.Popen(
        train_cmd,
        cwd=workspace,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="", flush=True)
    process.wait()
    if process.returncode != 0:
        raise RuntimeError(f"Training exited with code {process.returncode}")
    return {"status": "complete", "final_step": resume_from_step}


