__device__ __forceinline__ float warp_reduce_sum_f(float val) {
#pragma unroll
    for (int mask = WARP_SIZE / 2; mask > 0; mask >>= 1)
        val += __shfl_xor_sync(0xFFFFFFFF, val, mask);
    return val;
}

__device__ __forceinline__ float warp_reduce_max_f(float val) {
#pragma unroll
    for (int mask = WARP_SIZE / 2; mask > 0; mask >>= 1)
        val = fmaxf(val, __shfl_xor_sync(0xFFFFFFFF, val, mask));
    return val;
}

__device__ __forceinline__ float block_reduce_sum_f(float val, float* smem) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid  = threadIdx.x / WARP_SIZE;
    val = warp_reduce_sum_f(val);
    if (lane == 0) smem[wid] = val;
    __syncthreads();
    int num_warps = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
    val = (threadIdx.x < num_warps) ? smem[threadIdx.x] : 0.0f;
    if (wid == 0) val = warp_reduce_sum_f(val);
    return val;
}

__device__ __forceinline__ float block_reduce_max_f(float val, float* smem) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid  = threadIdx.x / WARP_SIZE;
    val = warp_reduce_max_f(val);
    if (lane == 0) smem[wid] = val;
    __syncthreads();
    int num_warps = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
    val = (threadIdx.x < num_warps) ? smem[threadIdx.x] : -CUDART_INF_F;
    if (wid == 0) val = warp_reduce_max_f(val);
    return val;
}

__device__ __forceinline__ unsigned char float_to_e4m3(float x) {
    unsigned int bits = __float_as_uint(x);
    unsigned int sign = (bits >> 31) & 1u;
    unsigned int exp  = (bits >> 23) & 0xFFu;
    unsigned int mant = bits & 0x7FFFFFu;
    unsigned int be   = 0u;
    if (exp != 0u) {
        int te = (int)exp - 127;
        int ke = te + 7;
        if (ke <= 0)      be = 0u;
        else if (ke >= 15) be = 15u;
        else               be = (unsigned int)ke;
    }
    unsigned int m3 = mant >> 20u;
    return (unsigned char)((sign << 7u) | (be << 3u) | m3);
}

__device__ __forceinline__ float e4m3_to_float(unsigned char q) {
    unsigned int xu   = (unsigned int)q;
    unsigned int sign = (xu >> 7u) & 1u;
    unsigned int exp4 = (xu >> 3u) & 0xFu;
    unsigned int mnt3 = xu & 0x7u;
    if (exp4 == 0u && mnt3 == 0u) return 0.0f;
    int te  = (int)exp4 - 7;
    unsigned int be = (unsigned int)(te + 127);
    unsigned int fp32_bits = (sign << 31u) | (be << 23u) | (mnt3 << 20u);
    return __uint_as_float(fp32_bits);
}

