import argparse
import os
import sys
import struct
import pathlib
import json
import time
import hashlib
import re
import unicodedata
from collections import defaultdict
from typing import Iterator, List, Optional

EOD_TOKEN = 2
BOS_TOKEN = 1
PAD_TOKEN = 3
UNK_TOKEN = 0


def parse_args():
    parser = argparse.ArgumentParser(description="Prepare tokenized training data")
    parser.add_argument("--output", type=str, required=True,
                        help="Output binary file path")
    parser.add_argument("--max-tokens", type=int, default=1_000_000_000_000,
                        help="Maximum number of tokens to write")
    parser.add_argument("--tokenizer-path", type=str, required=True,
                        help="Path to entropy tokenizer vocabulary TSV")
    parser.add_argument("--chunk-size", type=int, default=50_000_000,
                        help="Tokens per sequence chunk")
    parser.add_argument("--datasets", type=str, nargs="+",
                        default=["HuggingFaceFW/fineweb-edu", "togethercomputer/RedPajama-Data-V2"],
                        help="HuggingFace dataset IDs")
    parser.add_argument("--text-field", type=str, default="text",
                        help="Dataset field containing text")
    parser.add_argument("--min-doc-chars", type=int, default=500,
                        help="Minimum document character length")
    parser.add_argument("--dedup", action="store_true", default=True,
                        help="Deduplicate documents by hash")
    parser.add_argument("--quality-filter", action="store_true", default=True,
                        help="Apply quality filtering heuristics")
    parser.add_argument("--num-proc", type=int, default=8,
                        help="Number of parallel processes")
    parser.add_argument("--seed", type=int, default=42,
                        help="Random seed for shuffling")
    return parser.parse_args()


def load_tokenizer_vocab(vocab_path: str) -> dict:
    vocab = {}
    trie = {}
    with open(vocab_path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.rstrip("\n").split("\t")
            if len(parts) < 2:
                continue
            token_text = parts[0]
            token_id = int(parts[1])
            vocab[token_text] = token_id
            node = trie
            for ch in token_text:
                node = node.setdefault(ch, {})
            node["__id__"] = token_id
    return vocab, trie


def tokenize_text(text: str, trie: dict) -> List[int]:
    tokens = [BOS_TOKEN]
    pos = 0
    n = len(text)
    while pos < n:
        node = trie
        best_len = 0
        best_id = None
        j = pos
        while j < n and text[j] in node:
            node = node[text[j]]
            j += 1
            if "__id__" in node:
                best_len = j - pos
                best_id = node["__id__"]
        if best_id is not None:
            tokens.append(best_id)
            pos += best_len
        else:
            tokens.append(ord(text[pos]) % 65536 + 4)
            pos += 1
    tokens.append(EOD_TOKEN)
    return tokens


def is_quality_document(text: str, min_chars: int) -> bool:
    if len(text) < min_chars:
        return False
    words = text.split()
    if len(words) < 50:
        return False
    avg_word_len = sum(len(w) for w in words) / max(len(words), 1)
    if avg_word_len < 2.5 or avg_word_len > 15.0:
        return False
    alpha_chars = sum(1 for c in text if c.isalpha())
    if alpha_chars / max(len(text), 1) < 0.5:
        return False
    lines = text.split("\n")
    if len(lines) > 10:
        bullet_lines = sum(1 for l in lines if l.strip().startswith(("•", "-", "*", "·")))
        if bullet_lines / len(lines) > 0.5:
            return False
    repeated_ngrams = 0
    words_lower = [w.lower() for w in words[:200]]
    ngram_counts = defaultdict(int)
    for i in range(len(words_lower) - 3):
        ng = tuple(words_lower[i:i+4])
        ngram_counts[ng] += 1
    repeated_ngrams = sum(1 for v in ngram_counts.values() if v > 3)
    if repeated_ngrams > 20:
        return False
    return True


def doc_hash(text: str) -> str:
    normalized = unicodedata.normalize("NFKC", text.lower())
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return hashlib.md5(normalized[:1024].encode("utf-8")).hexdigest()


def stream_hf_datasets(
    dataset_ids: List[str],
    text_field: str,
    min_chars: int,
    do_quality_filter: bool,
    do_dedup: bool,
    num_proc: int,
    seed: int,
) -> Iterator[str]:
    try:
        from datasets import load_dataset, concatenate_datasets
    except ImportError:
        print("ERROR: 'datasets' package not installed. Run: pip install datasets")
        sys.exit(1)

    seen_hashes = set()

    for dataset_id in dataset_ids:
        print(f"[data] Loading dataset: {dataset_id}", flush=True)
        try:
            ds = load_dataset(
                dataset_id,
                split="train",
                streaming=True,
                trust_remote_code=True,
            )
        except Exception as e:
            print(f"[data] WARNING: Failed to load {dataset_id}: {e}")
            continue

        for example in ds:
            text = example.get(text_field, "")
            if not isinstance(text, str) or len(text) < min_chars:
                continue
            if do_quality_filter and not is_quality_document(text, min_chars):
                continue
            if do_dedup:
                h = doc_hash(text)
                if h in seen_hashes:
                    continue
                seen_hashes.add(h)
                if len(seen_hashes) % 100_000 == 0:
                    print(f"[data] Dedup set size: {len(seen_hashes):,}", flush=True)
            yield text


def write_tokens_binary(
    output_path: str,
    token_stream: Iterator[List[int]],
    chunk_size: int,
    max_tokens: int,
) -> int:
    output_path_obj = pathlib.Path(output_path)
    output_path_obj.parent.mkdir(parents=True, exist_ok=True)

    total_written = 0
    chunk_buffer = []
    chunks_written = 0
    start_time = time.time()
    last_report = start_time

    with open(output_path, "wb") as f:
        for doc_tokens in token_stream:
            chunk_buffer.extend(doc_tokens)

            while len(chunk_buffer) >= chunk_size:
                chunk = chunk_buffer[:chunk_size]
                chunk_buffer = chunk_buffer[chunk_size:]
                packed = struct.pack(f"<{len(chunk)}I", *chunk)
                f.write(packed)
                total_written += len(chunk)
                chunks_written += 1

                now = time.time()
                if now - last_report >= 10.0:
                    elapsed = now - start_time
                    tps = total_written / elapsed
                    pct = total_written / max_tokens * 100
                    print(
                        f"[data] chunks={chunks_written:,} "
                        f"tokens={total_written/1e9:.3f}B "
                        f"({pct:.2f}%) "
                        f"speed={tps/1e6:.2f}M tok/s",
                        flush=True,
                    )
                    last_report = now

                if total_written >= max_tokens:
                    break

            if total_written >= max_tokens:
                break

        if chunk_buffer and total_written < max_tokens:
            remaining = min(len(chunk_buffer), max_tokens - total_written)
            chunk = chunk_buffer[:remaining]
            while len(chunk) < chunk_size:
                chunk.append(PAD_TOKEN)
            packed = struct.pack(f"<{len(chunk)}I", *chunk)
            f.write(packed)
            total_written += remaining
            chunks_written += 1

    elapsed = time.time() - start_time
    print(
        f"[data] Done. Total tokens: {total_written/1e9:.3f}B "
        f"in {elapsed:.1f}s ({total_written/elapsed/1e6:.2f}M tok/s)",
        flush=True,
    )
    print(f"[data] Output: {output_path} ({output_path_obj.stat().st_size / 1e9:.2f} GB)")
    return total_written


def write_metadata(output_path: str, total_tokens: int, chunk_size: int, args) -> None:
    meta_path = output_path + ".meta.json"
    meta = {
        "total_tokens": total_tokens,
        "chunk_size": chunk_size,
        "num_chunks": total_tokens // chunk_size,
        "datasets": args.datasets,
        "tokenizer_path": args.tokenizer_path,
        "min_doc_chars": args.min_doc_chars,
        "dedup": args.dedup,
        "quality_filter": args.quality_filter,
        "seed": args.seed,
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "eod_token": EOD_TOKEN,
        "bos_token": BOS_TOKEN,
        "pad_token": PAD_TOKEN,
    }
    with open(meta_path, "w") as f:
        json.dump(meta, f, indent=2)
    print(f"[data] Metadata written to {meta_path}")


def main():
    args = parse_args()

    print(f"[data] Loading tokenizer from {args.tokenizer_path}...")
    if not pathlib.Path(args.tokenizer_path).exists():
        print(f"[data] WARNING: Tokenizer vocab not found at {args.tokenizer_path}. Using byte fallback.")
        vocab, trie = {}, {}
    else:
        vocab, trie = load_tokenizer_vocab(args.tokenizer_path)
        print(f"[data] Vocab size: {len(vocab):,}")

    def tokenize_and_yield(docs):
        for doc in docs:
            yield tokenize_text(doc, trie)

    doc_stream = stream_hf_datasets(
        dataset_ids=args.datasets,
        text_field=args.text_field,
        min_chars=args.min_doc_chars,
        do_quality_filter=args.quality_filter,
        do_dedup=args.dedup,
        num_proc=args.num_proc,
        seed=args.seed,
    )

    token_stream = tokenize_and_yield(doc_stream)

    total = write_tokens_binary(
        output_path=args.output,
        token_stream=token_stream,
        chunk_size=args.chunk_size,
        max_tokens=args.max_tokens,
    )

    write_metadata(args.output, total, args.chunk_size, args)


if __name__ == "__main__":
    main()
