**`data_prep/train_tokenizer.py`**
```python
import argparse
import os
import sys
import pathlib
import json
import time
import math
import struct
import unicodedata
import re
from collections import defaultdict, Counter
from typing import Dict, List, Tuple, Optional, Iterator


def parse_args():
    parser = argparse.ArgumentParser(description="Train entropy-constrained tokenizer")
    parser.add_argument("--input-files", type=str, nargs="+", required=True,
                        help="Input text files or glob patterns")
    parser.add_argument("--output-vocab", type=str, required=True,
                        help="Output vocabulary TSV file path")
    parser.add_argument("--vocab-size", type=int, default=131_072,
                        help="Target vocabulary size")
    parser.add_argument("--entropy-threshold", type=float, default=3.5,
                        help="Minimum token entropy to include in vocab")
    parser.add_argument("--max-token-length", type=int, default=32,
                        help="Maximum token length in characters")
    parser.add_argument("--min-frequency", type=int, default=50,
                        help="Minimum token frequency to include")
    parser.add_argument("--num-merge-iters", type=int, default=200_000,
                        help="Number of BPE merge iterations")
    parser.add_argument("--sample-size", type=int, default=100_000_000,
                        help="Number of characters to sample for training")
    parser.add_argument("--text-field", type=str, default="text")
    parser.add_argument("--lowercase", action="store_true", default=False)
    return parser.parse_args()


def compute_entropy(text: str) -> float:
    if not text:
        return 0.0
    counts = Counter(text)
    total = len(text)
    entropy = 0.0
    for cnt in counts.values():
        p = cnt / total
        entropy -= p * math.log2(p)
    return entropy


def normalize_text(text: str, lowercase: bool) -> str:
    text = unicodedata.normalize("NFKC", text)
    if lowercase:
        text = text.lower()
    text = re.sub(r"\r\n", "\n", text)
    text = re.sub(r"\r", "\n", text)
    return text


def pretokenize(text: str) -> List[str]:
    pattern = re.compile(
        r"""'s|'t|'re|'ve|'m|'ll|'d"""
        r"""| ?[a-zA-Z]+"""
        r"""| ?[0-9]+"""
        r"""| ?[^\s\w]+"""
        r"""|\s+(?!\S)"""
        r"""|\s+""",
        re.UNICODE,
    )
    return [m.group() for m in pattern.finditer(text)]


def build_initial_vocab() -> Dict[str, int]:
    vocab = {
        "<unk>": 0,
        "<bos>": 1,
        "<eod>": 2,
        "<pad>": 3,
    }
    for i in range(256):
        vocab[chr(i)] = len(vocab)
    return vocab


def get_pair_freqs(
    word_freqs: Dict[Tuple[str, ...], int]
) -> Dict[Tuple[str, str], int]:
    pair_counts = defaultdict(int)
    for word_tuple, freq in word_freqs.items():
        for i in range(len(word_tuple) - 1):
            pair_counts[(word_tuple[i], word_tuple[i + 1])] += freq
    return pair_counts


def merge_vocab(
    word_freqs: Dict[Tuple[str, ...], int],
    best_pair: Tuple[str, str],
) -> Dict[Tuple[str, ...], int]:
    new_word_freqs = {}
    bigram = best_pair
    replacement = bigram[0] + bigram[1]
    for word_tuple, freq in word_freqs.items():
        new_word = []
        i = 0
        while i < len(word_tuple):
            if (i < len(word_tuple) - 1 and
                    word_tuple[i] == bigram[0] and
                    word_tuple[i + 1] == bigram[1]):
                new_word.append(replacement)
                i += 2
            else:
                new_word.append(word_tuple[i])
                i += 1
        new_word_freqs[tuple(new_word)] = freq
    return new_word_freqs


def sample_text_corpus(
    input_files: List[str],
    sample_size: int,
    lowercase: bool,
) -> str:
    corpus_parts = []
    total_chars = 0

    for fpath in input_files:
        p = pathlib.Path(fpath)
        if not p.exists():
            print(f"[tok] WARNING: File not found: {fpath}")
            continue

        print(f"[tok] Reading {fpath}...", flush=True)
        try:
            with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                for line in f:
                    text = normalize_text(line.rstrip("\n"), lowercase)
                    if len(text) < 10:
                        continue
                    corpus_parts.append(text)
                    total_chars += len(text)
                    if total_chars >= sample_size:
                        break
        except Exception as e:
            print(f"[tok] WARNING: Error reading {fpath}: {e}")
            continue

        if total_chars >= sample_size:
            break

    print(f"[tok] Total corpus chars: {total_chars:,}", flush=True)
    return "\n".join(corpus_parts)


def train_bpe(
    corpus: str,
    vocab_size: int,
    entropy_threshold: float,
    max_token_length: int,
    min_frequency: int,
    num_merge_iters: int,
    lowercase: bool,
) -> Dict[str, Tuple[int, int, float]]:
    print("[tok] Pre-tokenizing corpus...", flush=True)
    pretokens = pretokenize(corpus)
    print(f"[tok] Pre-tokens: {len(pretokens):,}", flush=True)

    word_freqs: Dict[Tuple[str, ...], int] = defaultdict(int)
    for tok in pretokens:
        chars = tuple(tok)
        word_freqs[chars] += 1

    vocab = build_initial_vocab()
    merges = []

    print(f"[tok] Starting BPE training: vocab_size={vocab_size} iters={num_merge_iters}", flush=True)
    start_time = time.time()

    for merge_iter in range(num_merge_iters):
        if len(vocab) >= vocab_size:
            print(f"[tok] Reached target vocab size {vocab_size} at iter {merge_iter}")
            break

        pair_freqs = get_pair_freqs(word_freqs)
        if not pair_freqs:
            print("[tok] No more pairs to merge.")
            break

        best_pair = max(pair_freqs, key=lambda p: pair_freqs[p])
        best_freq = pair_freqs[best_pair]

        if best_freq < min_frequency:
            print(f"[tok] Best pair frequency {best_freq} < min_frequency {min_frequency}. Stopping.")
            break

        new_token = best_pair[0] + best_pair[1]

        if len(new_token) > max_token_length:
            word_freqs_temp = dict(word_freqs)
            word_freqs_temp2 = {}
            for wt, f in word_freqs_temp.items():
                word_freqs_temp2[wt] = f
            word_freqs = word_freqs_temp2
            continue

        token_entropy = compute_entropy(new_token)
        if token_entropy < entropy_threshold and len(new_token) > 3:
            word_freqs = merge_vocab(word_freqs, best_pair)
            continue

        word_freqs = merge_vocab(word_freqs, best_pair)
        merges.append(best_pair)
        vocab[new_token] = len(vocab)

        if merge_iter % 5000 == 0:
            elapsed = time.time() - start_time
            print(
                f"[tok] iter={merge_iter:,} vocab={len(vocab):,} "
                f"best_pair={repr(new_token)} freq={best_freq:,} "
                f"elapsed={elapsed:.1f}s",
                flush=True,
            )

    token_stats = {}
    all_token_freqs: Dict[str, int] = defaultdict(int)
    for word_tuple, freq in word_freqs.items():
        for tok in word_tuple:
            all_token_freqs[tok] += freq

    for token, token_id in vocab.items():
        freq = all_token_freqs.get(token, 0)
        entropy = compute_entropy(token)
        token_stats[token] = (token_id, freq, entropy)

    print(f"[tok] Final vocab size: {len(vocab):,}", flush=True)
    return token_stats


def filter_and_sort_vocab(
    token_stats: Dict[str, Tuple[int, int, float]],
    vocab_size: int,
    entropy_threshold: float,
    min_frequency: int,
) -> List[Tuple[str, int, int, float]]:
    special_tokens = ["<unk>", "<bos>", "<eod>", "<pad>"]
    special = [(tok, token_stats[tok][0], token_stats[tok][1], token_stats[tok][2])
               for tok in special_tokens if tok in token_stats]

    byte_tokens = [(tok, token_stats[tok][0], token_stats[tok][1], token_stats[tok][2])
                   for tok in token_stats
                   if len(tok) == 1 and ord(tok) < 256 and tok not in special_tokens]

    regular = [
        (tok, tid, freq, ent)
        for tok, (tid, freq, ent) in token_stats.items()
        if (tok not in special_tokens and
            not (len(tok) == 1 and ord(tok) < 256) and
            freq >= min_frequency)
    ]

    regular_filtered = [
        (tok, tid, freq, ent) for tok, tid, freq, ent in regular
        if ent >= entropy_threshold or len(tok) <= 2
    ]

    regular_sorted = sorted(regular_filtered, key=lambda x: -x[2])
    remaining_slots = vocab_size - len(special) - len(byte_tokens)
    regular_trimmed = regular_sorted[:max(0, remaining_slots)]

    all_tokens = special + byte_tokens + regular_trimmed
    all_tokens_reassigned = []
    for new_id, (tok, _, freq, ent) in enumerate(all_tokens):
        all_tokens_reassigned.append((tok, new_id, freq, ent))

    print(f"[tok] Final filtered vocab: {len(all_tokens_reassigned):,} tokens", flush=True)
    return all_tokens_reassigned


def write_vocab_tsv(
    output_path: str,
    vocab_entries: List[Tuple[str, int, int, float]],
) -> None:
    output_path_obj = pathlib.Path(output_path)
    output_path_obj.parent.mkdir(parents=True, exist_ok=True)

    with open(output_path, "w", encoding="utf-8") as f:
        for tok, tok_id, freq, ent in vocab_entries:
            tok_escaped = tok.replace("\t", "\\t").replace("\n", "\\n").replace("\r", "\\r")
            f.write(f"{tok_escaped}\t{tok_id}\t{freq}\t{ent:.6f}\n")

    print(f"[tok] Vocabulary written to {output_path} ({len(vocab_entries):,} entries)", flush=True)


def write_vocab_json(
    output_path: str,
    vocab_entries: List[Tuple[str, int, int, float]],
) -> None:
    json_path = output_path.replace(".tsv", ".json")
