    print(f"  Token length: min={min(lengths)} max={max(lengths)} "
          f"mean={sum(lengths)/len(lengths):.1f}")

    length_dist = Counter(lengths)
    print("  Length distribution:")
    for l in sorted(length_dist.keys())[:15]:
