def parse_args():
    parser = argparse.ArgumentParser(
        description="Replit -> Modal runner for Underdog 1T LLM"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    subparsers.add_parser("check", help="Check dependencies and project integrity")
    subparsers.add_parser("deploy", help="Deploy Modal app")
    subparsers.add_parser("phase1", help="Run Phase 1 single-GPU validation")
    subparsers.add_parser("phase2", help="Run Phase 2 8-GPU infrastructure validation")
    subparsers.add_parser("benchmark", help="Run throughput benchmarks")
    subparsers.add_parser("data_prep", help="Prepare training data on Modal")

    train_p = subparsers.add_parser("train", help="Launch full 1T training")
    train_p.add_argument("--resume-step", type=int, default=0)
    train_p.add_argument("--config", type=str, default="",
                         help="JSON config override string")

    subparsers.add_parser("nfs", help="Check NFS status")
    subparsers.add_parser("secrets", help="Check Modal secrets")

    full_p = subparsers.add_parser("full-pipeline", help="Run full pipeline: check -> phase1 -> phase2 -> train")
    full_p.add_argument("--skip-data-prep", action="store_true", default=False)

    return parser.parse_args()


def main():
