    elif args.command == "phase2":
        run_phase2()

    elif args.command == "benchmark":
        run_benchmark()

    elif args.command == "data_prep":
        run_data_prep()

    elif args.command == "train":
        config_override = json.loads(args.config) if args.config else None
        run_training(resume_step=args.resume_step, config_override=config_override)

    elif args.command == "nfs":
        check_nfs_status()

    elif args.command == "secrets":
        check_secrets()

    elif args.command == "full-pipeline":
        print("[runner] Starting full pipeline...")

        check_dependencies()
        if not check_local_build():
            print("[runner] Project files incomplete. Aborting.")
            sys.exit(1)

        code = modal_deploy()
        if code != 0:
            print("[runner] Deploy failed. Aborting.")
            sys.exit(1)

        if not args.skip_data_prep:
            run_data_prep()

        run_phase1()
        run_phase2()
        run_benchmark()
        run_training()


if __name__ == "__main__":
    main()
