const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("nvml.h");
});

pub const TimerEvent = struct {
    start: c.cudaEvent_t,
    stop: c.cudaEvent_t,
    device_id: i32,
    name: []const u8,
    elapsed_ms: f32,

    pub fn init(name: []const u8, device_id: i32) !TimerEvent {
        _ = c.cudaSetDevice(device_id);
        var start: c.cudaEvent_t = undefined;
        var stop: c.cudaEvent_t = undefined;
        if (c.cudaEventCreate(&start) != c.cudaSuccess) return error.CudaEventCreateFailed;
        if (c.cudaEventCreate(&stop) != c.cudaSuccess) return error.CudaEventCreateFailed;
        return TimerEvent{
            .start = start,
            .stop = stop,
            .device_id = device_id,
            .name = name,
            .elapsed_ms = 0.0,
        };
    }

    pub fn deinit(self: *TimerEvent) void {
        _ = c.cudaSetDevice(self.device_id);
        _ = c.cudaEventDestroy(self.start);
        _ = c.cudaEventDestroy(self.stop);
    }

    pub fn recordStart(self: *TimerEvent, stream: c.cudaStream_t) void {
        _ = c.cudaSetDevice(self.device_id);
        _ = c.cudaEventRecord(self.start, stream);
    }

    pub fn recordStop(self: *TimerEvent, stream: c.cudaStream_t) void {
        _ = c.cudaSetDevice(self.device_id);
        _ = c.cudaEventRecord(self.stop, stream);
    }

    pub fn synchronizeAndGetMs(self: *TimerEvent) !f32 {
        _ = c.cudaSetDevice(self.device_id);
        if (c.cudaEventSynchronize(self.stop) != c.cudaSuccess)
            return error.CudaEventSyncFailed;
        var ms: f32 = 0.0;
        if (c.cudaEventElapsedTime(&ms, self.start, self.stop) != c.cudaSuccess)
            return error.CudaElapsedTimeFailed;
        self.elapsed_ms = ms;
        return ms;
    }
};

pub const ProfilerEntry = struct {
    name: []const u8,
    total_ms: f64,
    call_count: u64,
    min_ms: f32,
    max_ms: f32,
};

pub const Profiler = struct {
    entries: std.StringHashMap(ProfilerEntry),
    active_timers: std.StringHashMap(TimerEvent),
    enabled: bool,
    allocator: std.mem.Allocator,
    step_start_ns: i64,
    tokens_processed: u64,

    pub fn init(enabled: bool, allocator: std.mem.Allocator) Profiler {
        return Profiler{
            .entries = std.StringHashMap(ProfilerEntry).init(allocator),
            .active_timers = std.StringHashMap(TimerEvent).init(allocator),
            .enabled = enabled,
            .allocator = allocator,
            .step_start_ns = 0,
            .tokens_processed = 0,
        };
    }

    pub fn deinit(self: *Profiler) void {
        var it = self.active_timers.iterator();
        while (it.next()) |entry| {
            var timer = entry.value_ptr;
            timer.deinit();
        }
        self.active_timers.deinit();
        self.entries.deinit();
    }

    pub fn startStep(self: *Profiler, tokens: u64) void {
        self.step_start_ns = std.time.nanoTimestamp();
        self.tokens_processed = tokens;
    }

    pub fn beginTimer(
        self: *Profiler,
        name: []const u8,
        device_id: i32,
        stream: c.cudaStream_t,
    ) void {
        if (!self.enabled) return;
        var timer = TimerEvent.init(name, device_id) catch return;
        timer.recordStart(stream);
        self.active_timers.put(name, timer) catch return;
    }

    pub fn endTimer(self: *Profiler, name: []const u8, stream: c.cudaStream_t) void {
        if (!self.enabled) return;
        var timer = self.active_timers.getPtr(name) orelse return;
        timer.recordStop(stream);
        const ms = timer.synchronizeAndGetMs() catch return;

        if (self.entries.getPtr(name)) |entry| {
            entry.total_ms += @as(f64, ms);
            entry.call_count += 1;
            if (ms < entry.min_ms) entry.min_ms = ms;
            if (ms > entry.max_ms) entry.max_ms = ms;
        } else {
            self.entries.put(name, ProfilerEntry{
                .name = name,
                .total_ms = @as(f64, ms),
                .call_count = 1,
                .min_ms = ms,
                .max_ms = ms,
            }) catch return;
        }
        _ = self.active_timers.remove(name);
        timer.deinit();
    }

    pub fn printReport(self: *Profiler) void {
        if (!self.enabled) return;

        const now_ns = std.time.nanoTimestamp();
        const step_ms = @as(f64, @floatFromInt(now_ns - self.step_start_ns)) / 1_000_000.0;
        const tps = @as(f64, @floatFromInt(self.tokens_processed)) / (step_ms / 1000.0);

        std.debug.print("\n[PROFILER] Step time: {d:.2}ms, Tokens/sec: {d:.0}\n", .{ step_ms, tps });
        std.debug.print("{s:<40} {s:>10} {s:>10} {s:>10} {s:>10}\n", .{
            "Operation", "Total(ms)", "Avg(ms)", "Min(ms)", "Max(ms)",
        });
        std.debug.print("{s}\n", .{"=" ** 82});

        var sorted_entries = std.ArrayList(ProfilerEntry).init(self.allocator);
        defer sorted_entries.deinit();

        var it = self.entries.iterator();
        while (it.next()) |entry| {
            sorted_entries.append(entry.value_ptr.*) catch continue;
        }

        std.mem.sort(ProfilerEntry, sorted_entries.items, {}, struct {
            fn lessThan(_: void, a: ProfilerEntry, b: ProfilerEntry) bool {
                return a.total_ms > b.total_ms;
            }
        }.lessThan);

        var total_accounted: f64 = 0.0;
        for (sorted_entries.items) |entry| {
            const avg_ms = entry.total_ms / @as(f64, @floatFromInt(entry.call_count));
            std.debug.print("{s:<40} {d:>10.2} {d:>10.2} {d:>10.2} {d:>10.2}\n", .{
                entry.name,
                entry.total_ms,
                avg_ms,
                entry.min_ms,
                entry.max_ms,
            });
            total_accounted += entry.total_ms;
        }
        std.debug.print("{s}\n", .{"-" ** 82});
        std.debug.print("{s:<40} {d:>10.2}\n\n", .{ "TOTAL ACCOUNTED", total_accounted });
    }

    pub fn resetCounters(self: *Profiler) void {
        var it = self.entries.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.total_ms = 0.0;
            entry.value_ptr.call_count = 0;
            entry.value_ptr.min_ms = std.math.inf(f32);
            entry.value_ptr.max_ms = -std.math.inf(f32);
        }
    }
};

pub const NvmlMonitor = struct {
    initialized: bool,
    num_gpus: u32,
    handles: []c.nvmlDevice_t,
    allocator: std.mem.Allocator,

    pub fn init(num_gpus: u32, allocator: std.mem.Allocator) !NvmlMonitor {
        const ret = c.nvmlInit_v2();
        if (ret != c.NVML_SUCCESS) {
            return NvmlMonitor{
                .initialized = false,
                .num_gpus = 0,
                .handles = &[_]c.nvmlDevice_t{},
                .allocator = allocator,
            };
        }
        const handles = try allocator.alloc(c.nvmlDevice_t, num_gpus);
        for (handles, 0..) |*handle, i| {
            const err = c.nvmlDeviceGetHandleByIndex(@intCast(i), handle);
            if (err != c.NVML_SUCCESS) {
                allocator.free(handles);
                return error.NvmlGetHandleFailed;
            }
        }
        return NvmlMonitor{
            .initialized = true,
            .num_gpus = num_gpus,
            .handles = handles,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *NvmlMonitor) void {
        if (self.initialized) {
            _ = c.nvmlShutdown();
            self.allocator.free(self.handles);
        }
    }

    pub fn printGpuStats(self: *NvmlMonitor) void {
        if (!self.initialized) return;
        std.debug.print("[GPU STATS]\n", .{});
        for (self.handles, 0..) |handle, i| {
            var mem_info: c.nvmlMemory_t = undefined;
            var util_info: c.nvmlUtilization_t = undefined;
            var temp: c_uint = 0;
            var power: c_uint = 0;
            var clock_sm: c_uint = 0;
            var clock_mem: c_uint = 0;

            _ = c.nvmlDeviceGetMemoryInfo(handle, &mem_info);
            _ = c.nvmlDeviceGetUtilizationRates(handle, &util_info);
            _ = c.nvmlDeviceGetTemperature(handle, c.NVML_TEMPERATURE_GPU, &temp);
            _ = c.nvmlDeviceGetPowerUsage(handle, &power);
            _ = c.nvmlDeviceGetClockInfo(handle, c.NVML_CLOCK_SM, &clock_sm);
            _ = c.nvmlDeviceGetClockInfo(handle, c.NVML_CLOCK_MEM, &clock_mem);

            const used_gb = @as(f64, @floatFromInt(mem_info.used)) / (1024.0 * 1024.0 * 1024.0);
            const total_gb = @as(f64, @floatFromInt(mem_info.total)) / (1024.0 * 1024.0 * 1024.0);
            const power_w = @as(f64, @floatFromInt(power)) / 1000.0;

            std.debug.print(
                "  GPU {d}: mem={d:.1f}/{d:.1f}GB util={d}% temp={d}C "
                "power={d:.0}W sm={d}MHz mem={d}MHz\n",
                .{
                    i, used_gb, total_gb,
                    util_info.gpu, temp, power_w,
                    clock_sm, clock_mem,
                },
            );
        }
    }
};

pub const ThroughputTracker = struct {
    window_size: u32,
    token_history: []u64,
    time_history: []i64,
    head: u32,
    filled: bool,
    total_tokens: u64,
    allocator: std.mem.Allocator,

    pub fn init(window_size: u32, allocator: std.mem.Allocator) !ThroughputTracker {
        const token_history = try allocator.alloc(u64, window_size);
        const time_history = try allocator.alloc(i64, window_size);
        @memset(token_history, 0);
        @memset(time_history, 0);
        return ThroughputTracker{
            .window_size = window_size,
            .token_history = token_history,
            .time_history = time_history,
            .head = 0,
            .filled = false,
            .total_tokens = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ThroughputTracker) void {
        self.allocator.free(self.token_history);
        self.allocator.free(self.time_history);
    }

    pub fn record(self: *ThroughputTracker, tokens: u64) void {
        self.token_history[self.head] = tokens;
        self.time_history[self.head] = std.time.nanoTimestamp();
        self.head = (self.head + 1) % self.window_size;
        if (self.head == 0) self.filled = true;
        self.total_tokens += tokens;
    }

    pub fn tokensPerSecond(self: *const ThroughputTracker) f64 {
        const n = if (self.filled) self.window_size else self.head;
        if (n < 2) return 0.0;

        const oldest_idx = if (self.filled) self.head else 0;
        const newest_idx = if (self.head == 0) self.window_size - 1 else self.head - 1;

        const dt_ns = self.time_history[newest_idx] - self.time_history[oldest_idx];
        if (dt_ns <= 0) return 0.0;

        var total_toks: u64 = 0;
        for (0..n) |i| {
            total_toks += self.token_history[(oldest_idx + i) % self.window_size];
        }

        const dt_s = @as(f64, @floatFromInt(dt_ns)) / 1_000_000_000.0;
        return @as(f64, @floatFromInt(total_toks)) / dt_s;
    }

    pub fn mfuEstimate(
        self: *const ThroughputTracker,
        model_flops_per_token: f64,
        gpu_peak_flops: f64,
        num_gpus: u32,
    ) f64 {
        const tps = self.tokensPerSecond();
        const actual_flops = tps * model_flops_per_token;
        const total_peak = gpu_peak_flops * @as(f64, @floatFromInt(num_gpus));
        return actual_flops / total_peak * 100.0;
    }
};
