    local_seq_len: u64,
    global_offset: u64,
    device_id: i32,
    hidden_buf: mem.MemoryBlock,
    grad_buf: mem.MemoryBlock,
    left_anchor: ?mem.MemoryBlock,
    right_anchor: ?mem.MemoryBlock,
    allocator: std.mem.Allocator,

    pub fn init(
        config: SeqParallelConfig,
        mm: *mem.MemoryManager,
        allocator: std.mem.Allocator,
    ) !SeqChunk {
        const base_len = config.total_seq_len / config.num_gpus;
        const remainder = config.total_seq_len % config.num_gpus;
        const local_len = base_len + (if (config.local_rank < remainder) @as(u64, 1) else 0);
        const global_off: u64 = blk: {
            var off: u64 = 0;
            for (0..config.local_rank) |r| {
                off += base_len + (if (r < remainder) @as(u64, 1) else 0);
            }
            break :blk off;
        };

        const elem_bytes = @sizeOf(f32);
        const hidden_size = local_len * config.model_dim * elem_bytes;
        const device_id: i32 = @intCast(config.local_rank);

        const hidden_buf = try mm.allocOnGPU(hidden_size, device_id);
        const grad_buf = try mm.allocOnGPU(hidden_size, device_id);

        const anchor_size = @as(u64, config.chunk_overlap) * config.model_dim * elem_bytes;
        const left_anchor: ?mem.MemoryBlock = if (config.local_rank > 0)
            try mm.allocOnGPU(anchor_size, device_id)
        else
            null;
        const right_anchor: ?mem.MemoryBlock = if (config.local_rank < config.num_gpus - 1)
            try mm.allocOnGPU(anchor_size, device_id)
        else
            null;

        return SeqChunk{
            .local_seq_len = local_len,
            .global_offset = global_off,
            .device_id = device_id,
            .hidden_buf = hidden_buf,
            .grad_buf = grad_buf,
            .left_anchor = left_anchor,
            .right_anchor = right_anchor,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SeqChunk) void {
        self.hidden_buf.freeGPU();
        self.grad_buf.freeGPU();
        if (self.left_anchor) |*a| a.freeGPU();
        if (self.right_anchor) |*a| a.freeGPU();
    }
};

pub const SequenceParallelRuntime = struct {
    config: SeqParallelConfig,
    chunks: []SeqChunk,
    comm: *nccl.NcclComm,
    mm: *mem.MemoryManager,
    send_buf: mem.MemoryBlock,
    recv_buf: mem.MemoryBlock,
    allocator: std.mem.Allocator,

    pub fn init(
        config: SeqParallelConfig,
        comm: *nccl.NcclComm,
        mm: *mem.MemoryManager,
        allocator: std.mem.Allocator,
    ) !SequenceParallelRuntime {
        const chunks = try allocator.alloc(SeqChunk, config.num_gpus);
        for (chunks, 0..) |*chunk, i| {
            var cfg = config;
            cfg.local_rank = @intCast(i);
            chunk.* = try SeqChunk.init(cfg, mm, allocator);
        }

        const max_anchor = @as(u64, config.chunk_overlap) * config.model_dim * @sizeOf(f32);
        const send_buf = try mm.allocOnGPU(max_anchor, 0);
        const recv_buf = try mm.allocOnGPU(max_anchor, 0);

        return SequenceParallelRuntime{
            .config = config,
            .chunks = chunks,
            .comm = comm,
            .mm = mm,
            .send_buf = send_buf,
            .recv_buf = recv_buf,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SequenceParallelRuntime) void {
        for (self.chunks) |*chunk| chunk.deinit();
        self.allocator.free(self.chunks);
        self.send_buf.freeGPU();
        self.recv_buf.freeGPU();
    }

    pub fn scatterSequence(
        self: *SequenceParallelRuntime,
        full_tokens: []const u32,
        streams: []c.cudaStream_t,
    ) !void {
        for (self.chunks, 0..) |*chunk, gpu_idx| {
            const start: u64 = chunk.global_offset;
            const end: u64 = start + chunk.local_seq_len;
            const tok_slice = full_tokens[@intCast(start)..@intCast(end)];
            _ = c.cudaSetDevice(@intCast(gpu_idx));
            const stream = if (gpu_idx < streams.len) streams[gpu_idx] else @as(c.cudaStream_t, @ptrFromInt(0));
            _ = c.cudaMemcpyAsync(
                chunk.hidden_buf.gpu_ptr.?,
                tok_slice.ptr,
                tok_slice.len * @sizeOf(u32),
                c.cudaMemcpyHostToDevice,
                stream,
            );
        }
    }

    pub fn exchangeAnchors(
        self: *SequenceParallelRuntime,
        streams: []c.cudaStream_t,
    ) !void {
        const overlap = self.config.chunk_overlap;
        const model_dim = self.config.model_dim;
        const anchor_elems = @as(u64, overlap) * model_dim;
        const anchor_bytes = anchor_elems * @sizeOf(f32);

        try c.ncclGroupStart();

        for (self.chunks, 0..) |*chunk, i| {
            const rank: i32 = @intCast(i);
            _ = c.cudaSetDevice(rank);
            const stream = if (i < streams.len) streams[i] else @as(c.cudaStream_t, @ptrFromInt(0));

            if (i + 1 < self.config.num_gpus) {
                const right_chunk = &self.chunks[i + 1];
                const tail_ptr: *anyopaque = @ptrFromInt(
                    @intFromPtr(chunk.hidden_buf.gpu_ptr.?) +
                    (chunk.local_seq_len - overlap) * model_dim * @sizeOf(f32),
                );
                _ = c.ncclSend(
                    tail_ptr,
                    @intCast(anchor_elems),
                    c.ncclFloat32,
                    rank + 1,
                    self.comm.comms[i],
                    stream,
                );
                if (right_chunk.left_anchor) |*la| {
                    _ = c.ncclRecv(
                        la.gpu_ptr.?,
                        @intCast(anchor_elems),
                        c.ncclFloat32,
                        rank + 1,
                        self.comm.comms[i],
                        stream,
                    );
                }
            }

            if (i > 0) {
                const left_chunk = &self.chunks[i - 1];
                const head_ptr = chunk.hidden_buf.gpu_ptr.?;
                _ = c.ncclSend(
                    head_ptr,
                    @intCast(anchor_elems),
                    c.ncclFloat32,
                    rank - 1,
                    self.comm.comms[i],
                    stream,
                );
                if (left_chunk.right_anchor) |*ra| {
                    _ = c.ncclRecv(
                        ra.gpu_ptr.?,
                        @intCast(anchor_elems),
                        c.ncclFloat32,
                        rank - 1,
                        self.comm.comms[i],
                        stream,
                    );
                }
            }

            _ = anchor_bytes;
        }

        try c.ncclGroupEnd();
        self.comm.syncAll();
    }

    pub fn allReduceGradsAcrossSeqChunks(
        self: *SequenceParallelRuntime,
        streams: []c.cudaStream_t,
    ) !void {
        try c.ncclGroupStart();
        for (self.chunks, 0..) |*chunk, i| {
            const stream = if (i < streams.len) streams[i] else @as(c.cudaStream_t, @ptrFromInt(0));
            _ = c.cudaSetDevice(@intCast(i));
            const num_elems = chunk.local_seq_len * self.config.model_dim;
            _ = c.ncclAllReduce(
                chunk.grad_buf.gpu_ptr.?,
                chunk.grad_buf.gpu_ptr.?,
                @intCast(num_elems),
                c.ncclFloat32,
                c.ncclSum,
                self.comm.comms[i],
                stream,
            );
        }
        try c.ncclGroupEnd();
        self.comm.syncAll();
    }

    pub fn gatherOutputFromChunks(
        self: *SequenceParallelRuntime,
        output_buf: *anyopaque,
        output_device: i32,
    ) !void {
        _ = c.cudaSetDevice(output_device);
        var offset: u64 = 0;
        for (self.chunks) |*chunk| {
            const bytes = chunk.local_seq_len * self.config.model_dim * @sizeOf(f32);
            const dst: *anyopaque = @ptrFromInt(@intFromPtr(output_buf) + offset * @sizeOf(f32));
            _ = c.cudaMemcpy(
                dst,
                chunk.hidden_buf.gpu_ptr.?,
                bytes,
                if (chunk.device_id == output_device)
                    c.cudaMemcpyDeviceToDevice
                else
                    c.cudaMemcpyDefault,
            );
            offset += chunk.local_seq_len * self.config.model_dim;
        }
    }

    pub fn chunkLocalSeqLen(self: *const SequenceParallelRuntime, rank: u32) u64 {
        return self.chunks[rank].local_seq_len;
    }

    pub fn chunkGlobalOffset(self: *const SequenceParallelRuntime, rank: u32) u64 {
        return self.chunks[rank].global_offset;
    }
};
