const std = @import("std");
const mem = @import("memory.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("liburing.h");
});

pub const OffloadTier = enum {
    gpu,
    cpu_pinned,
    nvme,
};

pub const OffloadPolicy = struct {
    active_layers_on_gpu: u32 = 4,
    prefetch_ahead: u32 = 2,
    writeback_behind: u32 = 2,
    nvme_path: []const u8 = "/mnt/nvme/offload",
    use_uring: bool = true,
    uring_queue_depth: u32 = 256,
    cpu_buffer_gb: f32 = 64.0,
    pin_optimizer_states: bool = false,
};

pub const LayerState = enum {
    on_gpu,
    on_cpu,
    on_nvme,
    prefetching_to_gpu,
    writing_to_cpu,
    writing_to_nvme,
    invalid,
};

pub const LayerOffloadRecord = struct {
    layer_idx: u32,
    state: LayerState,
    gpu_block: ?mem.MemoryBlock,
    cpu_block: ?mem.MemoryBlock,
    nvme_offset: u64,
    nvme_size: usize,
    param_size_bytes: usize,
    grad_size_bytes: usize,
    optim_size_bytes: usize,
    last_accessed_step: u64,
    prefetch_stream: c.cudaStream_t,
    writeback_stream: c.cudaStream_t,
};

pub const UringContext = struct {
    ring: c.io_uring,
    nvme_fd: c_int,
    initialized: bool,

    pub fn init(nvme_path: []const u8, queue_depth: u32) !UringContext {
        var ring: c.io_uring = undefined;
        const ret = c.io_uring_queue_init(queue_depth, &ring, 0);
        if (ret < 0) return error.UringInitFailed;

        const fd = std.c.open(nvme_path.ptr, std.c.O.RDWR | std.c.O.CREAT | std.c.O.LARGEFILE, 0o644);
        if (fd < 0) {
            c.io_uring_queue_exit(&ring);
            return error.NvmeOpenFailed;
        }

        return UringContext{
            .ring = ring,
            .nvme_fd = fd,
            .initialized = true,
        };
    }

    pub fn deinit(self: *UringContext) void {
        if (self.initialized) {
            _ = std.c.close(self.nvme_fd);
            c.io_uring_queue_exit(&self.ring);
            self.initialized = false;
        }
    }

    pub fn submitWrite(
        self: *UringContext,
        data: []const u8,
        offset: u64,
    ) !void {
        const sqe = c.io_uring_get_sqe(&self.ring) orelse return error.UringFullSQE;
        c.io_uring_prep_write(sqe, self.nvme_fd, data.ptr, @intCast(data.len), @intCast(offset));
        sqe.*.user_data = 0;
        _ = c.io_uring_submit(&self.ring);
    }

    pub fn submitRead(
        self: *UringContext,
        buffer: []u8,
        offset: u64,
    ) !void {
        const sqe = c.io_uring_get_sqe(&self.ring) orelse return error.UringFullSQE;
        c.io_uring_prep_read(sqe, self.nvme_fd, buffer.ptr, @intCast(buffer.len), @intCast(offset));
        sqe.*.user_data = 1;
        _ = c.io_uring_submit(&self.ring);
    }

    pub fn waitCompletion(self: *UringContext) !void {
        var cqe: *c.io_uring_cqe = undefined;
        const ret = c.io_uring_wait_cqe(&self.ring, &cqe);
        if (ret < 0) return error.UringWaitFailed;
        if (cqe.*.res < 0) return error.UringIOFailed;
        c.io_uring_cqe_seen(&self.ring, cqe);
    }

    pub fn drainCompletions(self: *UringContext) void {
        var cqe: *c.io_uring_cqe = undefined;
        while (c.io_uring_peek_cqe(&self.ring, &cqe) == 0) {
            c.io_uring_cqe_seen(&self.ring, cqe);
        }
    }
};

pub const ZeROOffloadManager = struct {
    policy: OffloadPolicy,
    records: []LayerOffloadRecord,
    num_layers: u32,
    num_gpus: u32,
    uring_ctx: ?UringContext,
    nvme_cursor: u64,
    cpu_pool: ?mem.MemoryBlock,
    cpu_pool_cursor: usize,
    mm: *mem.MemoryManager,
    allocator: std.mem.Allocator,
    current_step: u64,

    pub fn init(
        num_layers: u32,
        num_gpus: u32,
        policy: OffloadPolicy,
        mm: *mem.MemoryManager,
        allocator: std.mem.Allocator,
    ) !ZeROOffloadManager {
        const records = try allocator.alloc(LayerOffloadRecord, num_layers);

        for (records, 0..) |*rec, i| {
            var pref_stream: c.cudaStream_t = undefined;
            var wb_stream: c.cudaStream_t = undefined;
            const dev: i32 = @intCast(i % num_gpus);
            _ = c.cudaSetDevice(dev);
            _ = c.cudaStreamCreateWithFlags(&pref_stream, c.cudaStreamNonBlocking);
            _ = c.cudaStreamCreateWithFlags(&wb_stream, c.cudaStreamNonBlocking);
            rec.* = LayerOffloadRecord{
                .layer_idx = @intCast(i),
                .state = .invalid,
                .gpu_block = null,
                .cpu_block = null,
                .nvme_offset = 0,
                .nvme_size = 0,
                .param_size_bytes = 0,
                .grad_size_bytes = 0,
                .optim_size_bytes = 0,
                .last_accessed_step = 0,
                .prefetch_stream = pref_stream,
                .writeback_stream = wb_stream,
            };
        }

        var uring: ?UringContext = null;
        if (policy.use_uring) {
            uring = UringContext.init(policy.nvme_path, policy.uring_queue_depth) catch null;
        }

        const cpu_bytes = @as(usize, @intFromFloat(policy.cpu_buffer_gb * 1024.0 * 1024.0 * 1024.0));
        var cpu_pool: ?mem.MemoryBlock = null;
        if (cpu_bytes > 0) {
            cpu_pool = mem.MemoryBlock.allocPinned(cpu_bytes, 0) catch null;
        }

        return ZeROOffloadManager{
            .policy = policy,
            .records = records,
            .num_layers = num_layers,
            .num_gpus = num_gpus,
            .uring_ctx = uring,
            .nvme_cursor = 0,
            .cpu_pool = cpu_pool,
            .cpu_pool_cursor = 0,
            .mm = mm,
            .allocator = allocator,
            .current_step = 0,
        };
    }

    pub fn deinit(self: *ZeROOffloadManager) void {
        for (self.records) |*rec| {
            const dev: i32 = @intCast(rec.layer_idx % self.num_gpus);
            _ = c.cudaSetDevice(dev);
            _ = c.cudaStreamDestroy(rec.prefetch_stream);
            _ = c.cudaStreamDestroy(rec.writeback_stream);
            if (rec.gpu_block) |*b| b.freeGPU();
            if (rec.cpu_block) |*b| b.freeCPU();
        }
        self.allocator.free(self.records);
        if (self.uring_ctx) |*u| u.deinit();
        if (self.cpu_pool) |*p| p.freeCPU();
    }

    pub fn registerLayerParams(
        self: *ZeROOffloadManager,
        layer_idx: u32,
        param_bytes: usize,
        grad_bytes: usize,
        optim_bytes: usize,
    ) void {
        const rec = &self.records[layer_idx];
        rec.param_size_bytes = param_bytes;
        rec.grad_size_bytes = grad_bytes;
        rec.optim_size_bytes = optim_bytes;
        rec.state = .on_nvme;
        rec.nvme_size = param_bytes + grad_bytes + optim_bytes;
        rec.nvme_offset = self.nvme_cursor;
        self.nvme_cursor += rec.nvme_size;
    }

    pub fn prefetchLayerToGPU(self: *ZeROOffloadManager, layer_idx: u32) !void {
        const rec = &self.records[layer_idx];
        if (rec.state == .on_gpu) return;

        const dev: i32 = @intCast(layer_idx % self.num_gpus);
        _ = c.cudaSetDevice(dev);
        rec.state = .prefetching_to_gpu;

        const total_size = rec.param_size_bytes + rec.grad_size_bytes;
        const gpu_block = try self.mm.allocOnGPU(total_size, dev);
        rec.gpu_block = gpu_block;

        switch (rec.state) {
            .on_cpu => {
                if (rec.cpu_block) |cpu| {
                    _ = c.cudaMemcpyAsync(
                        gpu_block.gpu_ptr.?,
                        cpu.cpu_ptr.?,
                        rec.param_size_bytes,
                        c.cudaMemcpyHostToDevice,
                        rec.prefetch_stream,
                    );
                }
            },
            .on_nvme => {
                if (self.cpu_pool) |*pool| {
                    const cpu_off = @mod(layer_idx * total_size, pool.size_bytes - total_size);
                    const cpu_ptr: *anyopaque = @ptrFromInt(@intFromPtr(pool.cpu_ptr.?) + cpu_off);
                    var cpu_buf: []u8 = undefined;
                    cpu_buf.ptr = @ptrCast(cpu_ptr);
                    cpu_buf.len = total_size;
                    if (self.uring_ctx) |*u| {
                        u.submitRead(cpu_buf, rec.nvme_offset) catch {};
                        u.waitCompletion() catch {};
                    }
                    _ = c.cudaMemcpyAsync(
                        gpu_block.gpu_ptr.?,
                        cpu_ptr,
                        total_size,
                        c.cudaMemcpyHostToDevice,
                        rec.prefetch_stream,
                    );
                }
            },
            else => {},
        }
        rec.state = .on_gpu;
        rec.last_accessed_step = self.current_step;
    }

    pub fn writebackLayerToCPU(self: *ZeROOffloadManager, layer_idx: u32) !void {
        const rec = &self.records[layer_idx];
        if (rec.state != .on_gpu) return;
        if (rec.gpu_block == null) return;

        const dev: i32 = @intCast(layer_idx % self.num_gpus);
        _ = c.cudaSetDevice(dev);
        rec.state = .writing_to_cpu;

        const total_size = rec.param_size_bytes + rec.grad_size_bytes;

        if (self.cpu_pool) |*pool| {
            const cpu_off = @mod(layer_idx * total_size, pool.size_bytes - total_size);
            const cpu_ptr: *anyopaque = @ptrFromInt(@intFromPtr(pool.cpu_ptr.?) + cpu_off);
            _ = c.cudaMemcpyAsync(
                cpu_ptr,
                rec.gpu_block.?.gpu_ptr.?,
                total_size,
                c.cudaMemcpyDeviceToHost,
                rec.writeback_stream,
            );
            _ = c.cudaStreamSynchronize(rec.writeback_stream);

            if (self.uring_ctx) |*u| {
                var buf: []const u8 = undefined;
                buf.ptr = @ptrCast(cpu_ptr);
                buf.len = total_size;
                u.submitWrite(buf, rec.nvme_offset) catch {};
            }
        }

        rec.gpu_block.?.freeGPU();
        rec.gpu_block = null;
        rec.state = .on_cpu;
    }

    pub fn scheduleForStep(self: *ZeROOffloadManager, step: u64, active_layer: u32) !void {
        self.current_step = step;

        const prefetch_ahead = self.policy.prefetch_ahead;
        const writeback_behind = self.policy.writeback_behind;
        const active = self.policy.active_layers_on_gpu;

        for (0..prefetch_ahead) |i| {
            const target = active_layer + active + @as(u32, @intCast(i));
            if (target < self.num_layers) {
                try self.prefetchLayerToGPU(target);
            }
        }

        if (active_layer > writeback_behind) {
            for (0..writeback_behind) |i| {
                const target = active_layer - writeback_behind + @as(u32, @intCast(i));
                try self.writebackLayerToCPU(target);
            }
        }
    }

    pub fn syncAllWritebacks(self: *ZeROOffloadManager) void {
        for (self.records) |rec| {
            if (rec.state == .writing_to_cpu or rec.state == .writing_to_nvme) {
                _ = c.cudaSetDevice(@intCast(rec.layer_idx % self.num_gpus));
                _ = c.cudaStreamSynchronize(rec.writeback_stream);
            }
        }
        if (self.uring_ctx) |*u| u.drainCompletions();
    }

    pub fn getLayerGPUPtr(self: *ZeROOffloadManager, layer_idx: u32) ?*anyopaque {
        const rec = &self.records[layer_idx];
        if (rec.state == .on_gpu) {
            if (rec.gpu_block) |b| return b.gpu_ptr;
        }
        return null;
    }

    pub fn offloadStats(self: *const ZeROOffloadManager) void {
        var on_gpu: u32 = 0;
        var on_cpu: u32 = 0;
        var on_nvme: u32 = 0;
        for (self.records) |rec| {
            switch (rec.state) {
                .on_gpu, .prefetching_to_gpu => on_gpu += 1,
                .on_cpu, .writing_to_cpu => on_cpu += 1,
                .on_nvme, .writing_to_nvme => on_nvme += 1,
                else => {},
            }
        }
        std.log.info(
            "ZeROOffload: gpu={} cpu={} nvme={} nvme_cursor={}GB",
            .{
                on_gpu, on_cpu, on_nvme,
                self.nvme_cursor / (1024 * 1024 * 1024),
            },
        );
    }
};
