const std = @import("std");
const mem = @import("../runtime/memory.zig");
const nccl = @import("../runtime/nccl.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cublas_v2.h");
});

pub const PRISMConfig = struct {
    model_dim: u32,
    num_layers: u32,
    num_heads: u32,
    head_dim: u32,
    ffn_dim: u32,
    vocab_size: u32,
    max_seq_len: u64,
    num_gpus: u32,
    tensor_parallel_degree: u32,
    precision: mem.Precision,
    low_rank_forget: u32 = 64,
    high_rank_inject: u32 = 512,
    num_anchors: u32 = 32,
    anchor_stride: u32 = 1024,
};

pub const PRISMLayerWeights = struct {
    forget_down: mem.MemoryBlock,
    forget_up: mem.MemoryBlock,
    inject_key: mem.MemoryBlock,
    inject_val: mem.MemoryBlock,
    inject_query: mem.MemoryBlock,
    inject_out: mem.MemoryBlock,
    predictor_up1: mem.MemoryBlock,
    predictor_up2: mem.MemoryBlock,
    predictor_down: mem.MemoryBlock,
    anchor_proj: mem.MemoryBlock,
    norm1_scale: mem.MemoryBlock,
    norm1_bias: mem.MemoryBlock,
    norm2_scale: mem.MemoryBlock,
    norm2_bias: mem.MemoryBlock,
    device_id: i32,

    pub fn init(cfg: PRISMConfig, device_id: i32, mm: *mem.MemoryManager) !PRISMLayerWeights {
        const eb = mem.precisionBytes(cfg.precision);
        const tp = cfg.tensor_parallel_degree;
        const d = cfg.model_dim;
        const lr = cfg.low_rank_forget;
        const hr = cfg.high_rank_inject;
        const local_heads = cfg.num_heads / tp;
        _ = c.cudaSetDevice(device_id);

        return PRISMLayerWeights{
            .forget_down     = try mm.allocOnGPU(d * lr * eb, device_id),
            .forget_up       = try mm.allocOnGPU(lr * d * eb, device_id),
            .inject_key      = try mm.allocOnGPU(d * hr * eb, device_id),
            .inject_val      = try mm.allocOnGPU(d * hr * eb, device_id),
            .inject_query    = try mm.allocOnGPU(d * (local_heads * cfg.head_dim) * eb, device_id),
            .inject_out      = try mm.allocOnGPU((local_heads * cfg.head_dim) * d * eb, device_id),
            .predictor_up1   = try mm.allocOnGPU(d * cfg.ffn_dim / tp * eb, device_id),
            .predictor_up2   = try mm.allocOnGPU(d * cfg.ffn_dim / tp * eb, device_id),
            .predictor_down  = try mm.allocOnGPU(cfg.ffn_dim / tp * d * eb, device_id),
            .anchor_proj     = try mm.allocOnGPU(d * d * eb, device_id),
            .norm1_scale     = try mm.allocOnGPU(d * @sizeOf(f32), device_id),
            .norm1_bias      = try mm.allocOnGPU(d * @sizeOf(f32), device_id),
            .norm2_scale     = try mm.allocOnGPU(d * @sizeOf(f32), device_id),
            .norm2_bias      = try mm.allocOnGPU(d * @sizeOf(f32), device_id),
            .device_id       = device_id,
        };
    }

    pub fn deinit(self: *PRISMLayerWeights) void {
        self.forget_down.freeGPU();
        self.forget_up.freeGPU();
        self.inject_key.freeGPU();
        self.inject_val.freeGPU();
        self.inject_query.freeGPU();
        self.inject_out.freeGPU();
        self.predictor_up1.freeGPU();
        self.predictor_up2.freeGPU();
        self.predictor_down.freeGPU();
        self.anchor_proj.freeGPU();
        self.norm1_scale.freeGPU();
        self.norm1_bias.freeGPU();
        self.norm2_scale.freeGPU();
        self.norm2_bias.freeGPU();
    }

    pub fn serialize(self: *const PRISMLayerWeights, writer: anytype) !void {
        const blocks = [_]mem.MemoryBlock{
            self.forget_down,  self.forget_up,
            self.inject_key,   self.inject_val,
            self.inject_query, self.inject_out,
            self.predictor_up1, self.predictor_up2,
            self.predictor_down, self.anchor_proj,
            self.norm1_scale,  self.norm1_bias,
            self.norm2_scale,  self.norm2_bias,
        };
        for (blocks) |block| {
            if (block.gpu_ptr == null) {
                try writer.writeInt(u64, 0, .little);
                continue;
            }
            var cpu_buf = try std.heap.page_allocator.alloc(u8, block.size_bytes);
            defer std.heap.page_allocator.free(cpu_buf);
            _ = c.cudaMemcpy(cpu_buf.ptr, block.gpu_ptr.?, block.size_bytes, c.cudaMemcpyDeviceToHost);
            try writer.writeInt(u64, block.size_bytes, .little);
            try writer.writeAll(cpu_buf);
        }
    }

    pub fn deserialize(self: *PRISMLayerWeights, reader: anytype) !void {
        var blocks = [_]*mem.MemoryBlock{
            &self.forget_down,  &self.forget_up,
            &self.inject_key,   &self.inject_val,
            &self.inject_query, &self.inject_out,
            &self.predictor_up1, &self.predictor_up2,
            &self.predictor_down, &self.anchor_proj,
            &self.norm1_scale,  &self.norm1_bias,
            &self.norm2_scale,  &self.norm2_bias,
        };
        for (blocks) |block| {
            const size = try reader.readInt(u64, .little);
            if (size == 0) continue;
            var cpu_buf = try std.heap.page_allocator.alloc(u8, size);
            defer std.heap.page_allocator.free(cpu_buf);
            _ = try reader.readAll(cpu_buf);
            if (block.gpu_ptr) |ptr| {
                _ = c.cudaMemcpy(ptr, cpu_buf.ptr, size, c.cudaMemcpyHostToDevice);
            }
        }
    }
};

pub const PRISMModel = struct {
    config: PRISMConfig,
    layers: []PRISMLayerWeights,
    embedding: mem.MemoryBlock,
    lm_head: mem.MemoryBlock,
    final_norm_scale: mem.MemoryBlock,
    final_norm_bias: mem.MemoryBlock,
    grad_embedding: mem.MemoryBlock,
    grad_lm_head: mem.MemoryBlock,
    anchor_cache: []mem.MemoryBlock,
    cublas_handles: []c.cublasHandle_t,
    mm: *mem.MemoryManager,
    comm: *nccl.NcclComm,
    allocator: std.mem.Allocator,

    pub fn init(
        config_in: anytype,
        mm: *mem.MemoryManager,
        comm: *nccl.NcclComm,
        allocator: std.mem.Allocator,
    ) !PRISMModel {
        const cfg = PRISMConfig{
            .model_dim = config_in.model_dim,
            .num_layers = config_in.num_layers,
            .num_heads = config_in.num_heads,
            .head_dim = config_in.head_dim,
            .ffn_dim = config_in.ffn_dim,
            .vocab_size = config_in.vocab_size,
            .max_seq_len = config_in.max_seq_len,
            .num_gpus = config_in.num_gpus,
            .tensor_parallel_degree = config_in.tensor_parallel_degree,
            .precision = config_in.precision,
        };

        const layers = try allocator.alloc(PRISMLayerWeights, cfg.num_layers);
        for (layers, 0..) |*layer, i| {
            const dev: i32 = @intCast(i % cfg.num_gpus);
            layer.* = try PRISMLayerWeights.init(cfg, dev, mm);
        }

        const embed_eb = mem.precisionBytes(cfg.precision);
        const embed_size = cfg.vocab_size * cfg.model_dim * embed_eb;
        const norm_size = cfg.model_dim * @sizeOf(f32);

        const num_anchor_slots = cfg.num_layers * cfg.num_anchors;
        const anchor_cache = try allocator.alloc(mem.MemoryBlock, num_anchor_slots);
        for (anchor_cache, 0..) |*ac, i| {
            const dev: i32 = @intCast((i / cfg.num_anchors) % cfg.num_gpus);
            const anchor_size = cfg.model_dim * @sizeOf(f32);
            ac.* = try mm.allocOnGPU(anchor_size, dev);
        }

        const cublas_handles = try allocator.alloc(c.cublasHandle_t, cfg.num_gpus);
        for (cublas_handles, 0..) |*h, i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cublasCreate(h);
            _ = c.cublasSetMathMode(h.*, c.CUBLAS_TENSOR_OP_MATH);
        }

        return PRISMModel{
            .config = cfg,
            .layers = layers,
            .embedding = try mm.allocOnGPU(embed_size, 0),
            .lm_head = try mm.allocOnGPU(embed_size, 0),
            .final_norm_scale = try mm.allocOnGPU(norm_size, 0),
            .final_norm_bias = try mm.allocOnGPU(norm_size, 0),
            .grad_embedding = try mm.allocOnGPU(embed_size, 0),
            .grad_lm_head = try mm.allocOnGPU(embed_size, 0),
            .anchor_cache = anchor_cache,
            .cublas_handles = cublas_handles,
            .mm = mm,
            .comm = comm,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *PRISMModel) void {
        for (self.layers) |*l| l.deinit();
        self.allocator.free(self.layers);
        self.embedding.freeGPU();
        self.lm_head.freeGPU();
        self.final_norm_scale.freeGPU();
        self.final_norm_bias.freeGPU();
        self.grad_embedding.freeGPU();
        self.grad_lm_head.freeGPU();
        for (self.anchor_cache) |*ac| ac.freeGPU();
        self.allocator.free(self.anchor_cache);
        for (self.cublas_handles, 0..) |h, i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cublasDestroy(h);
        }
        self.allocator.free(self.cublas_handles);
    }

    pub fn forwardChunk(
        self: *PRISMModel,
        tokens: []u32,
        global_offset: u64,
    ) !f64 {
        const seq_len = tokens.len;
        const d = self.config.model_dim;

        var token_gpu = try self.mm.allocOnGPU(seq_len * @sizeOf(u32), 0);
        defer token_gpu.freeGPU();
        _ = c.cudaMemcpy(token_gpu.gpu_ptr.?, tokens.ptr, seq_len * @sizeOf(u32), c.cudaMemcpyHostToDevice);

        var hidden = try self.mm.allocOnGPU(seq_len * d * @sizeOf(f32), 0);
        defer hidden.freeGPU();

        launchEmbeddingForwardPRISM(
            @ptrCast(token_gpu.gpu_ptr.?),
            @ptrCast(self.embedding.gpu_ptr.?),
            @ptrCast(hidden.gpu_ptr.?),
            @intCast(seq_len), d, 0,
            self.mm.getStream(0),
        );

        for (self.layers, 0..) |*layer, layer_idx| {
            const dev: i32 = @intCast(layer_idx % self.config.num_gpus);
            _ = c.cudaSetDevice(dev);
            const stream = self.mm.getStream(dev);

            launchRMSNormPRISM(
                @ptrCast(hidden.gpu_ptr.?),
                @ptrCast(layer.norm1_scale.gpu_ptr.?),
                @ptrCast(layer.norm1_bias.gpu_ptr.?),
                @intCast(seq_len), d, dev, stream,
            );

            const anchor_start = layer_idx * self.config.num_anchors;
            var anchor_ptrs: [32]*anyopaque = undefined;
            const num_valid_anchors = @min(self.config.num_anchors, self.anchor_cache.len - anchor_start);
            for (0..num_valid_anchors) |ai| {
                anchor_ptrs[ai] = self.anchor_cache[anchor_start + ai].gpu_ptr.?;
            }

            launchPRISMForgetInject(
                @ptrCast(hidden.gpu_ptr.?),
                @ptrCast(layer.forget_down.gpu_ptr.?),
                @ptrCast(layer.forget_up.gpu_ptr.?),
                @ptrCast(layer.inject_key.gpu_ptr.?),
                @ptrCast(layer.inject_val.gpu_ptr.?),
                @ptrCast(layer.inject_query.gpu_ptr.?),
                @ptrCast(layer.inject_out.gpu_ptr.?),
                @ptrCast(anchor_ptrs[0]),
                @intCast(seq_len), d,
                self.config.low_rank_forget,
                self.config.high_rank_inject,
                @intCast(num_valid_anchors),
                self.config.anchor_stride,
                @intCast(global_offset),
                dev, stream,
            );

            launchRMSNormPRISM(
                @ptrCast(hidden.gpu_ptr.?),
                @ptrCast(layer.norm2_scale.gpu_ptr.?),
                @ptrCast(layer.norm2_bias.gpu_ptr.?),
                @intCast(seq_len), d, dev, stream,
            );

            launchSwiGLUFFNPRISM(
                @ptrCast(hidden.gpu_ptr.?),
                @ptrCast(layer.predictor_up1.gpu_ptr.?),
                @ptrCast(layer.predictor_up2.gpu_ptr.?),
                @ptrCast(layer.predictor_down.gpu_ptr.?),
                @intCast(seq_len), d,
                self.config.ffn_dim / self.config.tensor_parallel_degree,
                dev, stream,
            );

            if (self.config.tensor_parallel_degree > 1) {
                const elems = seq_len * d / self.config.tensor_parallel_degree;
                try self.comm.allReduceSum(
                    hidden.gpu_ptr.?, hidden.gpu_ptr.?,
                    elems, c.ncclFloat32, @intCast(dev),
                );
            }
        }

        launchRMSNormPRISM(
            @ptrCast(hidden.gpu_ptr.?),
            @ptrCast(self.final_norm_scale.gpu_ptr.?),
            @ptrCast(self.final_norm_bias.gpu_ptr.?),
            @intCast(seq_len), d, 0,
            self.mm.getStream(0),
        );

        var logits = try self.mm.allocOnGPU(seq_len * self.config.vocab_size * @sizeOf(f32), 0);
        defer logits.freeGPU();
        var loss_buf = try self.mm.allocOnGPU(@sizeOf(f32), 0);
        defer loss_buf.freeGPU();

        launchLMHeadAndLossPRISM(
            @ptrCast(hidden.gpu_ptr.?),
            @ptrCast(self.lm_head.gpu_ptr.?),
            @ptrCast(token_gpu.gpu_ptr.?),
            @ptrCast(logits.gpu_ptr.?),
            @ptrCast(loss_buf.gpu_ptr.?),
            @intCast(seq_len), d,
            self.config.vocab_size,
            0, self.mm.getStream(0),
        );

        var loss_host: f32 = 0.0;
        _ = c.cudaMemcpy(&loss_host, loss_buf.gpu_ptr.?, @sizeOf(f32), c.cudaMemcpyDeviceToHost);
        return @as(f64, loss_host);
    }

    pub fn updateAnchors(
        self: *PRISMModel,
        layer_idx: u32,
        hidden: *anyopaque,
        seq_len: usize,
        global_offset: u64,
    ) void {
        const stride = self.config.anchor_stride;
        const num_anchors = self.config.num_anchors;
        const anchor_start = layer_idx * num_anchors;
        var anchor_idx: u32 = 0;
        var t: u64 = 0;
        while (t < seq_len and anchor_idx < num_anchors) : (t += stride) {
            const actual_pos = global_offset + t;
            _ = actual_pos;
            const hidden_t: *anyopaque = @ptrFromInt(
                @intFromPtr(hidden) + t * self.config.model_dim * @sizeOf(f32),
            );
            const anchor = &self.anchor_cache[anchor_start + anchor_idx];
            _ = c.cudaMemcpyAsync(
                anchor.gpu_ptr.?,
                hidden_t,
                self.config.model_dim * @sizeOf(f32),
                c.cudaMemcpyDeviceToDevice,
                self.mm.getStream(0),
            );
            anchor_idx += 1;
        }
    }
};

extern fn launchEmbeddingForwardPRISM(
    tokens: [*]u32, embed_table: [*]f32, output: [*]f32,
    seq_len: c_int, model_dim: c_uint, device_id: c_int,
    stream: c.cudaStream_t,
) void;

extern fn launchRMSNormPRISM(
    hidden: [*]f32, scale: [*]f32, bias: [*]f32,
    seq_len: c_int, model_dim: c_uint, device_id: c_int,
    stream: c.cudaStream_t,
) void;

extern fn launchPRISMForgetInject(
    hidden: [*]f32,
    forget_down: [*]f32, forget_up: [*]f32,
    inject_key: [*]f32, inject_val: [*]f32,
    inject_query: [*]f32, inject_out: [*]f32,
    anchors: *anyopaque,
    seq_len: c_int, model_dim: c_uint,
    low_rank: c_uint, high_rank: c_uint,
    num_anchors: c_uint, anchor_stride: c_uint,
    global_offset: c_long,
    device_id: c_int, stream: c.cudaStream_t,
) void;

extern fn launchSwiGLUFFNPRISM(
    hidden: [*]f32,
    up1: [*]f32, up2: [*]f32, down: [*]f32,
    seq_len: c_int, model_dim: c_uint, ffn_dim: c_uint,
    device_id: c_int, stream: c.cudaStream_t,
) void;

extern fn launchLMHeadAndLossPRISM(
    hidden: [*]f32, lm_head: [*]f32,
    targets: [*]u32, logits_out: [*]f32, loss_out: [*]f32,
    seq_len: c_int, model_dim: c_uint, vocab_size: c_uint,
    device_id: c_int, stream: c.cudaStream_t,
) void;
