import "mxfp8"

let sigmoid (x: f32) : f32 = 1.0f32 / (1.0f32 + f32.exp (-x))
let silu (x: f32) : f32 = x * sigmoid x
let softmax [n] (xs: [n]f32) : [n]f32 =
  let m = f32.maximum xs
  let exps = map (\x -> f32.exp (x - m)) xs
  let s = f32.sum exps
  in map (\e -> e / s) exps

let rms_norm [n] (x: [n]f32) (scale: [n]f32) (eps: f32) : [n]f32 =
  let sq_sum = f32.sum (map (\xi -> xi * xi) x)
  let rms = f32.sqrt (sq_sum / f32.i64 n + eps)
  in map2 (\xi si -> xi / rms * si) x scale

let low_rank_transform [d] [r] (x: [d]f32) (down: [d][r]f32) (up: [r][d]f32) : [d]f32 =
  let low = map (\col -> f32.sum (map2 (*) x col)) (transpose down)
  let gated = map silu low
  let out = map (\col -> f32.sum (map2 (*) gated col)) (transpose up)
  in map2 (+) x out

let high_rank_attend [d] [hr] [na]
    (query: [d]f32)
    (keys: [hr][d]f32)
    (vals: [hr][d]f32)
    (anchors: [na][d]f32)
    : [d]f32 =
  let q_proj = map (\ki -> f32.sum (map2 (*) query ki)) keys
  let anchor_scores = map (\anc ->
    let q_anc = map (\ki -> f32.sum (map2 (*) anc ki)) keys
    in f32.sum (map2 (*) q_proj q_anc)
  ) anchors
  let weights = softmax anchor_scores
  in map (\j ->
    f32.sum (map2 (\w anc -> w * anc[j]) weights anchors)
  ) (iota d)

entry prism_forward_chunk
    [seq] [d] [lr] [hr] [na]
    (hidden: [seq][d]f32)
    (forget_down: [d][lr]f32)
    (forget_up: [lr][d]f32)
    (inject_key: [d][hr]f32)
    (inject_val: [d][hr]f32)
    (inject_query: [d][d]f32)
    (inject_out: [d][d]f32)
    (anchors: [na][d]f32)
    (norm_scale: [d]f32)
    (anchor_stride: i64)
    (global_offset: i64)
    : ([seq][d]f32, [na][d]f32) =
  let normed = map (\h -> rms_norm h norm_scale 1e-6f32) hidden
  let after_forget = map (\h -> low_rank_transform h forget_down forget_up) normed
  let keys_hr = map (\col -> f32.sum) (transpose inject_key)
  let vals_hr = map (\col -> f32.sum) (transpose inject_val)
  let inject_keys_matrix: [hr][d]f32 = map (\ri ->
    map (\di -> inject_key[di][ri]) (iota d)
  ) (iota hr)
  let inject_vals_matrix: [hr][d]f32 = map (\ri ->
    map (\di -> inject_val[di][ri]) (iota d)
  ) (iota hr)
  let injected = map (\h ->
    let q = map (\col -> f32.sum (map2 (*) h col)) (transpose inject_query)
    let mem_out = high_rank_attend q inject_keys_matrix inject_vals_matrix anchors
    let proj_out = map (\col -> f32.sum (map2 (*) mem_out col)) (transpose inject_out)
    in map2 (+) h proj_out
  ) after_forget
  let new_anchors =
    map (\ai ->
      let t = i64.i64 ai * anchor_stride
      in if t < seq
         then injected[t]
         else anchors[ai]
    ) (iota na)
  in (injected, new_anchors)

entry prism_swiglu_ffn
    [seq] [d] [ffn_d]
    (hidden: [seq][d]f32)
    (up1: [d][ffn_d]f32)
    (up2: [d][ffn_d]f32)
    (down: [ffn_d][d]f32)
    (norm_scale: [d]f32)
    : [seq][d]f32 =
  let normed = map (\h -> rms_norm h norm_scale 1e-6f32) hidden
  let intermediate = map (\h ->
    let g1 = map (\col -> f32.sum (map2 (*) h col)) (transpose up1)
    let g2 = map (\col -> f32.sum (map2 (*) h col)) (transpose up2)
    in map2 (\a b -> silu a * b) g1 g2
  ) normed
  let out = map (\inter ->
    map (\col -> f32.sum (map2 (*) inter col)) (transpose down)
  ) intermediate
  in map2 (map2 (+)) hidden out

entry prism_cross_entropy_loss
    [seq] [vocab]
    (logits: [seq][vocab]f32)
    (targets: [seq]i32)
    : f32 =
  let losses = map2 (\logit_row target ->
    let m = f32.maximum logit_row
    let shifted = map (\l -> l - m) logit_row
    let log_sum_exp = m + f32.log (f32.sum (map f32.exp shifted))
    in log_sum_exp - logit_row[target]
  ) logits targets
  in f32.sum losses / f32.i64 seq

entry prism_update_anchors
    [seq] [d] [na]
    (hidden: [seq][d]f32)
    (old_anchors: [na][d]f32)
    (anchor_stride: i64)
    : [na][d]f32 =
  map (\ai ->
    let t = i64.i64 ai * anchor_stride
    in if t < seq then hidden[t] else old_anchors[ai]
  ) (iota na)

entry prism_compute_forget_gate
    [seq] [d] [lr]
    (hidden: [seq][d]f32)
    (forget_down: [d][lr]f32)
    (forget_up: [lr][d]f32)
    : [seq][d]f32 =
  map (\h ->
    let low = map (\col -> f32.sum (map2 (*) h col)) (transpose forget_down)
    let gated = map silu low
    let delta = map (\col -> f32.sum (map2 (*) gated col)) (transpose forget_up)
    in map2 (+) h delta
  ) hidden

entry prism_backward_forget
    [seq] [d] [lr]
    (hidden: [seq][d]f32)
    (forget_down: [d][lr]f32)
    (forget_up: [lr][d]f32)
    (grad_out: [seq][d]f32)
    : ([d][lr]f32, [lr][d]f32, [seq][d]f32) =
  let grad_down = map (\di ->
    map (\ri ->
      f32.sum (map2 (\h go ->
        let low = map (\col -> f32.sum (map2 (*) h col)) (transpose forget_down)
        let silu_low = map silu low
        let dsilu = silu_low[ri] * (1.0f32 - silu_low[ri]) + silu_low[ri]
        in go[di] * forget_up[ri][di] * dsilu * h[di]
      ) hidden grad_out)
    ) (iota lr)
  ) (iota d)
  let grad_up = map (\ri ->
    map (\di ->
      f32.sum (map2 (\h go ->
        let low = map (\col -> f32.sum (map2 (*) h col)) (transpose forget_down)
        let silu_low = map silu low
        in go[di] * silu_low[ri]
      ) hidden grad_out)
    ) (iota d)
  ) (iota lr)
  let grad_hidden = map2 (map2 (+)) grad_out
    (map (\h ->
      let low = map (\col -> f32.sum (map2 (*) h col)) (transpose forget_down)
      let silu_low = map silu low
      let delta = map (\col -> f32.sum (map2 (*) silu_low col)) (transpose forget_up)
      in delta
    ) hidden)
  in (grad_down, grad_up, grad_hidden)
