#include <cuda_runtime.h>
#include <nccl.h>
#include <stdint.h>
#include <stdio.h>
#include "cuda_helpers.h"

__global__ void scatter_tokens_to_hidden_kernel(
    const uint32_t* __restrict__ tokens,
    const float* __restrict__ embed_table,
    float* __restrict__ output,
    int seq_len,
    unsigned int model_dim,
    uint64_t global_offset
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= seq_len || d >= (int)model_dim) return;
    uint32_t tok_id = tokens[t];
    output[t * model_dim + d] = embed_table[tok_id * model_dim + d];
    (void)global_offset;
}

extern "C" void launchScatterTokensToHidden(
    uint32_t* tokens,
    float* embed_table,
    float* output,
    int seq_len,
    unsigned int model_dim,
    uint64_t global_offset,
    int device_id,
    cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)model_dim, threads);
    dim3 grid(seq_len, blocks_d);
    scatter_tokens_to_hidden_kernel<<<grid, threads, 0, stream>>>(
        tokens, embed_table, output, seq_len, model_dim, global_offset
    );
}

__global__ void copy_anchor_left_kernel(
    const float* __restrict__ src_hidden,
    float* __restrict__ dst_anchor,
    int overlap,
    int seq_len,
    unsigned int model_dim
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= overlap || d >= (int)model_dim) return;
    int src_t = seq_len - overlap + t;
    dst_anchor[t * model_dim + d] = src_hidden[src_t * model_dim + d];
}

__global__ void copy_anchor_right_kernel(
    const float* __restrict__ src_hidden,
    float* __restrict__ dst_anchor,
    int overlap,
    unsigned int model_dim
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= overlap || d >= (int)model_dim) return;
    dst_anchor[t * model_dim + d] = src_hidden[t * model_dim + d];
}

extern "C" void launchExtractLeftAnchor(
    float* hidden, float* anchor_buf,
    int overlap, int seq_len, unsigned int model_dim,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)model_dim, threads);
    dim3 grid(overlap, blocks_d);
    copy_anchor_left_kernel<<<grid, threads, 0, stream>>>(
        hidden, anchor_buf, overlap, seq_len, model_dim
    );
}

extern "C" void launchExtractRightAnchor(
    float* hidden, float* anchor_buf,
    int overlap, unsigned int model_dim,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)model_dim, threads);
    dim3 grid(overlap, blocks_d);
    copy_anchor_right_kernel<<<grid, threads, 0, stream>>>(
        hidden, anchor_buf, overlap, model_dim
    );
}

__global__ void merge_anchor_into_hidden_kernel(
    float* __restrict__ hidden,
    const float* __restrict__ anchor,
    int overlap,
    int seq_len,
    unsigned int model_dim,
    float alpha
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= overlap || d >= (int)model_dim) return;
    int pos = seq_len - overlap + t;
    hidden[pos * model_dim + d] = (1.0f - alpha) * hidden[pos * model_dim + d]
                                 + alpha * anchor[t * model_dim + d];
}

extern "C" void launchMergeAnchorIntoHidden(
    float* hidden, float* anchor,
    int overlap, int seq_len, unsigned int model_dim,
    float alpha, int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)model_dim, threads);
    dim3 grid(overlap, blocks_d);
    merge_anchor_into_hidden_kernel<<<grid, threads, 0, stream>>>(
        hidden, anchor, overlap, seq_len, model_dim, alpha
    );
}

__global__ void ring_allreduce_prepare_kernel(
    const float* __restrict__ input,
    float* __restrict__ send_buf,
    int chunk_size,
    int rank,
    int world_size,
    unsigned int total_elements
) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    int shard_size = (total_elements + world_size - 1) / world_size;
    int start = rank * shard_size;
    int local_idx = idx;
    if (local_idx >= chunk_size) return;
    int global_idx = start + local_idx;
    if ((unsigned int)global_idx >= total_elements) {
        send_buf[local_idx] = 0.0f;
        return;
    }
    send_buf[local_idx] = input[global_idx];
}

__global__ void ring_allreduce_accumulate_kernel(
    float* __restrict__ local_buf,
    const float* __restrict__ recv_buf,
    int chunk_size
) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx >= chunk_size) return;
    local_buf[idx] += recv_buf[idx];
}

__global__ void ring_allreduce_scatter_kernel(
    const float* __restrict__ final_shard,
    float* __restrict__ output,
    int shard_size,
    int rank,
    unsigned int total_elements
) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx >= shard_size) return;
    int global_idx = rank * shard_size + idx;
    if ((unsigned int)global_idx < total_elements) {
        output[global_idx] = final_shard[idx];
    }
}

extern "C" void launchRingAllReducePrepare(
    float* input, float* send_buf,
    int chunk_size, int rank, int world_size, unsigned int total_elements,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 512;
    int blocks = DIV_CEIL(chunk_size, threads);
    ring_allreduce_prepare_kernel<<<blocks, threads, 0, stream>>>(
        input, send_buf, chunk_size, rank, world_size, total_elements
    );
}

extern "C" void launchRingAllReduceAccumulate(
    float* local_buf, float* recv_buf, int chunk_size,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 512;
    int blocks = DIV_CEIL(chunk_size, threads);
    ring_allreduce_accumulate_kernel<<<blocks, threads, 0, stream>>>(
        local_buf, recv_buf, chunk_size
    );
}

extern "C" void launchRingAllReduceScatter(
    float* final_shard, float* output,
    int shard_size, int rank, unsigned int total_elements,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 512;
    int blocks = DIV_CEIL(shard_size, threads);
    ring_allreduce_scatter_kernel<<<blocks, threads, 0, stream>>>(
        final_shard, output, shard_size, rank, total_elements
    );
}

__global__ void reduce_scatter_grad_kernel(
    float* __restrict__ grad_flat,
    float* __restrict__ local_shard,
    int shard_size,
    int rank,
    int world_size,
    unsigned int total_elements
) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx >= shard_size) return;
    int global_idx = rank * shard_size + idx;
    if ((unsigned int)global_idx < total_elements) {
        local_shard[idx] = grad_flat[global_idx];
    }
}

extern "C" void launchReduceScatterGrad(
    float* grad_flat, float* local_shard,
    int shard_size, int rank, int world_size, unsigned int total_elements,
    int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 512;
    int blocks = DIV_CEIL(shard_size, threads);
    reduce_scatter_grad_kernel<<<blocks, threads, 0, stream>>>(
        grad_flat, local_shard, shard_size, rank, world_size, total_elements
    );
}

__global__ void tensor_parallel_split_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int seq_len,
    unsigned int full_dim,
    unsigned int local_dim,
    int rank
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= seq_len || d >= (int)local_dim) return;
    int global_d = rank * (int)local_dim + d;
    if ((unsigned int)global_d < full_dim) {
        output[t * local_dim + d] = input[t * full_dim + global_d];
    }
}

extern "C" void launchTensorParallelSplit(
    float* input, float* output,
    int seq_len, unsigned int full_dim, unsigned int local_dim,
    int rank, int device_id, cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)local_dim, threads);
    dim3 grid(seq_len, blocks_d);
    tensor_parallel_split_kernel<<<grid, threads, 0, stream>>>(
        input, output, seq_len, full_dim, local_dim, rank
    );
}

__global__ void positional_encoding_add_kernel(
    float* __restrict__ hidden,
    int seq_len,
    unsigned int model_dim,
    uint64_t global_offset,
    float theta_base
) {
    int t = blockIdx.x;
    int d = threadIdx.x + blockIdx.y * blockDim.x;
    if (t >= seq_len || d >= (int)(model_dim / 2)) return;

    uint64_t pos = (uint64_t)t + global_offset;
    float freq = powf(theta_base, -2.0f * (float)d / (float)model_dim);
    float angle = (float)pos * freq;
    float cos_a = cosf(angle);
    float sin_a = sinf(angle);

    float x0 = hidden[t * model_dim + d];
    float x1 = hidden[t * model_dim + d + model_dim / 2];
    hidden[t * model_dim + d]               = x0 * cos_a - x1 * sin_a;
    hidden[t * model_dim + d + model_dim / 2] = x0 * sin_a + x1 * cos_a;
}

extern "C" void launchPositionalEncodingAdd(
    float* hidden,
    int seq_len,
    unsigned int model_dim,
    uint64_t global_offset,
    float theta_base,
    int device_id,
    cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    int threads = 256;
    int blocks_d = DIV_CEIL((int)(model_dim / 2), threads);
    dim3 grid(seq_len, blocks_d);
    positional_encoding_add_kernel<<<grid, threads, 0, stream>>>(
        hidden, seq_len, model_dim, global_offset, theta_base
    );
}

__global__ void scale_grads_by_world_size_kernel(
    float* __restrict__ grads,
    size_t num_elements,
    float inv_world_size
) {
    size_t idx = threadIdx.x + (size_t)blockIdx.x * blockDim.x;
    if (idx >= num_elements) return;
    grads[idx] *= inv_world_size;
}

extern "C" void launchScaleGradsByWorldSize(
    float* grads,
    size_t num_elements,
    int world_size,
    int device_id,
    cudaStream_t stream
) {
    CUDA_CHECK(cudaSetDevice(device_id));
    float inv_ws = 1.0f / (float)world_size;
    int threads = 512;
    int blocks = (int)DIV_CEIL((int)num_elements, threads);
    scale_grads_by_world_size_kernel<<<blocks, threads, 0, stream>>>(
        grads, num_elements, inv_ws
    );
}
