#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"

ZIG_VERSION="0.13.0"
ZIG_URL=""
ZIG_DIR="${HOME}/.local/zig"

FUTHARK_VERSION="0.25.18"
FUTHARK_URL=""
FUTHARK_DIR="${HOME}/.local/futhark"

MODAL_VERSION="0.73.0"

log() { echo "[setup] $*"; }
err() { echo "[setup] ERROR: $*" >&2; exit 1; }

command_exists() { command -v "$1" >/dev/null 2>&1; }

install_system_deps() {
    log "Installing system dependencies..."
    if command_exists apt-get; then
        sudo apt-get update -qq
        sudo apt-get install -y --no-install-recommends \
            curl wget tar xz-utils \
            build-essential \
            python3 python3-pip python3-venv \
            git ca-certificates \
            libssl-dev \
            2>/dev/null || true
    elif command_exists yum; then
        sudo yum install -y curl wget tar xz gcc python3 python3-pip git openssl-devel 2>/dev/null || true
    fi
    log "System deps: OK"
}

install_zig() {
    if command_exists zig; then
        local ver
        ver=$(zig version 2>/dev/null || echo "unknown")
        log "Zig already installed: $ver"
        return 0
    fi

    log "Installing Zig ${ZIG_VERSION}..."
    mkdir -p "${ZIG_DIR}"
    local tmp
    tmp=$(mktemp -d)
    wget -q "${ZIG_URL}" -O "${tmp}/zig.tar.xz" || err "Failed to download Zig"
    tar -xf "${tmp}/zig.tar.xz" -C "${tmp}/"
    mv "${tmp}/zig-linux-x86_64-${ZIG_VERSION}"/* "${ZIG_DIR}/"
    rm -rf "${tmp}"

    local bin_link="${HOME}/.local/bin/zig"
    mkdir -p "$(dirname "$bin_link")"
    ln -sf "${ZIG_DIR}/zig" "$bin_link"

    if ! echo "$PATH" | grep -q "${HOME}/.local/bin"; then
        export PATH="${HOME}/.local/bin:$PATH"
        echo 'export PATH="$HOME/.local/bin:$PATH"' >> "${HOME}/.bashrc"
        echo 'export PATH="$HOME/.local/bin:$PATH"' >> "${HOME}/.profile"
    fi

    zig version || err "Zig installation failed"
    log "Zig ${ZIG_VERSION}: OK"
}

install_futhark() {
    if command_exists futhark; then
        local ver
        ver=$(futhark --version 2>/dev/null | head -1 || echo "unknown")
        log "Futhark already installed: $ver"
        return 0
    fi

    log "Installing Futhark ${FUTHARK_VERSION}..."
    mkdir -p "${FUTHARK_DIR}"
    local tmp
    tmp=$(mktemp -d)
    wget -q "${FUTHARK_URL}" -O "${tmp}/futhark.tar.xz" || err "Failed to download Futhark"
    tar -xf "${tmp}/futhark.tar.xz" -C "${tmp}/"
    mv "${tmp}/futhark-nightly-linux-x86-64"/* "${FUTHARK_DIR}/"
    rm -rf "${tmp}"

    local bin_link="${HOME}/.local/bin/futhark"
    ln -sf "${FUTHARK_DIR}/bin/futhark" "$bin_link"

    futhark --version || err "Futhark installation failed"
    log "Futhark: OK"
}

install_python_deps() {
    log "Installing Python dependencies..."
    if ! command_exists pip3 && ! command_exists pip; then
        err "pip not found. Install Python 3 first."
    fi

    local pip_cmd
    pip_cmd=$(command_exists pip3 && echo "pip3" || echo "pip")

    "${pip_cmd}" install --quiet --upgrade pip
    "${pip_cmd}" install --quiet \
        "modal==${MODAL_VERSION}" \
        huggingface_hub \
        datasets \
        tokenizers \
        numpy \
        tqdm \
        psutil \
        py-cpuinfo \
        requests

    modal --version || err "Modal installation failed"
    log "Python deps: OK"
}

setup_modal_auth() {
    log "Checking Modal authentication..."
    if modal token list >/dev/null 2>&1; then
        log "Modal: already authenticated"
        return 0
    fi
    log "Modal token not found. Run 'modal token new' to authenticate."
    log "Or set MODAL_TOKEN_ID and MODAL_TOKEN_SECRET environment variables."
}

create_directory_structure() {
    log "Creating project directory structure..."
    local dirs=(
        "${PROJECT_ROOT}/src/runtime"
        "${PROJECT_ROOT}/src/model"
        "${PROJECT_ROOT}/src/optimizer"
        "${PROJECT_ROOT}/src/eval"
        "${PROJECT_ROOT}/kernels"
        "${PROJECT_ROOT}/include"
        "${PROJECT_ROOT}/data_prep"
        "${PROJECT_ROOT}/scripts"
        "${PROJECT_ROOT}/vocab"
        "${PROJECT_ROOT}/tests"
    )
    for d in "${dirs[@]}"; do
        mkdir -p "$d"
        log "  created: $d"
    done
    log "Directory structure: OK"
}

check_modal_secrets() {
    log "Checking Modal secrets..."
    if modal secret list 2>/dev/null | grep -q "hf-token"; then
        log "  hf-token: FOUND"
    else
        log "  hf-token: NOT FOUND"
        log "  Create it with: modal secret create hf-token HF_TOKEN=<your-token>"
    fi
}

verify_installation() {
    log ""
    log "=== Installation Verification ==="
    local ok=true

    for tool in zig futhark python3 modal; do
        if command_exists "$tool"; then
            local ver
            ver=$("$tool" --version 2>/dev/null | head -1 || echo "?")
            log "  OK: $tool ($ver)"
        else
            log "  MISSING: $tool"
            ok=false
        fi
    done

    local required_files=(
        "${PROJECT_ROOT}/build.zig"
        "${PROJECT_ROOT}/src/main.zig"
        "${PROJECT_ROOT}/kernels/efla.fut"
        "${PROJECT_ROOT}/kernels/mxfp8.fut"
        "${PROJECT_ROOT}/kernels/efla_kernels.cu"
        "${PROJECT_ROOT}/kernels/optimizer_kernels.cu"
        "${PROJECT_ROOT}/modal_deploy.py"
        "${PROJECT_ROOT}/replit_runner.py"
    )

    log ""
    log "  Project files:"
    for f in "${required_files[@]}"; do
        if [[ -f "$f" ]]; then
            local size
            size=$(wc -c < "$f")
            log "    OK: $(basename $f) (${size} bytes)"
        else
            log "    MISSING: $f"
            ok=false
        fi
    done

    log ""
    if [[ "$ok" == "true" ]]; then
        log "=== All checks PASSED ==="
    else
        log "=== Some checks FAILED ==="
        return 1
    fi
}

print_next_steps() {
    log ""
    log "=== Next Steps ==="
    log "1. Authenticate Modal:"
    log "   modal token new"
    log ""
    log "2. Create HuggingFace secret:"
    log "   modal secret create hf-token HF_TOKEN=<your-hf-token>"
    log ""
    log "3. Run Phase 1 validation (single GPU):"
    log "   python3 replit_runner.py phase1"
    log ""
    log "4. Run Phase 2 validation (8 GPUs):"
    log "   python3 replit_runner.py phase2"
    log ""
    log "5. Prepare training data:"
    log "   python3 replit_runner.py data_prep"
    log ""
    log "6. Launch full 1T training:"
    log "   python3 replit_runner.py train"
    log ""
    log "Or run full pipeline at once:"
    log "   python3 replit_runner.py full-pipeline"
}

main() {
    log "Underdog 1T LLM - Replit Environment Setup"
    log "============================================"

    install_system_deps
    install_zig
    install_futhark
    install_python_deps
    setup_modal_auth
    create_directory_structure
    check_modal_secrets
    verify_installation
    print_next_steps
}

main "$@"
