**`src/runtime/fault_tolerance.zig`**
```zig
const std = @import("std");
const checkpoint = @import("checkpoint.zig");
const mem = @import("memory.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("signal.h");
});

pub const FaultTolerance = struct {
    checkpoint_mgr: *checkpoint.CheckpointManager,
    last_safe_step: u64,
    watchdog_interval_ms: u64,
    max_consecutive_nan: u32,
    consecutive_nan_count: u32,
    loss_history: std.ArrayList(f64),
    loss_spike_threshold: f64,
    last_watchdog_time: i64,
    allocator: std.mem.Allocator,

    pub fn init(
        checkpoint_mgr: *checkpoint.CheckpointManager,
        watchdog_interval_ms: u64,
        max_consecutive_nan: u32,
        allocator: std.mem.Allocator,
    ) FaultTolerance {
        return FaultTolerance{
            .checkpoint_mgr = checkpoint_mgr,
            .last_safe_step = 0,
            .watchdog_interval_ms = watchdog_interval_ms,
            .max_consecutive_nan = max_consecutive_nan,
            .consecutive_nan_count = 0,
            .loss_history = std.ArrayList(f64).init(allocator),
            .loss_spike_threshold = 10.0,
            .last_watchdog_time = std.time.milliTimestamp(),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *FaultTolerance) void {
        self.loss_history.deinit();
    }

    pub fn recordLoss(self: *FaultTolerance, loss: f64, step: u64) !FaultAction {
        if (std.math.isNan(loss) or std.math.isInf(loss)) {
            self.consecutive_nan_count += 1;
            std.log.warn("NaN/Inf loss at step {} (count: {})", .{
                step, self.consecutive_nan_count,
            });
            if (self.consecutive_nan_count >= self.max_consecutive_nan) {
                std.log.err("Too many NaN losses. Rolling back to step {}.", .{
                    self.last_safe_step,
                });
                return .rollback_to_last_safe;
            }
            return .skip_step;
        }

        self.consecutive_nan_count = 0;

        if (self.loss_history.items.len >= 100) {
            _ = self.loss_history.orderedRemove(0);
        }
        try self.loss_history.append(loss);

        if (self.loss_history.items.len >= 10) {
            const recent_avg = blk: {
                var sum: f64 = 0.0;
                const window = 5;
                const start = self.loss_history.items.len - window;
                for (self.loss_history.items[start..]) |l| sum += l;
                break :blk sum / @as(f64, window);
            };
            const prev_avg = blk: {
                var sum: f64 = 0.0;
                const window = 5;
                const items = self.loss_history.items;
                const end = items.len - window;
                const start = if (end >= window) end - window else 0;
                for (items[start..end]) |l| sum += l;
                break :blk sum / @as(f64, @floatFromInt(end - start));
            };
            if (recent_avg > prev_avg * self.loss_spike_threshold) {
                std.log.warn(
                    "Loss spike detected at step {}: {d:.4} vs baseline {d:.4}",
                    .{ step, recent_avg, prev_avg },
                );
                return .reduce_lr;
            }
        }

        self.last_safe_step = step;
        return .continue_training;
    }

    pub fn runWatchdog(self: *FaultTolerance, num_gpus: u32) !WatchdogResult {
        const now = std.time.milliTimestamp();
        if (now - self.last_watchdog_time < @as(i64, @intCast(self.watchdog_interval_ms))) {
            return .ok;
        }
        self.last_watchdog_time = now;

        for (0..num_gpus) |i| {
            const err = c.cudaSetDevice(@intCast(i));
            if (err != c.cudaSuccess) {
                std.log.err("GPU {} unresponsive: {s}", .{ i, c.cudaGetErrorString(err) });
                return .gpu_failure;
            }
            var free: usize = 0;
            var total: usize = 0;
            const merr = c.cudaMemGetInfo(&free, &total);
            if (merr != c.cudaSuccess) {
                std.log.err("GPU {} memory query failed", .{i});
                return .gpu_failure;
            }
            const used_pct = @as(f64, @floatFromInt(total - free)) /
                @as(f64, @floatFromInt(total)) * 100.0;
            if (used_pct > 98.0) {
                std.log.warn("GPU {} memory critical: {d:.1f}% used", .{ i, used_pct });
                return .oom_warning;
            }
        }
        return .ok;
    }

    pub fn handleAction(
        self: *FaultTolerance,
        action: FaultAction,
        current_step: u64,
        current_lr: *f32,
    ) !bool {
        switch (action) {
            .continue_training => return true,
            .skip_step => return false,
            .reduce_lr => {
                current_lr.* *= 0.5;
                std.log.warn("Reducing LR to {e:.3} at step {}", .{ current_lr.*, current_step });
                return true;
            },
            .rollback_to_last_safe => {
                std.log.err("Rolling back to step {}...", .{self.last_safe_step});
                return false;
            },
            .checkpoint_and_exit => {
                std.log.err("Fault: checkpointing and exiting at step {}", .{current_step});
                return false;
            },
        }
    }
};

pub const FaultAction = enum {
    continue_training,
    skip_step,
    reduce_lr,
    rollback_to_last_safe,
    checkpoint_and_exit,
};

pub const WatchdogResult = enum {
    ok,
    gpu_failure,
    oom_warning,
    network_failure,
};

pub const GracefulShutdown = struct {
    shutdown_requested: std.atomic.Value(bool),
    checkpoint_on_exit: bool,
    allocator: std.mem.Allocator,

    pub fn init(checkpoint_on_exit: bool, allocator: std.mem.Allocator) GracefulShutdown {
        return GracefulShutdown{
            .shutdown_requested = std.atomic.Value(bool).init(false),
            .checkpoint_on_exit = checkpoint_on_exit,
            .allocator = allocator,
        };
    }

    pub fn isShutdownRequested(self: *const GracefulShutdown) bool {
        return self.shutdown_requested.load(.acquire);
    }

    pub fn requestShutdown(self: *GracefulShutdown) void {
        self.shutdown_requested.store(true, .release);
        std.log.info("Graceful shutdown requested.", .{});
    }

    pub fn waitForSafePoint(
        self: *GracefulShutdown,
        current_step: u64,
        checkpoint_interval: u64,
    ) bool {
        if (!self.isShutdownRequested()) return false;
        if (current_step % checkpoint_interval == 0) {
            std.log.info("Shutdown at safe checkpoint step {}", .{current_step});
            return true;
        }
        return false;
    }
};

pub fn installSignalHandlers() void {
    const handler = struct {
        fn handle(sig: c_int) callconv(.C) void {
            std.log.info("Received signal {}, requesting graceful shutdown...", .{sig});
        }
    };
    _ = c.signal(c.SIGINT, handler.handle);
    _ = c.signal(c.SIGTERM, handler.handle);
}

pub fn checkCudaDeviceHealth(num_gpus: u32) bool {
    for (0..num_gpus) |i| {
        if (c.cudaSetDevice(@intCast(i)) != c.cudaSuccess) return false;
        if (c.cudaDeviceSynchronize() != c.cudaSuccess) return false;
        var free: usize = 0;
        var total: usize = 0;
        if (c.cudaMemGetInfo(&free, &total) != c.cudaSuccess) return false;
    }
    return true;
}
