const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cuda_runtime_api.h");
});

pub const Precision = enum {
    fp32,
    fp16,
    bf16,
    fp8_e4m3,
    fp8_e5m2,
    fp4,
};

pub fn precisionBytes(p: Precision) usize {
    return switch (p) {
        .fp32    => 4,
        .fp16    => 2,
        .bf16    => 2,
        .fp8_e4m3, .fp8_e5m2 => 1,
        .fp4     => 1,
    };
}

pub const MemoryBlock = struct {
    gpu_ptr:    ?*anyopaque,
    cpu_ptr:    ?*anyopaque,
    size_bytes: usize,
    device_id:  i32,
    pinned:     bool,

    pub fn allocPinned(size_bytes: usize, device_id: i32) !MemoryBlock {
        _ = c.cudaSetDevice(device_id);
        var ptr: ?*anyopaque = null;
        const err = c.cudaMallocHost(&ptr, size_bytes);
        if (err != c.cudaSuccess) return error.CudaPinnedAllocFailed;
        return MemoryBlock{
            .gpu_ptr    = null,
            .cpu_ptr    = ptr,
            .size_bytes = size_bytes,
            .device_id  = device_id,
            .pinned     = true,
        };
    }

    pub fn freeCPU(self: *MemoryBlock) void {
        if (self.cpu_ptr) |ptr| {
            if (self.pinned) {
                _ = c.cudaFreeHost(ptr);
            } else {
                std.heap.page_allocator.free(@as([*]u8, @ptrCast(ptr))[0..self.size_bytes]);
            }
            self.cpu_ptr = null;
        }
    }

    pub fn freeGPU(self: *MemoryBlock) void {
        if (self.gpu_ptr) |ptr| {
            _ = c.cudaSetDevice(self.device_id);
            _ = c.cudaFree(ptr);
            self.gpu_ptr = null;
        }
    }

    pub fn copyToGPU(self: *MemoryBlock, stream: c.cudaStream_t) !void {
        if (self.cpu_ptr == null or self.gpu_ptr == null) return error.NullPointer;
        _ = c.cudaSetDevice(self.device_id);
        const err = c.cudaMemcpyAsync(
            self.gpu_ptr.?,
            self.cpu_ptr.?,
            self.size_bytes,
            c.cudaMemcpyHostToDevice,
            stream,
        );
        if (err != c.cudaSuccess) return error.CudaMemcpyFailed;
    }

    pub fn copyToCPU(self: *MemoryBlock, stream: c.cudaStream_t) !void {
        if (self.cpu_ptr == null or self.gpu_ptr == null) return error.NullPointer;
        _ = c.cudaSetDevice(self.device_id);
        const err = c.cudaMemcpyAsync(
            self.cpu_ptr.?,
            self.gpu_ptr.?,
            self.size_bytes,
            c.cudaMemcpyDeviceToHost,
            stream,
        );
        if (err != c.cudaSuccess) return error.CudaMemcpyFailed;
    }

    pub fn zero(self: *MemoryBlock, stream: c.cudaStream_t) void {
        if (self.gpu_ptr) |ptr| {
            _ = c.cudaSetDevice(self.device_id);
            _ = c.cudaMemsetAsync(ptr, 0, self.size_bytes, stream);
        }
    }
};

pub const StreamPool = struct {
    streams:    []c.cudaStream_t,
    num_gpus:   u32,
    allocator:  std.mem.Allocator,

    pub fn init(num_gpus: u32, streams_per_gpu: u32, allocator: std.mem.Allocator) !StreamPool {
        const total = num_gpus * streams_per_gpu;
        const streams = try allocator.alloc(c.cudaStream_t, total);
        for (0..num_gpus) |gi| {
            _ = c.cudaSetDevice(@intCast(gi));
            for (0..streams_per_gpu) |si| {
                const idx = gi * streams_per_gpu + si;
                const err = c.cudaStreamCreateWithFlags(&streams[idx], c.cudaStreamNonBlocking);
                if (err != c.cudaSuccess) return error.CudaStreamCreateFailed;
            }
        }
        return StreamPool{
            .streams   = streams,
            .num_gpus  = num_gpus,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StreamPool) void {
        for (self.streams) |stream| {
            _ = c.cudaStreamDestroy(stream);
        }
        self.allocator.free(self.streams);
    }

    pub fn get(self: *const StreamPool, device_id: u32, stream_idx: u32) c.cudaStream_t {
        const streams_per_gpu = self.streams.len / self.num_gpus;
        return self.streams[device_id * streams_per_gpu + stream_idx];
    }

    pub fn syncAll(self: *const StreamPool) void {
        for (self.streams) |stream| {
            _ = c.cudaStreamSynchronize(stream);
        }
    }

    pub fn syncDevice(self: *const StreamPool, device_id: u32) void {
        const streams_per_gpu = self.streams.len / self.num_gpus;
        for (0..streams_per_gpu) |si| {
            _ = c.cudaStreamSynchronize(self.streams[device_id * streams_per_gpu + si]);
        }
    }
};

pub const MemoryManager = struct {
    num_gpus:        u32,
    stream_pool:     StreamPool,
    allocated_gpu:   []usize,
    allocated_cpu:   usize,
    peak_gpu:        []usize,
    allocator:       std.mem.Allocator,

    pub fn init(num_gpus: u32, allocator: std.mem.Allocator) !MemoryManager {
        const stream_pool = try StreamPool.init(num_gpus, 4, allocator);
        const allocated_gpu = try allocator.alloc(usize, num_gpus);
        const peak_gpu = try allocator.alloc(usize, num_gpus);
        @memset(allocated_gpu, 0);
        @memset(peak_gpu, 0);
        return MemoryManager{
            .num_gpus      = num_gpus,
            .stream_pool   = stream_pool,
            .allocated_gpu = allocated_gpu,
            .allocated_cpu = 0,
            .peak_gpu      = peak_gpu,
            .allocator     = allocator,
        };
    }

    pub fn deinit(self: *MemoryManager) void {
        self.stream_pool.deinit();
        self.allocator.free(self.allocated_gpu);
        self.allocator.free(self.peak_gpu);
    }

    pub fn allocOnGPU(self: *MemoryManager, size_bytes: usize, device_id: i32) !MemoryBlock {
        _ = c.cudaSetDevice(device_id);
        var ptr: ?*anyopaque = null;
        const err = c.cudaMalloc(&ptr, size_bytes);
        if (err != c.cudaSuccess) {
            const gpu_idx: usize = @intCast(device_id);
            std.log.err(
                "cudaMalloc failed on GPU {}: size={} err={}",
                .{ device_id, size_bytes, @intFromEnum(err) },
            );
            self.printMemoryStats();
            return error.CudaMallocFailed;
        }
        const gpu_idx: usize = @intCast(device_id);
        self.allocated_gpu[gpu_idx] += size_bytes;
        if (self.allocated_gpu[gpu_idx] > self.peak_gpu[gpu_idx]) {
            self.peak_gpu[gpu_idx] = self.allocated_gpu[gpu_idx];
        }
        return MemoryBlock{
            .gpu_ptr    = ptr,
            .cpu_ptr    = null,
            .size_bytes = size_bytes,
            .device_id  = device_id,
            .pinned     = false,
        };
    }

    pub fn allocOnGPUZeroed(self: *MemoryManager, size_bytes: usize, device_id: i32) !MemoryBlock {
        var blk = try self.allocOnGPU(size_bytes, device_id);
        _ = c.cudaSetDevice(device_id);
        _ = c.cudaMemset(blk.gpu_ptr.?, 0, size_bytes);
        return blk;
    }

    pub fn freeGPU(self: *MemoryManager, block: *MemoryBlock) void {
        if (block.gpu_ptr) |ptr| {
            _ = c.cudaSetDevice(block.device_id);
            _ = c.cudaFree(ptr);
            const gpu_idx: usize = @intCast(block.device_id);
            if (self.allocated_gpu[gpu_idx] >= block.size_bytes) {
                self.allocated_gpu[gpu_idx] -= block.size_bytes;
            }
            block.gpu_ptr = null;
        }
    }

    pub fn getStream(self: *const MemoryManager, device_id: i32) c.cudaStream_t {
        return self.stream_pool.get(@intCast(device_id), 0);
    }

    pub fn getComputeStream(self: *const MemoryManager, device_id: i32) c.cudaStream_t {
        return self.stream_pool.get(@intCast(device_id), 1);
    }

    pub fn getCommunicationStream(self: *const MemoryManager, device_id: i32) c.cudaStream_t {
        return self.stream_pool.get(@intCast(device_id), 2);
    }

    pub fn getCheckpointStream(self: *const MemoryManager, device_id: i32) c.cudaStream_t {
        return self.stream_pool.get(@intCast(device_id), 3);
    }

    pub fn syncAll(self: *const MemoryManager) void {
        self.stream_pool.syncAll();
    }

    pub fn syncDevice(self: *const MemoryManager, device_id: i32) void {
        self.stream_pool.syncDevice(@intCast(device_id));
    }

    pub fn printMemoryStats(self: *const MemoryManager) void {
        std.log.info("[MemoryManager] GPU Allocation Stats:", .{});
        for (0..self.num_gpus) |i| {
            var free_b: usize = 0;
            var total_b: usize = 0;
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaMemGetInfo(&free_b, &total_b);
            std.log.info(
                "  GPU {}: tracked={d:.2}GB free={d:.2}GB total={d:.2}GB peak={d:.2}GB",
                .{
                    i,
                    @as(f64, @floatFromInt(self.allocated_gpu[i])) / 1e9,
                    @as(f64, @floatFromInt(free_b)) / 1e9,
                    @as(f64, @floatFromInt(total_b)) / 1e9,
                    @as(f64, @floatFromInt(self.peak_gpu[i])) / 1e9,
                },
            );
        }
    }
};
