const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("nccl.h");
});

pub const NcclComm = struct {
    comms:    []c.ncclComm_t,
    num_gpus: u32,
    allocator: std.mem.Allocator,

    pub fn init(num_gpus: u32, allocator: std.mem.Allocator) !NcclComm {
        const comms = try allocator.alloc(c.ncclComm_t, num_gpus);
        var dev_list = try allocator.alloc(c_int, num_gpus);
        defer allocator.free(dev_list);
        for (0..num_gpus) |i| dev_list[i] = @intCast(i);

        const err = c.ncclCommInitAll(comms.ptr, @intCast(num_gpus), dev_list.ptr);
        if (err != c.ncclSuccess) {
            std.log.err("ncclCommInitAll failed: {s}", .{c.ncclGetErrorString(err)});
            allocator.free(comms);
            return error.NcclInitFailed;
        }
        return NcclComm{ .comms = comms, .num_gpus = num_gpus, .allocator = allocator };
    }

    pub fn deinit(self: *NcclComm) void {
        for (self.comms) |comm| _ = c.ncclCommDestroy(comm);
        self.allocator.free(self.comms);
    }

    pub fn allReduceSum(
        self: *NcclComm,
        send_ptr: ?*anyopaque,
        recv_ptr: ?*anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        device_id: i32,
    ) !void {
        _ = c.cudaSetDevice(device_id);
        const rank: usize = @intCast(device_id);
        const err = c.ncclAllReduce(
            send_ptr, recv_ptr,
            @intCast(count),
            dtype, c.ncclSum,
            self.comms[rank], @ptrFromInt(0),
        );
        if (err != c.ncclSuccess) {
            std.log.err("ncclAllReduce failed: {s}", .{c.ncclGetErrorString(err)});
            return error.NcclAllReduceFailed;
        }
    }

    pub fn allReduceSumAll(
        self: *NcclComm,
        bufs: []?*anyopaque,
        counts: []usize,
        dtype: c.ncclDataType_t,
        streams: []c.cudaStream_t,
    ) !void {
        const err_start = c.ncclGroupStart();
        if (err_start != c.ncclSuccess) return error.NcclGroupStartFailed;
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            const err = c.ncclAllReduce(
                bufs[i], bufs[i],
                @intCast(counts[i]),
                dtype, c.ncclSum,
                self.comms[i], streams[i],
            );
            if (err != c.ncclSuccess) {
                _ = c.ncclGroupEnd();
                return error.NcclAllReduceFailed;
            }
        }
        const err_end = c.ncclGroupEnd();
        if (err_end != c.ncclSuccess) return error.NcclGroupEndFailed;
    }

    pub fn broadcastFromRank0(
        self: *NcclComm,
        bufs: []?*anyopaque,
        count: usize,
        dtype: c.ncclDataType_t,
        streams: []c.cudaStream_t,
    ) !void {
        const err_start = c.ncclGroupStart();
        if (err_start != c.ncclSuccess) return error.NcclGroupStartFailed;
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.ncclBroadcast(
                bufs[0], bufs[i],
                @intCast(count),
                dtype, 0,
                self.comms[i], streams[i],
            );
        }
        _ = c.ncclGroupEnd();
    }

    pub fn reduceScatterAll(
        self: *NcclComm,
        send_bufs: []?*anyopaque,
        recv_bufs: []?*anyopaque,
        count_per_rank: usize,
        dtype: c.ncclDataType_t,
        streams: []c.cudaStream_t,
    ) !void {
        const err_start = c.ncclGroupStart();
        if (err_start != c.ncclSuccess) return error.NcclGroupStartFailed;
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.ncclReduceScatter(
                send_bufs[i], recv_bufs[i],
                @intCast(count_per_rank),
                dtype, c.ncclSum,
                self.comms[i], streams[i],
            );
        }
        _ = c.ncclGroupEnd();
    }

    pub fn allGatherAll(
        self: *NcclComm,
        send_bufs: []?*anyopaque,
        recv_bufs: []?*anyopaque,
        count_per_rank: usize,
        dtype: c.ncclDataType_t,
        streams: []c.cudaStream_t,
    ) !void {
        const err_start = c.ncclGroupStart();
        if (err_start != c.ncclSuccess) return error.NcclGroupStartFailed;
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.ncclAllGather(
                send_bufs[i], recv_bufs[i],
                @intCast(count_per_rank),
                dtype,
                self.comms[i], streams[i],
            );
        }
        _ = c.ncclGroupEnd();
    }

    pub fn syncAll(self: *const NcclComm) void {
        for (0..self.num_gpus) |i| {
            _ = c.cudaSetDevice(@intCast(i));
            _ = c.cudaDeviceSynchronize();
        }
    }

    pub fn getUniqueId() !c.ncclUniqueId {
        var id: c.ncclUniqueId = undefined;
        const err = c.ncclGetUniqueId(&id);
        if (err != c.ncclSuccess) return error.NcclGetIdFailed;
        return id;
    }
};

pub fn testNcclBandwidth(
    comm: *NcclComm,
    msg_size_bytes: usize,
    num_iters: u32,
    allocator: std.mem.Allocator,
) !f64 {
    const mem = @import("memory.zig");
    var mm = try mem.MemoryManager.init(comm.num_gpus, allocator);
    defer mm.deinit();

    var bufs = try allocator.alloc(mem.MemoryBlock, comm.num_gpus);
    defer {
        for (bufs) |*b| mm.freeGPU(b);
        allocator.free(bufs);
    }
    for (0..comm.num_gpus) |i| {
        bufs[i] = try mm.allocOnGPUZeroed(msg_size_bytes, @intCast(i));
    }

    var streams = try allocator.alloc(c.cudaStream_t, comm.num_gpus);
    defer allocator.free(streams);
    for (0..comm.num_gpus) |i| streams[i] = mm.getStream(@intCast(i));

    var bufs_ptr = try allocator.alloc(?*anyopaque, comm.num_gpus);
    defer allocator.free(bufs_ptr);
    for (0..comm.num_gpus) |i| bufs_ptr[i] = bufs[i].gpu_ptr;
    var counts = try allocator.alloc(usize, comm.num_gpus);
    defer allocator.free(counts);
    for (0..comm.num_gpus) |i| counts[i] = msg_size_bytes / @sizeOf(f32);

    const start_ns = std.time.nanoTimestamp();
    for (0..num_iters) |_| {
        try comm.allReduceSumAll(bufs_ptr, counts, c.ncclFloat32, streams);
        comm.syncAll();
    }
    const end_ns = std.time.nanoTimestamp();

    const elapsed_s = @as(f64, @floatFromInt(end_ns - start_ns)) / 1e9;
    const bytes_transferred = @as(f64, @floatFromInt(msg_size_bytes * num_iters * comm.num_gpus));
    const bw_gb_s = bytes_transferred / elapsed_s / 1e9;
    return bw_gb_s;
}
