const std = @import("std");
const mem = @import("memory.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("stdio.h");
});

pub const CheckpointHeader = struct {
    magic: u64 = 0x554E444552444F47,
    version: u32 = 3,
    step: u64,
    loss: f64,
    lr: f32,
    tokens_seen: u64,
    num_layers: u32,
    model_dim: u32,
    num_heads: u32,
    head_dim: u32,
    ffn_dim: u32,
    vocab_size: u32,
    max_seq_len: u64,
    num_gpus: u32,
    precision: u32,
    timestamp_unix: i64,
    wall_time_seconds: f64,
    grad_norm: f32,
    weight_decay: f32,
    reserved: [64]u8 = [_]u8{0} ** 64,
};

pub const CheckpointManager = struct {
    checkpoint_dir: []const u8,
    keep_last_n: u32,
    save_interval: u32,
    saved_steps: std.ArrayList(u64),
    allocator: std.mem.Allocator,
    total_checkpoint_bytes: u64,
    num_checkpoints_saved: u64,
    wall_time_start: i64,

    pub fn init(
        checkpoint_dir: []const u8,
        keep_last_n: u32,
        save_interval: u32,
        allocator: std.mem.Allocator,
    ) !CheckpointManager {
        const dir = std.fs.cwd().makeOpenPath(checkpoint_dir, .{}) catch |e| blk: {
            if (e == error.PathAlreadyExists) {
                break :blk try std.fs.cwd().openDir(checkpoint_dir, .{});
            }
            return e;
        };
        dir.close();
        return CheckpointManager{
            .checkpoint_dir          = checkpoint_dir,
            .keep_last_n             = keep_last_n,
            .save_interval           = save_interval,
            .saved_steps             = std.ArrayList(u64).init(allocator),
            .allocator               = allocator,
            .total_checkpoint_bytes  = 0,
            .num_checkpoints_saved   = 0,
            .wall_time_start         = std.time.timestamp(),
        };
    }

    pub fn deinit(self: *CheckpointManager) void {
        self.saved_steps.deinit();
    }

    pub fn shouldSave(self: *const CheckpointManager, step: u64) bool {
        return step > 0 and step % self.save_interval == 0;
    }

    pub fn buildPath(self: *const CheckpointManager, step: u64, allocator: std.mem.Allocator) ![]u8 {
        return std.fmt.allocPrint(allocator, "{s}/step_{:0>10}.ckpt", .{ self.checkpoint_dir, step });
    }

    pub fn buildMetaPath(self: *const CheckpointManager, step: u64, allocator: std.mem.Allocator) ![]u8 {
        return std.fmt.allocPrint(allocator, "{s}/step_{:0>10}.meta.json", .{ self.checkpoint_dir, step });
    }

    pub fn save(
        self: *CheckpointManager,
        step: u64,
        header: CheckpointHeader,
        param_blocks: []const mem.MemoryBlock,
        optim_blocks: []const mem.MemoryBlock,
        streams: []c.cudaStream_t,
    ) !void {
        const path = try self.buildPath(step, self.allocator);
        defer self.allocator.free(path);

        std.log.info("[checkpoint] Saving step {} -> {s}", .{ step, path });
        const start_ns = std.time.nanoTimestamp();

        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();

        try writer.writeStruct(header);

        var total_bytes: u64 = @sizeOf(CheckpointHeader);

        for (param_blocks, 0..) |block, i| {
            _ = i;
            if (block.gpu_ptr == null) {
                try writer.writeInt(u64, 0, .little);
                continue;
            }
            _ = c.cudaSetDevice(block.device_id);
            var cpu_buf = try self.allocator.alloc(u8, block.size_bytes);
            defer self.allocator.free(cpu_buf);

            const stream = if (block.device_id < @as(i32, @intCast(streams.len)))
                streams[@intCast(block.device_id)]
            else
                @as(c.cudaStream_t, @ptrFromInt(0));

            _ = c.cudaMemcpyAsync(cpu_buf.ptr, block.gpu_ptr.?, block.size_bytes,
                c.cudaMemcpyDeviceToHost, stream);
            _ = c.cudaStreamSynchronize(stream);

            try writer.writeInt(u64, block.size_bytes, .little);
            try writer.writeAll(cpu_buf);
            total_bytes += 8 + block.size_bytes;
        }

        for (optim_blocks) |block| {
            if (block.gpu_ptr == null) {
                try writer.writeInt(u64, 0, .little);
                continue;
            }
            _ = c.cudaSetDevice(block.device_id);
            var cpu_buf = try self.allocator.alloc(u8, block.size_bytes);
            defer self.allocator.free(cpu_buf);

            const stream = if (block.device_id < @as(i32, @intCast(streams.len)))
                streams[@intCast(block.device_id)]
            else
                @as(c.cudaStream_t, @ptrFromInt(0));

            _ = c.cudaMemcpyAsync(cpu_buf.ptr, block.gpu_ptr.?, block.size_bytes,
                c.cudaMemcpyDeviceToHost, stream);
            _ = c.cudaStreamSynchronize(stream);

            try writer.writeInt(u64, block.size_bytes, .little);
            try writer.writeAll(cpu_buf);
            total_bytes += 8 + block.size_bytes;
        }

        const elapsed_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_ns)) / 1e6;
        const mb_per_s = @as(f64, @floatFromInt(total_bytes)) / 1e6 / (elapsed_ms / 1000.0);
        std.log.info(
            "[checkpoint] Saved {d:.1}MB in {d:.0}ms ({d:.0}MB/s)",
            .{ @as(f64, @floatFromInt(total_bytes)) / 1e6, elapsed_ms, mb_per_s },
        );

        try self.saved_steps.append(step);
        self.total_checkpoint_bytes += total_bytes;
        self.num_checkpoints_saved += 1;

        try self.writeMetadata(step, header, total_bytes);
        try self.pruneOldCheckpoints();
    }

    pub fn load(
        self: *const CheckpointManager,
        step: u64,
        param_blocks: []mem.MemoryBlock,
        optim_blocks: []mem.MemoryBlock,
        streams: []c.cudaStream_t,
    ) !CheckpointHeader {
        const path = try self.buildPath(step, self.allocator);
        defer self.allocator.free(path);

        std.log.info("[checkpoint] Loading step {} from {s}", .{ step, path });

        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();

        const header = try reader.readStruct(CheckpointHeader);
        if (header.magic != 0x554E444552444F47) {
            return error.InvalidCheckpointMagic;
        }
        if (header.step != step) {
            std.log.warn("[checkpoint] Header step {} != requested step {}", .{ header.step, step });
        }

        for (param_blocks, 0..) |*block, _| {
            const size = try reader.readInt(u64, .little);
            if (size == 0) continue;
            var cpu_buf = try self.allocator.alloc(u8, size);
            defer self.allocator.free(cpu_buf);
            _ = try reader.readAll(cpu_buf);
            if (block.gpu_ptr) |ptr| {
                _ = c.cudaSetDevice(block.device_id);
                const stream = if (block.device_id < @as(i32, @intCast(streams.len)))
                    streams[@intCast(block.device_id)]
                else
                    @as(c.cudaStream_t, @ptrFromInt(0));
                _ = c.cudaMemcpyAsync(ptr, cpu_buf.ptr, size,
                    c.cudaMemcpyHostToDevice, stream);
            }
        }

        for (optim_blocks) |*block| {
            const size = try reader.readInt(u64, .little);
            if (size == 0) continue;
            var cpu_buf = try self.allocator.alloc(u8, size);
            defer self.allocator.free(cpu_buf);
            _ = try reader.readAll(cpu_buf);
            if (block.gpu_ptr) |ptr| {
                _ = c.cudaSetDevice(block.device_id);
                const stream = if (block.device_id < @as(i32, @intCast(streams.len)))
                    streams[@intCast(block.device_id)]
                else
                    @as(c.cudaStream_t, @ptrFromInt(0));
                _ = c.cudaMemcpyAsync(ptr, cpu_buf.ptr, size,
                    c.cudaMemcpyHostToDevice, stream);
            }
        }

        for (0..@as(usize, @intCast(@min(streams.len, 8)))) |i| {
            _ = c.cudaStreamSynchronize(streams[i]);
        }
        std.log.info("[checkpoint] Load complete: step={} loss={d:.4} lr={e:.3}", .{
            header.step, header.loss, header.lr,
        });
        return header;
    }

    fn writeMetadata(
        self: *const CheckpointManager,
        step: u64,
        header: CheckpointHeader,
        total_bytes: u64,
    ) !void {
        const meta_path = try self.buildMetaPath(step, self.allocator);
        defer self.allocator.free(meta_path);

        const file = try std.fs.cwd().createFile(meta_path, .{});
        defer file.close();
        const w = file.writer();

        try w.print(
            \\{{
            \\  "step": {d},
            \\  "loss": {d},
            \\  "lr": {e},
            \\  "tokens_seen": {d},
            \\  "size_bytes": {d},
            \\  "grad_norm": {e},
            \\  "weight_decay": {e},
            \\  "timestamp": {d},
            \\  "wall_time_hours": {d:.3}
            \\}}
            \\
        , .{
            step, header.loss, header.lr,
            header.tokens_seen, total_bytes,
            header.grad_norm, header.weight_decay,
            header.timestamp_unix,
            @as(f64, @floatFromInt(header.timestamp_unix - self.wall_time_start)) / 3600.0,
        });
    }

    fn pruneOldCheckpoints(self: *CheckpointManager) !void {
        while (self.saved_steps.items.len > self.keep_last_n) {
            const old_step = self.saved_steps.orderedRemove(0);
            const old_path = try self.buildPath(old_step, self.allocator);
            defer self.allocator.free(old_path);
            std.fs.cwd().deleteFile(old_path) catch |e| {
                std.log.warn("[checkpoint] Could not delete old checkpoint: {}", .{e});
            };
            const meta_path = try self.buildMetaPath(old_step, self.allocator);
            defer self.allocator.free(meta_path);
            std.fs.cwd().deleteFile(meta_path) catch {};
            std.log.info("[checkpoint] Pruned checkpoint step {}", .{old_step});
        }
    }

    pub fn findLatestStep(self: *const CheckpointManager) !?u64 {
        var dir = std.fs.cwd().openDir(self.checkpoint_dir, .{ .iterate = true }) catch return null;
        defer dir.close();

        var latest: ?u64 = null;
        var it = dir.iterate();
        while (try it.next()) |entry| {
            if (entry.kind != .file) continue;
            if (!std.mem.endsWith(u8, entry.name, ".ckpt")) continue;
            if (entry.name.len < 16) continue;
            const step_str = entry.name[5..15];
            const step = std.fmt.parseInt(u64, step_str, 10) catch continue;
            if (latest == null or step > latest.?) latest = step;
        }
        return latest;
    }
};
