pub const EFLAConfig = struct {
    model_dim:             u32,
    num_layers:            u32,
    num_heads:             u32,
    head_dim:              u32,
    ffn_dim:               u32,
    vocab_size:            u32,
    max_seq_len:           u64,
    num_gpus:              u32,
    tensor_parallel:       u32 = 1,
    low_rank:              u32 = 64,
    precision:             mem.Precision = .fp32,
    gradient_checkpointing: bool = false,
    use_fp8_weights:       bool = false,
    use_fp8_activations:   bool = false,
    tie_embeddings:        bool = true,
    rotary_base:           f32 = 500_000.0,
};

pub const EFLALayerWeights = struct {
    qkv_weight:  mem.MemoryBlock,
    out_weight:  mem.MemoryBlock,
    fw_key:      mem.MemoryBlock,
    fw_val:      mem.MemoryBlock,
    fw_decay:    mem.MemoryBlock,
    ffn_up:      mem.MemoryBlock,
    ffn_gate:    mem.MemoryBlock,
    ffn_down:    mem.MemoryBlock,
    norm1_scale: mem.MemoryBlock,
    norm1_bias:  mem.MemoryBlock,
    norm2_scale: mem.MemoryBlock,
    norm2_bias:  mem.MemoryBlock,
    device_id:   i32,
    param_count: u64,

    pub fn init(cfg: EFLAConfig, device_id: i32, mm: *mem.MemoryManager) !EFLALayerWeights {
        const eb  = mem.precisionBytes(cfg.precision);
        const d   = cfg.model_dim;
        const nh  = cfg.num_heads / cfg.tensor_parallel;
        const hd  = cfg.head_dim;
        const fd  = cfg.ffn_dim / cfg.tensor_parallel;
        const lr  = cfg.low_rank;
        _ = c.cudaSetDevice(device_id);

        const qkv_size  = d * (3 * nh * hd) * eb;
        const out_size  = (nh * hd) * d * eb;
        const fwk_size  = nh * lr * hd * eb;
        const fwv_size  = nh * lr * hd * eb;
        const fwd_size  = nh * lr * @sizeOf(f32);
        const up_size   = d * fd * eb;
        const gate_size = d * fd * eb;
        const down_size = fd * d * eb;
        const norm_size = d * @sizeOf(f32);

        const pc =
            (qkv_size + out_size + fwk_size + fwv_size + fwd_size +
             up_size + gate_size + down_size + 4 * norm_size) / eb;

        return EFLALayerWeights{
            .qkv_weight  = try mm.allocOnGPU(qkv_size,  device_id),
            .out_weight  = try mm.allocOnGPU(out_size,  device_id),
            .fw_key      = try mm.allocOnGPUZeroed(fwk_size, device_id),
            .fw_val      = try mm.allocOnGPUZeroed(fwv_size, device_id),
            .fw_decay    = try mm.allocOnGPU(fwd_size,  device_id),
            .ffn_up      = try mm.allocOnGPU(up_size,   device_id),
            .ffn_gate    = try mm.allocOnGPU(gate_size, device_id),
            .ffn_down    = try mm.allocOnGPU(down_size, device_id),
            .norm1_scale = try mm.allocOnGPU(norm_size, device_id),
            .norm1_bias  = try mm.allocOnGPUZeroed(norm_size, device_id),
            .norm2_scale = try mm.allocOnGPU(norm_size, device_id),
            .norm2_bias  = try mm.allocOnGPUZeroed(norm_size, device_id),
            .device_id   = device_id,
            .param_count = pc,
        };
    }

    pub fn deinit(self: *EFLALayerWeights) void {
        self.qkv_weight.freeGPU();
        self.out_weight.freeGPU();
        self.fw_key.freeGPU();
        self.fw_val.freeGPU();
        self.fw_decay.freeGPU();
        self.ffn_up.freeGPU();
        self.ffn_gate.freeGPU();
        self.ffn_down.freeGPU();
        self.norm1_scale.freeGPU();
        self.norm1_bias.freeGPU();
        self.norm2_scale.freeGPU();
        self.norm2_bias.freeGPU();
    }

    pub fn initWeightsNormal(self: *EFLALayerWeights, scale: f32, stream: c.cudaStream_t) void {
        launchInitWeightsNormal(
            @ptrCast(self.qkv_weight.gpu_ptr.?),
            self.qkv_weight.size_bytes / @sizeOf(f32),
            scale, self.device_id, stream,
        );
        launchInitWeightsNormal(
            @ptrCast(self.out_weight.gpu_ptr.?),
            self.out_weight.size_bytes / @sizeOf(f32),
            scale * 0.5, self.device_id, stream,
        );
        launchInitWeightsOnes(
            @ptrCast(self.norm1_scale.gpu_ptr.?),
            self.norm1_scale.size_bytes / @sizeOf(f32),
            self.device_id, stream,
        );
        launchInitWeightsOnes(
            @ptrCast(self.norm2_scale.gpu_ptr.?),
            self.norm2_scale.size_bytes / @sizeOf(f32),
            self.device_id, stream,
        );
        launchInitWeightsNormal(
            @ptrCast(self.ffn_up.gpu_ptr.?),
            self.ffn_up.size_bytes / @sizeOf(f32),
            scale, self.device_id, stream,
        );
        launchInitWeightsNormal(
            @ptrCast(self.ffn_gate.gpu_ptr.?),
            self.ffn_gate.size_bytes / @sizeOf(f32),
            scale, self.device_id, stream,
        );
        launchInitWeightsNormal(
            @ptrCast(self.ffn_down.gpu_ptr.?),
            self.ffn_down.size_bytes / @sizeOf(f32),
            scale * 0.5, self.device_id, stream,
        );
        launchInitDecayNegative(
            @ptrCast(self.fw_decay.gpu_ptr.?),
            self.fw_decay.size_bytes / @sizeOf(f32),
            self.device_id, stream,
        );
    }
};

pub const EFLAGradients = struct {
    d_qkv_weight:  mem.MemoryBlock,
