    pub fn zero(self: *EFLAGradients, stream: c.cudaStream_t) void {
        self.d_qkv_weight.zero(stream);
        self.d_out_weight.zero(stream);
        self.d_fw_decay.zero(stream);
        self.d_ffn_up.zero(stream);
        self.d_ffn_gate.zero(stream);
        self.d_ffn_down.zero(stream);
        self.d_norm1_scale.zero(stream);
        self.d_norm2_scale.zero(stream);
