};

pub const EFLAModel = struct {
    config:          EFLAConfig,
    layers:          []EFLALayerWeights,
    grads:           []EFLAGradients,
    embedding:       mem.MemoryBlock,
    lm_head:         mem.MemoryBlock,
    grad_embedding:  mem.MemoryBlock,
    grad_lm_head:    mem.MemoryBlock,
    norm_scale:      mem.MemoryBlock,
    norm_bias:       mem.MemoryBlock,
    hidden_buf:      []mem.MemoryBlock,
    logits_buf:      mem.MemoryBlock,
    loss_buf:        mem.MemoryBlock,
    total_params:    u64,
    mm:              *mem.MemoryManager,
    comm:            *nccl.NcclComm,
    allocator:       std.mem.Allocator,

    pub fn init(
        cfg: EFLAConfig,
        mm: *mem.MemoryManager,
        comm: *nccl.NcclComm,
        allocator: std.mem.Allocator,
    ) !EFLAModel {
        const layers = try allocator.alloc(EFLALayerWeights, cfg.num_layers);
        const grads  = try allocator.alloc(EFLAGradients,    cfg.num_layers);
        var total_params: u64 = 0;

        for (layers, 0..) |*layer, i| {
            const dev: i32 = @intCast(i % cfg.num_gpus);
            layer.* = try EFLALayerWeights.init(cfg, dev, mm);
            total_params += layer.param_count;
        }
        for (grads, 0..) |*grad, i| {
            const dev: i32 = @intCast(i % cfg.num_gpus);
            grad.* = try EFLAGradients.init(cfg, dev, mm);
        }

        const embed_eb   = mem.precisionBytes(cfg.precision);
        const embed_size = cfg.vocab_size * cfg.model_dim * embed_eb;
        const norm_size  = cfg.model_dim * @sizeOf(f32);

        const hidden_buf = try allocator.alloc(mem.MemoryBlock, cfg.num_gpus);
        for (hidden_buf, 0..) |*h, i| {
            const max_local_seq = (cfg.max_seq_len / cfg.num_gpus + 1) * cfg.model_dim;
            h.* = try mm.allocOnGPUZeroed(max_local_seq * @sizeOf(f32), @intCast(i));
        }

        const max_logits = (cfg.max_seq_len / cfg.num_gpus + 1) * cfg.vocab_size;
        const logits_buf = try mm.allocOnGPU(max_logits * @sizeOf(f32), 0);
        const loss_buf   = try mm.allocOnGPUZeroed(@sizeOf(f32), 0);

        const embed_block  = try mm.allocOnGPU(embed_size, 0);
        const lm_head_blk  = if (cfg.tie_embeddings) embed_block else try mm.allocOnGPU(embed_size, 0);
        const grad_embed   = try mm.allocOnGPUZeroed(embed_size, 0);
        const grad_lmhead  = if (cfg.tie_embeddings) grad_embed else try mm.allocOnGPUZeroed(embed_size, 0);

        total_params += cfg.vocab_size * cfg.model_dim * 2;
        total_params += cfg.model_dim * 2;

        std.log.info("[EFLAModel] Total params: {d:.2}B", .{
            @as(f64, @floatFromInt(total_params)) / 1e9,
        });

        return EFLAModel{
            .config         = cfg,
            .layers         = layers,
            .grads          = grads,
            .embedding      = embed_block,
            .lm_head        = lm_head_blk,
            .grad_embedding = grad_embed,
            .grad_lm_head   = grad_lmhead,
            .norm_scale     = try mm.allocOnGPU(norm_size, 0),
            .norm_bias      = try mm.allocOnGPUZeroed(norm_size, 0),
            .hidden_buf     = hidden_buf,
            .logits_buf     = logits_buf,
            .loss_buf       = loss_buf,
            .total_params   = total_params,
            .mm             = mm,
            .comm           = comm,
            .allocator      = allocator,
        };
    }

    pub fn deinit(self: *EFLAModel) void {
        for (self.layers) |*l| l.deinit();
        for (self.grads)  |*g| g.deinit();
        self.allocator.free(self.layers);
        self.allocator.free(self.grads);
        self.embedding.freeGPU();
        if (!self.config.tie_embeddings) self.lm_head.freeGPU();
        self.grad_embedding.freeGPU();
        if (!self.config.tie_embeddings) self.grad_lm_head.freeGPU();
        self.norm_scale.freeGPU();
        self.norm_bias.freeGPU();
        for (self.hidden_buf) |*h| h.freeGPU();
        self.allocator.free(self.hidden_buf);
        self.logits_buf.freeGPU();
        self.loss_buf.freeGPU();
    }

    pub fn initWeights(self: *EFLAModel) void {
        const scale = @as(f32, @floatFromInt(self.config.model_dim));
        const std_dev = 1.0 / @sqrt(scale);
        for (self.layers, 0..) |*layer, i| {
            const stream = self.mm.getStream(layer.device_id);
            const depth_scale = std_dev / @sqrt(@as(f32, @floatFromInt(i + 1)));
            layer.initWeightsNormal(depth_scale, stream);
        }
        const s0 = self.mm.getStream(0);
        launchInitWeightsNormal(
            @ptrCast(self.embedding.gpu_ptr.?),
            self.embedding.size_bytes / @sizeOf(f32),
            std_dev, 0, s0,
        );
        launchInitWeightsOnes(
            @ptrCast(self.norm_scale.gpu_ptr.?),
            self.norm_scale.size_bytes / @sizeOf(f32),
            0, s0,
        );
        self.mm.syncAll();
        std.log.info("[EFLAModel] Weights initialized.", .{});
    }

    pub fn zeroGrads(self: *EFLAModel) void {
        for (self.grads, 0..) |*g, i| {
            const stream = self.mm.getStream(self.layers[i].device_id);
            g.zero(stream);
        }
        self.grad_embedding.zero(self.mm.getStream(0));
        if (!self.config.tie_embeddings) {
            self.grad_lm_head.zero(self.mm.getStream(0));
        }
        self.loss_buf.zero(self.mm.getStream(0));
    }

    pub fn forwardAndLoss(
        self: *EFLAModel,
        tokens_gpu: *anyopaque,
        seq_len: usize,
        global_offset: u64,
    ) !f64 {
        const d = self.config.model_dim;
        const s = self.mm.getStream(0);

        launchEmbeddingForward(
            @ptrCast(tokens_gpu),
            @ptrCast(self.embedding.gpu_ptr.?),
            @ptrCast(self.hidden_buf[0].gpu_ptr.?),
            @intCast(seq_len), d, 0, s,
        );

        launchPositionalEncodingAdd(
            @ptrCast(self.hidden_buf[0].gpu_ptr.?),
            @intCast(seq_len), d, global_offset,
            self.config.rotary_base, 0, s,
        );

        for (self.layers, 0..) |*layer, layer_idx| {
            const dev = layer.device_id;
            const compute_stream = self.mm.getComputeStream(dev);

            launchRMSNorm(
                @ptrCast(self.hidden_buf[0].gpu_ptr.?),
                @ptrCast(layer.norm1_scale.gpu_ptr.?),
                @ptrCast(layer.norm1_bias.gpu_ptr.?),
                @intCast(seq_len), d, dev, compute_stream,
            );

            launchEFLAAssociativeScan(
                @ptrCast(self.hidden_buf[0].gpu_ptr.?),
                @ptrCast(layer.qkv_weight.gpu_ptr.?),
                @ptrCast(layer.fw_key.gpu_ptr.?),
                @ptrCast(layer.fw_val.gpu_ptr.?),
                @ptrCast(layer.fw_decay.gpu_ptr.?),
                @ptrCast(layer.out_weight.gpu_ptr.?),
                @intCast(seq_len), d,
                self.config.num_heads / self.config.tensor_parallel,
                self.config.head_dim,
                self.config.low_rank,
                dev, compute_stream,
            );

            launchRMSNorm(
                @ptrCast(self.hidden_buf[0].gpu_ptr.?),
                @ptrCast(layer.norm2_scale.gpu_ptr.?),
                @ptrCast(layer.norm2_bias.gpu_ptr.?),
                @intCast(seq_len), d, dev, compute_stream,
            );

            launchSwiGLUFFN(
                @ptrCast(self.hidden_buf[0].gpu_ptr.?),
                @ptrCast(layer.ffn_up.gpu_ptr.?),
                @ptrCast(layer.ffn_gate.gpu_ptr.?),
                @ptrCast(layer.ffn_down.gpu_ptr.?),
                @intCast(seq_len), d,
                self.config.ffn_dim / self.config.tensor_parallel,
                dev, compute_stream,
            );

            if (self.config.tensor_parallel > 1) {
                const comm_stream = self.mm.getCommunicationStream(dev);
                const elems = seq_len * d / self.config.tensor_parallel;
                self.comm.allReduceSum(
                    self.hidden_buf[0].gpu_ptr,
                    self.hidden_buf[0].gpu_ptr,
                    elems, c.ncclFloat32, dev,
                ) catch |e| std.log.err("AllReduce failed layer {}: {}", .{ layer_idx, e });
                _ = comm_stream;
            }
        }

        launchRMSNorm(
            @ptrCast(self.hidden_buf[0].gpu_ptr.?),
            @ptrCast(self.norm_scale.gpu_ptr.?),
            @ptrCast(self.norm_bias.gpu_ptr.?),
            @intCast(seq_len), d, 0, s,
        );

        launchLMHeadAndLoss(
            @ptrCast(self.hidden_buf[0].gpu_ptr.?),
            @ptrCast(self.lm_head.gpu_ptr.?),
            @ptrCast(tokens_gpu),
            @ptrCast(self.logits_buf.gpu_ptr.?),
            @ptrCast(self.loss_buf.gpu_ptr.?),
            @intCast(seq_len), d,
            self.config.vocab_size,
            0, s,
        );

        var loss_host: f32 = 0.0;
        _ = c.cudaSetDevice(0);
        _ = c.cudaStreamSynchronize(s);
        _ = c.cudaMemcpy(&loss_host, self.loss_buf.gpu_ptr.?, @sizeOf(f32), c.cudaMemcpyDeviceToHost);
        return @as(f64, loss_host);
    }

    pub fn resetRecurrentState(self: *EFLAModel) void {
        for (self.layers) |*layer| {
            const stream = self.mm.getStream(layer.device_id);
            layer.fw_key.zero(stream);
            layer.fw_val.zero(stream);
        }
    }

    pub fn countParams(self: *const EFLAModel) u64 {
        return self.total_params;
    }

    pub fn estimateMFLOPsPerToken(self: *const EFLAModel) f64 {
        const d: f64 = @floatFromInt(self.config.model_dim);
        const L: f64 = @floatFromInt(self.config.num_layers);
        const H: f64 = @floatFromInt(self.config.num_heads);
        const hd: f64 = @floatFromInt(self.config.head_dim);
        const fd: f64 = @floatFromInt(self.config.ffn_dim);
        const lr: f64 = @floatFromInt(self.config.low_rank);
        const attn_flops = L * H * (3 * d * hd + lr * hd * 6 + hd * d);
        const ffn_flops  = L * (3 * d * fd);
        const embed_flops= d * @as(f64, @floatFromInt(self.config.vocab_size));
        return 6.0 * (attn_flops + ffn_flops + embed_flops);
    }
};

extern fn launchEmbeddingForward(tokens: [*]u32, embed_table: [*]f32, output: [*]f32,
    seq_len: c_int, model_dim: c_uint, device_id: c_int, stream: c.cudaStream_t) void;
