const std = @import("std");
const mem = @import("../runtime/memory.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const MuonConfig = struct {
    lr:           f32 = 0.02,
    momentum:     f32 = 0.95,
    weight_decay: f32 = 0.01,
    nesterov:     bool = true,
    ns_steps:     u32 = 5,
    ns_eps:       f32 = 1e-7,
    warmup_steps: u64 = 2000,
    total_steps:  u64 = 1_000_000,
    min_lr_ratio: f32 = 0.1,
};

pub const MuonState = struct {
    momentum_buf: mem.MemoryBlock,
    num_elements: usize,
    num_rows:     usize,
    num_cols:     usize,
    device_id:    i32,
    step:         u64,

    pub fn init(
        num_rows: usize,
        num_cols: usize,
        device_id: i32,
        mm: *mem.MemoryManager,
    ) !MuonState {
        const n = num_rows * num_cols;
        return MuonState{
            .momentum_buf = try mm.allocOnGPUZeroed(n * @sizeOf(f32), device_id),
            .num_elements = n,
            .num_rows     = num_rows,
            .num_cols     = num_cols,
            .device_id    = device_id,
            .step         = 0,
        };
    }

    pub fn deinit(self: *MuonState) void {
        self.momentum_buf.freeGPU();
    }
};

pub const MuonOptimizer = struct {
    config:      MuonConfig,
    states:      std.ArrayList(MuonState),
    params:      std.ArrayList(mem.MemoryBlock),
    grads:       std.ArrayList(mem.MemoryBlock),
    global_step: u64,
    mm:          *mem.MemoryManager,
    allocator:   std.mem.Allocator,

    pub fn init(
        config: MuonConfig,
        mm: *mem.MemoryManager,
        allocator: std.mem.Allocator,
    ) MuonOptimizer {
        return MuonOptimizer{
            .config      = config,
            .states      = std.ArrayList(MuonState).init(allocator),
            .params      = std.ArrayList(mem.MemoryBlock).init(allocator),
            .grads       = std.ArrayList(mem.MemoryBlock).init(allocator),
            .global_step = 0,
            .mm          = mm,
            .allocator   = allocator,
        };
    }

    pub fn deinit(self: *MuonOptimizer) void {
        for (self.states.items) |*s| s.deinit();
        self.states.deinit();
        self.params.deinit();
        self.grads.deinit();
    }

    pub fn addParamGroup(
        self: *MuonOptimizer,
        param: mem.MemoryBlock,
        grad: mem.MemoryBlock,
        num_rows: usize,
        num_cols: usize,
    ) !void {
        try self.params.append(param);
        try self.grads.append(grad);
        try self.states.append(try MuonState.init(num_rows, num_cols, param.device_id, self.mm));
    }

    pub fn getLR(self: *const MuonOptimizer) f32 {
        const step = self.global_step;
        const warmup = self.config.warmup_steps;
        const total = self.config.total_steps;
        const base_lr = self.config.lr;
        const min_lr = base_lr * self.config.min_lr_ratio;

        if (step < warmup) {
            return base_lr * @as(f32, @floatFromInt(step + 1)) / @as(f32, @floatFromInt(warmup));
        }
        const progress = @as(f32, @floatFromInt(step - warmup)) /
                         @as(f32, @floatFromInt(total - warmup));
        const cosine = 0.5 * (1.0 + @cos(std.math.pi * @min(progress, 1.0)));
        return min_lr + (base_lr - min_lr) * cosine;
    }

    pub fn step(self: *MuonOptimizer) !void {
        self.global_step += 1;
        const current_lr = self.getLR();

        for (self.states.items, 0..) |*state, i| {
            state.step += 1;
            const stream = self.mm.getStream(state.device_id);

            launchMuonNewtonSchulz5(
                @ptrCast(self.grads.items[i].gpu_ptr.?),
                state.num_rows, state.num_cols,
                self.config.ns_steps,
                self.config.ns_eps,
                state.device_id, stream,
            );

            launchMuonMomentumUpdate(
                @ptrCast(state.momentum_buf.gpu_ptr.?),
                @ptrCast(self.grads.items[i].gpu_ptr.?),
                self.config.momentum,
                state.num_elements,
                state.device_id, stream,
            );

            launchMuonParamUpdate(
                @ptrCast(self.params.items[i].gpu_ptr.?),
                @ptrCast(state.momentum_buf.gpu_ptr.?),
                @ptrCast(self.grads.items[i].gpu_ptr.?),
                current_lr,
                self.config.weight_decay,
                self.config.nesterov,
                state.num_elements,
                state.device_id, stream,
            );
        }
    }

    pub fn zeroGrads(self: *MuonOptimizer) void {
        for (self.grads.items, 0..) |*g, i| {
            const dev = self.states.items[i].device_id;
            g.zero(self.mm.getStream(dev));
        }
    }

    pub fn stateDict(self: *const MuonOptimizer) MuonStateDict {
        return MuonStateDict{
            .global_step = self.global_step,
            .current_lr  = self.getLR(),
        };
    }
};

pub const MuonStateDict = struct {
    global_step: u64,
    current_lr:  f32,
};

extern fn launchMuonNewtonSchulz5(
    grad: [*]f32, num_rows: usize, num_cols: usize,
    ns_steps: c_uint, eps: f32,
    device_id: c_int, stream: c.cudaStream_t) void;
extern fn launchMuonMomentumUpdate(
    momentum: [*]f32, grad: [*]f32, beta: f32, num_elements: usize,
    device_id: c_int, stream: c.cudaStream_t) void;
extern fn launchMuonParamUpdate(
    param: [*]f32, momentum: [*]f32, grad: [*]f32,
    lr: f32, weight_decay: f32, nesterov: bool, num_elements: usize,
    device_id: c_int, stream: c.cudaStream_t) void;
