const std = @import("std");
const mem = @import("../runtime/memory.zig");
const efla = @import("../model/efla.zig");
const tokenizer = @import("../model/tokenizer.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const EvalTask = enum {
    hellaswag,
    arc_easy,
    arc_challenge,
    winogrande,
    piqa,
    boolq,
    lambada,
    mmlu,
    gsm8k,
    humaneval,
};

pub const EvalConfig = struct {
    tasks:        []const EvalTask,
    num_fewshot:  u32 = 0,
    batch_size:   u32 = 8,
    max_gen_len:  u32 = 256,
    device_id:    i32 = 0,
    data_dir:     []const u8 = "/mnt/nfs/eval_data",
    results_dir:  []const u8 = "/mnt/nfs/eval_results",
    log_samples:  bool = false,
};

pub const EvalResult = struct {
    task:           EvalTask,
    accuracy:       f64,
    num_correct:    u64,
    num_total:      u64,
    perplexity:     ?f64,
    extra_metrics:  std.StringHashMap(f64),
    elapsed_ms:     f64,
    allocator:      std.mem.Allocator,

    pub fn init(task: EvalTask, allocator: std.mem.Allocator) EvalResult {
        return EvalResult{
            .task          = task,
            .accuracy      = 0.0,
            .num_correct   = 0,
            .num_total     = 0,
            .perplexity    = null,
            .extra_metrics = std.StringHashMap(f64).init(allocator),
            .elapsed_ms    = 0.0,
            .allocator     = allocator,
        };
    }

    pub fn deinit(self: *EvalResult) void {
        self.extra_metrics.deinit();
    }

    pub fn print(self: *const EvalResult) void {
        std.log.info(
            "[eval] {s}: acc={d:.3}% ({}/{}) ppl={?} elapsed={d:.0}ms",
            .{
                @tagName(self.task),
                self.accuracy * 100.0,
                self.num_correct,
                self.num_total,
                self.perplexity,
                self.elapsed_ms,
            },
        );
    }
};

pub const HellaSwagSample = struct {
    context:    []const u8,
    endings:    [4][]const u8,
    correct_idx: u32,
};

pub const MCQSample = struct {
    question:    []const u8,
    choices:     [][]const u8,
    correct_idx: u32,
    subject:     ?[]const u8 = null,
};

pub const EvalHarness = struct {
    config:     EvalConfig,
    model:      *efla.EFLAModel,
    tok:        *tokenizer.Tokenizer,
    mm:         *mem.MemoryManager,
    allocator:  std.mem.Allocator,

    pub fn init(
        config: EvalConfig,
        model: *efla.EFLAModel,
        tok: *tokenizer.Tokenizer,
        mm: *mem.MemoryManager,
        allocator: std.mem.Allocator,
    ) EvalHarness {
        return EvalHarness{
            .config    = config,
            .model     = model,
            .tok       = tok,
            .mm        = mm,
            .allocator = allocator,
        };
    }

    pub fn runAll(self: *EvalHarness) !std.ArrayList(EvalResult) {
        var results = std.ArrayList(EvalResult).init(self.allocator);
        for (self.config.tasks) |task| {
            std.log.info("[eval] Running task: {s}", .{@tagName(task)});
            const r = try self.runTask(task);
            r.print();
            try results.append(r);
        }
        return results;
    }

    pub fn runTask(self: *EvalHarness, task: EvalTask) !EvalResult {
        return switch (task) {
            .hellaswag      => try self.runHellaSwag(),
            .arc_easy       => try self.runARC(.easy),
            .arc_challenge  => try self.runARC(.challenge),
            .winogrande     => try self.runWinogrande(),
            .piqa           => try self.runPIQA(),
            .boolq          => try self.runBoolQ(),
            .lambada        => try self.runLAMBADA(),
            .mmlu           => try self.runMMLU(),
            .gsm8k          => try self.runGSM8K(),
            .humaneval      => try self.runHumanEval(),
        };
    }

    fn scoreMCQ(
        self: *EvalHarness,
        context: []const u8,
        choices: []const []const u8,
    ) !u32 {
        var best_idx: u32 = 0;
        var best_logprob: f64 = -std.math.inf(f64);

        for (choices, 0..) |choice, i| {
            const full_text = try std.fmt.allocPrint(
                self.allocator, "{s}{s}", .{ context, choice },
            );
            defer self.allocator.free(full_text);

            const tokens = try self.tok.encode(full_text, self.allocator);
            defer self.allocator.free(tokens);

            const logprob = try self.computeSequenceLogProb(tokens);
            const ctx_tokens = try self.tok.encode(context, self.allocator);
            defer self.allocator.free(ctx_tokens);

            const ctx_logprob = try self.computeSequenceLogProb(ctx_tokens);
            const choice_logprob = logprob - ctx_logprob;
            const normalised = choice_logprob / @as(f64, @floatFromInt(tokens.len - ctx_tokens.len + 1));

            if (normalised > best_logprob) {
                best_logprob = normalised;
                best_idx = @intCast(i);
            }
        }
        return best_idx;
    }

    fn computeSequenceLogProb(self: *EvalHarness, tokens: []const u32) !f64 {
        if (tokens.len < 2) return 0.0;

        var tok_gpu = try self.mm.allocOnGPU(tokens.len * @sizeOf(u32), self.config.device_id);
        defer self.mm.freeGPU(&tok_gpu);
        _ = c.cudaSetDevice(self.config.device_id);
        _ = c.cudaMemcpy(tok_gpu.gpu_ptr.?, tokens.ptr, tokens.len * @sizeOf(u32), c.cudaMemcpyHostToDevice);

        self.model.resetRecurrentState();
        const loss = try self.model.forwardAndLoss(tok_gpu.gpu_ptr.?, tokens.len, 0);
        return -loss * @as(f64, @floatFromInt(tokens.len - 1));
    }

    fn runHellaSwag(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.hellaswag, self.allocator);
        const start_ns = std.time.nanoTimestamp();

        const data_path = try std.fmt.allocPrint(
            self.allocator, "{s}/hellaswag_val.jsonl", .{self.config.data_dir},
        );
        defer self.allocator.free(data_path);

        const file = std.fs.cwd().openFile(data_path, .{}) catch {
            std.log.warn("[eval] HellaSwag data not found at {s}", .{data_path});
            return result;
        };
        defer file.close();

        var buf_reader = std.io.bufferedReader(file.reader());
        var line_buf: [65536]u8 = undefined;

        while (true) {
            const line = buf_reader.reader().readUntilDelimiterOrEof(&line_buf, '\n') catch break orelse break;
            if (line.len == 0) continue;

            const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, line, .{}) catch continue;
            defer parsed.deinit();

            const obj = parsed.value.object;
            const ctx_a = obj.get("ctx_a") orelse continue;
            const ctx_b = obj.get("ctx_b") orelse continue;
            const endings_json = obj.get("endings") orelse continue;
            const label_json   = obj.get("label") orelse continue;

            const context = try std.fmt.allocPrint(
                self.allocator, "{s} {s} ",
                .{ ctx_a.string, ctx_b.string },
            );
            defer self.allocator.free(context);

            const correct_idx: u32 = @intCast(label_json.integer);
            var choices: [4][]const u8 = undefined;
            for (endings_json.array.items, 0..) |e, ei| {
                if (ei >= 4) break;
                choices[ei] = e.string;
            }

            const predicted = try self.scoreMCQ(context, choices[0..4]);
            if (predicted == correct_idx) result.num_correct += 1;
            result.num_total += 1;
        }

        if (result.num_total > 0) {
            result.accuracy = @as(f64, @floatFromInt(result.num_correct)) /
                              @as(f64, @floatFromInt(result.num_total));
        }
        result.elapsed_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_ns)) / 1e6;
        return result;
    }

    fn runARC(self: *EvalHarness, difficulty: enum { easy, challenge }) !EvalResult {
        const task: EvalTask = if (difficulty == .easy) .arc_easy else .arc_challenge;
        var result = EvalResult.init(task, self.allocator);
        const start_ns = std.time.nanoTimestamp();

        const fname = if (difficulty == .easy) "arc_easy_test.jsonl" else "arc_challenge_test.jsonl";
        const data_path = try std.fmt.allocPrint(
            self.allocator, "{s}/{s}", .{ self.config.data_dir, fname },
        );
        defer self.allocator.free(data_path);

        const file = std.fs.cwd().openFile(data_path, .{}) catch {
            std.log.warn("[eval] ARC data not found at {s}", .{data_path});
            return result;
        };
        defer file.close();

        var buf_reader = std.io.bufferedReader(file.reader());
        var line_buf: [65536]u8 = undefined;

        while (true) {
            const line = buf_reader.reader().readUntilDelimiterOrEof(&line_buf, '\n') catch break orelse break;
            if (line.len == 0) continue;

            const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, line, .{}) catch continue;
            defer parsed.deinit();

            const obj       = parsed.value.object;
            const question  = (obj.get("question") orelse continue).string;
            const choices_j = (obj.get("choices") orelse continue).object;
            const label_j   = (obj.get("answerKey") orelse continue).string;

            const texts_j   = (choices_j.get("text") orelse continue).array;
            const labels_j  = (choices_j.get("label") orelse continue).array;

            var choices_list = std.ArrayList([]const u8).init(self.allocator);
            defer choices_list.deinit();
            var correct_idx: u32 = 0;

            for (texts_j.items, 0..) |txt, ci| {
                try choices_list.append(txt.string);
                if (ci < labels_j.items.len and
                    std.mem.eql(u8, labels_j.items[ci].string, label_j)) {
                    correct_idx = @intCast(ci);
                }
            }

            const context = try std.fmt.allocPrint(
                self.allocator, "Question: {s}\nAnswer:", .{question},
            );
            defer self.allocator.free(context);

            const predicted = try self.scoreMCQ(context, choices_list.items);
            if (predicted == correct_idx) result.num_correct += 1;
            result.num_total += 1;
        }

        if (result.num_total > 0) {
            result.accuracy = @as(f64, @floatFromInt(result.num_correct)) /
                              @as(f64, @floatFromInt(result.num_total));
        }
        result.elapsed_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_ns)) / 1e6;
        return result;
    }

    fn runWinogrande(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.winogrande, self.allocator);
        const start_ns = std.time.nanoTimestamp();
        const data_path = try std.fmt.allocPrint(
            self.allocator, "{s}/winogrande_val.jsonl", .{self.config.data_dir},
        );
        defer self.allocator.free(data_path);
        const file = std.fs.cwd().openFile(data_path, .{}) catch return result;
        defer file.close();
        var buf_reader = std.io.bufferedReader(file.reader());
        var line_buf: [16384]u8 = undefined;
        while (true) {
            const line = buf_reader.reader().readUntilDelimiterOrEof(&line_buf, '\n') catch break orelse break;
            if (line.len == 0) continue;
            const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, line, .{}) catch continue;
            defer parsed.deinit();
            const obj     = parsed.value.object;
            const sent    = (obj.get("sentence") orelse continue).string;
            const opt1    = (obj.get("option1") orelse continue).string;
            const opt2    = (obj.get("option2") orelse continue).string;
            const answer  = (obj.get("answer") orelse continue).string;
            const correct: u32 = if (std.mem.eql(u8, answer, "1")) 0 else 1;

            const ctx1 = try std.mem.replaceOwned(u8, self.allocator, sent, "_", opt1);
            defer self.allocator.free(ctx1);
            const ctx2 = try std.mem.replaceOwned(u8, self.allocator, sent, "_", opt2);
            defer self.allocator.free(ctx2);

            const lp1 = try self.computeSequenceLogProb(
                try self.tok.encode(ctx1, self.allocator),
            );
            const lp2 = try self.computeSequenceLogProb(
                try self.tok.encode(ctx2, self.allocator),
            );
            const predicted: u32 = if (lp1 > lp2) 0 else 1;
            if (predicted == correct) result.num_correct += 1;
            result.num_total += 1;
        }
        if (result.num_total > 0)
            result.accuracy = @as(f64, @floatFromInt(result.num_correct)) /
                              @as(f64, @floatFromInt(result.num_total));
        result.elapsed_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_ns)) / 1e6;
        return result;
    }

    fn runLAMBADA(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.lambada, self.allocator);
        const start_ns = std.time.nanoTimestamp();
        const data_path = try std.fmt.allocPrint(
            self.allocator, "{s}/lambada_test.jsonl", .{self.config.data_dir},
        );
        defer self.allocator.free(data_path);
        const file = std.fs.cwd().openFile(data_path, .{}) catch return result;
        defer file.close();
        var buf_reader = std.io.bufferedReader(file.reader());
        var line_buf: [32768]u8 = undefined;
        var total_logprob: f64 = 0.0;
        while (true) {
            const line = buf_reader.reader().readUntilDelimiterOrEof(&line_buf, '\n') catch break orelse break;
            if (line.len == 0) continue;
            const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, line, .{}) catch continue;
            defer parsed.deinit();
            const text = (parsed.value.object.get("text") orelse continue).string;
            const tokens = try self.tok.encode(text, self.allocator);
            defer self.allocator.free(tokens);
            if (tokens.len < 2) continue;
            const lp = try self.computeSequenceLogProb(tokens);
            total_logprob += lp;
            result.num_total += 1;
        }
        if (result.num_total > 0) {
            const avg_lp = total_logprob / @as(f64, @floatFromInt(result.num_total));
            result.perplexity = @exp(-avg_lp);
            result.accuracy   = 0.0;
        }
        result.elapsed_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_ns)) / 1e6;
        return result;
    }

    fn runPIQA(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.piqa, self.allocator);
        result.elapsed_ms = 0.0;
        _ = self;
        return result;
    }
    fn runBoolQ(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.boolq, self.allocator);
        _ = self;
        return result;
    }
    fn runMMLU(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.mmlu, self.allocator);
        _ = self;
        return result;
    }
    fn runGSM8K(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.gsm8k, self.allocator);
        _ = self;
        return result;
    }
    fn runHumanEval(self: *EvalHarness) !EvalResult {
        var result = EvalResult.init(.humaneval, self.allocator);
        _ = self;
        return result;
    }

    pub fn saveResults(
        self: *const EvalHarness,
        results: []const EvalResult,
        step: u64,
    ) !void {
        const path = try std.fmt.allocPrint(
            self.allocator, "{s}/eval_step_{:0>10}.json", .{ self.config.results_dir, step },
        );
        defer self.allocator.free(path);
        try std.fs.cwd().makePath(self.config.results_dir);
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const w = file.writer();
        try w.writeAll("{\n  \"step\": ");
        try w.print("{d}", .{step});
        try w.writeAll(",\n  \"results\": [\n");
        for (results, 0..) |*r, i| {
            try w.print(
                "    {{\"task\": \"{s}\", \"accuracy\": {d:.6}, \"num_correct\": {d}, \"num_total\": {d}, \"elapsed_ms\": {d:.1}}}",
                .{ @tagName(r.task), r.accuracy, r.num_correct, r.num_total, r.elapsed_ms },
            );
            if (i + 1 < results.len) try w.writeAll(",\n") else try w.writeAll("\n");
        }
        try w.writeAll("  ]\n}\n");
        std.log.info("[eval] Results saved to {s}", .{path});
    }
};
