const std = @import("std");

pub const SPECIAL_UNK: u32 = 0;
pub const SPECIAL_BOS: u32 = 1;
pub const SPECIAL_EOD: u32 = 2;
pub const SPECIAL_PAD: u32 = 3;

pub const TrieNode = struct {
    children: std.AutoHashMap(u21, *TrieNode),
    token_id: ?u32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !*TrieNode {
        const node = try allocator.create(TrieNode);
        node.* = TrieNode{
            .children  = std.AutoHashMap(u21, *TrieNode).init(allocator),
            .token_id  = null,
            .allocator = allocator,
        };
        return node;
    }

    pub fn deinit(self: *TrieNode) void {
        var it = self.children.iterator();
        while (it.next()) |entry| entry.value_ptr.*.deinit();
        self.children.deinit();
        self.allocator.destroy(self);
    }

    pub fn insert(self: *TrieNode, text: []const u8, token_id: u32) !void {
        var node = self;
        var it = std.unicode.Utf8Iterator{ .bytes = text, .i = 0 };
        while (it.nextCodepoint()) |cp| {
            const gop = try node.children.getOrPut(cp);
            if (!gop.found_existing) {
                gop.value_ptr.* = try TrieNode.init(self.allocator);
            }
            node = gop.value_ptr.*;
        }
        node.token_id = token_id;
    }
};

pub const Tokenizer = struct {
    root:        *TrieNode,
    vocab:       std.StringHashMap(u32),
    id_to_token: std.AutoHashMap(u32, []const u8),
    vocab_size:  u32,
    allocator:   std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !Tokenizer {
        return Tokenizer{
            .root        = try TrieNode.init(allocator),
            .vocab       = std.StringHashMap(u32).init(allocator),
            .id_to_token = std.AutoHashMap(u32, []const u8).init(allocator),
            .vocab_size  = 0,
            .allocator   = allocator,
        };
    }

    pub fn deinit(self: *Tokenizer) void {
        self.root.deinit();
        self.vocab.deinit();
        var it = self.id_to_token.iterator();
        while (it.next()) |e| self.allocator.free(e.value_ptr.*);
        self.id_to_token.deinit();
    }

    pub fn loadFromTSV(self: *Tokenizer, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        var buf_reader = std.io.bufferedReader(file.reader());
        var line_buf: [4096]u8 = undefined;
        var line_count: u32 = 0;

        while (true) {
            const line = buf_reader.reader().readUntilDelimiterOrEof(&line_buf, '\n') catch break orelse break;
            if (line.len == 0) continue;
            var parts = std.mem.splitScalar(u8, line, '\t');
            const tok_text_raw = parts.next() orelse continue;
            const tok_id_str   = parts.next() orelse continue;
            const token_id = std.fmt.parseInt(u32, tok_id_str, 10) catch continue;

            var tok_text_buf: [256]u8 = undefined;
            var tok_text_len: usize = 0;
            var i: usize = 0;
            while (i < tok_text_raw.len) {
                if (i + 1 < tok_text_raw.len and
                    tok_text_raw[i] == '\\' and tok_text_raw[i + 1] == 't') {
                    tok_text_buf[tok_text_len] = '\t';
                    tok_text_len += 1;
                    i += 2;
                } else if (i + 1 < tok_text_raw.len and
                    tok_text_raw[i] == '\\' and tok_text_raw[i + 1] == 'n') {
                    tok_text_buf[tok_text_len] = '\n';
                    tok_text_len += 1;
                    i += 2;
                } else {
                    tok_text_buf[tok_text_len] = tok_text_raw[i];
                    tok_text_len += 1;
                    i += 1;
                }
            }
            const tok_text = tok_text_buf[0..tok_text_len];
            const owned = try self.allocator.dupe(u8, tok_text);
            try self.root.insert(owned, token_id);
            try self.vocab.put(owned, token_id);
            try self.id_to_token.put(token_id, owned);
            line_count += 1;
        }
        self.vocab_size = line_count;
        std.log.info("[tokenizer] Loaded {d} tokens from {s}", .{ line_count, path });
    }

    pub fn encode(self: *const Tokenizer, text: []const u8, allocator: std.mem.Allocator) ![]u32 {
        var tokens = std.ArrayList(u32).init(allocator);
        try tokens.append(SPECIAL_BOS);

        var pos: usize = 0;
        while (pos < text.len) {
            var node = self.root;
            var best_len: usize = 0;
            var best_id: ?u32  = null;
            var j = pos;

            while (j < text.len) {
                const cp_len = std.unicode.utf8ByteSequenceLength(text[j]) catch break;
                if (j + cp_len > text.len) break;
                const cp = std.unicode.utf8Decode(text[j..j+cp_len]) catch break;
                const next_node = node.children.get(cp) orelse break;
                j += cp_len;
                node = next_node;
                if (node.token_id) |id| {
                    best_len = j - pos;
                    best_id  = id;
                }
            }

            if (best_id) |id| {
                try tokens.append(id);
                pos += best_len;
            } else {
                const cp_len = std.unicode.utf8ByteSequenceLength(text[pos]) catch 1;
                const byte_tok = @as(u32, text[pos]) % (self.vocab_size) + 4;
                try tokens.append(byte_tok);
                pos += cp_len;
            }
        }
        return tokens.toOwnedSlice();
    }

    pub fn decode(self: *const Tokenizer, tokens: []const u32, allocator: std.mem.Allocator) ![]u8 {
        var out = std.ArrayList(u8).init(allocator);
        for (tokens) |tok_id| {
            if (tok_id == SPECIAL_BOS or tok_id == SPECIAL_EOD or tok_id == SPECIAL_PAD) continue;
            if (self.id_to_token.get(tok_id)) |text| {
                try out.appendSlice(text);
            } else {
                try out.appendSlice("[UNK]");
            }
        }
        return out.toOwnedSlice();
    }

    pub fn tokenCount(self: *const Tokenizer, text: []const u8) !usize {
        const tokens = try self.encode(text, self.allocator);
        defer self.allocator.free(tokens);
        return tokens.len;
    }
};
