const efla_mod = @import("model/efla.zig");
const tokenizer_mod = @import("model/tokenizer.zig");
const muon_mod = @import("optimizer/muon.zig");
const lion_mod = @import("optimizer/lion.zig");
const harness_mod = @import("eval/harness.zig");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("stdio.h");
});

pub const TrainConfig = struct {
    model_dim:            u32   = 16_384,
    num_layers:           u32   = 126,
    num_heads:            u32   = 128,
    head_dim:             u32   = 128,
    ffn_dim:              u32   = 53_248,
    vocab_size:           u32   = 131_072,
    max_seq_len:          u64   = 131_072,
    num_gpus:             u32   = 8,
    tensor_parallel:      u32   = 8,
    low_rank:             u32   = 64,
    precision:            mem.Precision = .fp32,
    use_fp8_weights:      bool  = false,
    tie_embeddings:       bool  = true,
    gradient_checkpointing: bool = true,
    batch_size:           u32   = 1,
    micro_batch_size:     u32   = 1,
    total_tokens:         u64   = 1_000_000_000_000,
    max_seq_per_batch:    u64   = 131_072,
    grad_clip_norm:       f32   = 1.0,
    checkpoint_dir:       []const u8 = "/mnt/nfs/checkpoints",
    data_path:            []const u8 = "/mnt/nfs/data/train_tokens.bin",
    tokenizer_path:       []const u8 = "/workspace/underdog-llm/vocab/entropy_tokenizer.tsv",
    eval_dir:             []const u8 = "/mnt/nfs/eval_data",
    log_interval:         u32   = 10,
    checkpoint_interval:  u32   = 1000,
    eval_interval:        u32   = 5000,
    muon_lr:              f32   = 0.02,
    muon_momentum:        f32   = 0.95,
    muon_wd:              f32   = 0.01,
    lion_lr:              f32   = 2e-4,
    lion_beta1:           f32   = 0.9,
    lion_beta2:           f32   = 0.99,
    lion_wd:              f32   = 0.0,
    warmup_steps:         u64   = 2000,
    resume_step:          u64   = 0,
    rotary_base:          f32   = 500_000.0,
    seed:                 u64   = 42,
    smoke_test:           bool  = false,
    benchmark_mode:       bool  = false,
    nccl_bw_test:         bool  = false,
    zero3_test:           bool  = false,
};

const DataLoader = struct {
    file:         std.fs.File,
    chunk_size:   usize,
    current_pos:  u64,
    total_tokens: u64,
    buf:          []u32,
    allocator:    std.mem.Allocator,

    pub fn init(path: []const u8, chunk_size: usize, allocator: std.mem.Allocator) !DataLoader {
        const file = try std.fs.cwd().openFile(path, .{});
        const stat  = try file.stat();
        const total = stat.size / @sizeOf(u32);
        const buf   = try allocator.alloc(u32, chunk_size);
        return DataLoader{
            .file         = file,
            .chunk_size   = chunk_size,
            .current_pos  = 0,
            .total_tokens = total,
            .buf          = buf,
            .allocator    = allocator,
        };
    }

    pub fn deinit(self: *DataLoader) void {
        self.file.close();
        self.allocator.free(self.buf);
    }

    pub fn nextChunk(self: *DataLoader) !?[]u32 {
        if (self.current_pos >= self.total_tokens) return null;
        const remaining = self.total_tokens - self.current_pos;
        const to_read   = @min(remaining, self.chunk_size);
        const bytes     = to_read * @sizeOf(u32);
        try self.file.seekTo(self.current_pos * @sizeOf(u32));
        const n_read = try self.file.read(std.mem.sliceAsBytes(self.buf[0..to_read]));
        const n_toks = n_read / @sizeOf(u32);
        self.current_pos += n_toks;
        if (n_toks == 0) return null;
        return self.buf[0..n_toks];
    }

    pub fn epochProgress(self: *const DataLoader) f64 {
        return @as(f64, @floatFromInt(self.current_pos)) /
               @as(f64, @floatFromInt(self.total_tokens)) * 100.0;
    }
};

fn parseArgs(allocator: std.mem.Allocator) !TrainConfig {
    var cfg = TrainConfig{};
    var args = try std.process.argsWithAllocator(allocator);
    defer args.deinit();
    _ = args.next();
    while (args.next()) |arg| {
        if (std.mem.eql(u8, arg, "--smoke-test"))   { cfg.smoke_test = true; }
        else if (std.mem.eql(u8, arg, "--benchmark")) { cfg.benchmark_mode = true; }
        else if (std.mem.eql(u8, arg, "--nccl-bw-test")) { cfg.nccl_bw_test = true; }
        else if (std.mem.eql(u8, arg, "--zero3-test"))    { cfg.zero3_test = true; }
        else if (std.mem.eql(u8, arg, "--resume")) {
            if (args.next()) |v| cfg.resume_step = std.fmt.parseInt(u64, v, 10) catch 0;
        }
        else if (std.mem.eql(u8, arg, "--model-dim")) {
            if (args.next()) |v| cfg.model_dim = std.fmt.parseInt(u32, v, 10) catch cfg.model_dim;
        }
        else if (std.mem.eql(u8, arg, "--num-layers")) {
            if (args.next()) |v| cfg.num_layers = std.fmt.parseInt(u32, v, 10) catch cfg.num_layers;
        }
        else if (std.mem.eql(u8, arg, "--num-heads")) {
            if (args.next()) |v| cfg.num_heads = std.fmt.parseInt(u32, v, 10) catch cfg.num_heads;
        }
        else if (std.mem.eql(u8, arg, "--head-dim")) {
            if (args.next()) |v| cfg.head_dim = std.fmt.parseInt(u32, v, 10) catch cfg.head_dim;
        }
        else if (std.mem.eql(u8, arg, "--ffn-dim")) {
            if (args.next()) |v| cfg.ffn_dim = std.fmt.parseInt(u32, v, 10) catch cfg.ffn_dim;
        }
        else if (std.mem.eql(u8, arg, "--vocab-size")) {
            if (args.next()) |v| cfg.vocab_size = std.fmt.parseInt(u32, v, 10) catch cfg.vocab_size;
        }
        else if (std.mem.eql(u8, arg, "--max-seq-len")) {
            if (args.next()) |v| cfg.max_seq_len = std.fmt.parseInt(u64, v, 10) catch cfg.max_seq_len;
        }
        else if (std.mem.eql(u8, arg, "--num-gpus")) {
            if (args.next()) |v| cfg.num_gpus = std.fmt.parseInt(u32, v, 10) catch cfg.num_gpus;
        }
        else if (std.mem.eql(u8, arg, "--total-steps")) {
            if (args.next()) |v| {
                const steps = std.fmt.parseInt(u64, v, 10) catch 0;
                cfg.total_tokens = steps * cfg.max_seq_len;
            }
        }
    }
    return cfg;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{ .safety = false }){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const cfg = try parseArgs(allocator);

    std.log.info("=== Underdog 1T LLM Training System ===", .{});
    std.log.info("Model: {}L-{}H-{}D-{}FFN", .{
        cfg.num_layers, cfg.num_heads, cfg.model_dim, cfg.ffn_dim,
    });

    var num_real_gpus: c_int = 0;
    _ = c.cudaGetDeviceCount(&num_real_gpus);
    std.log.info("CUDA GPUs detected: {}", .{num_real_gpus});

    const actual_gpus = @min(cfg.num_gpus, @as(u32, @intCast(num_real_gpus)));

    if (cfg.nccl_bw_test) {
        std.log.info("Running NCCL bandwidth test on {} GPUs...", .{actual_gpus});
        var mm = try mem.MemoryManager.init(actual_gpus, allocator);
        defer mm.deinit();
        var comm = try nccl_mod.NcclComm.init(actual_gpus, allocator);
        defer comm.deinit();
        const bw = try nccl_mod.testNcclBandwidth(&comm, 1024 * 1024 * 256, 10, allocator);
        std.log.info("NCCL AllReduce bandwidth: {d:.2} GB/s", .{bw});
        return;
    }

    var mm = try mem.MemoryManager.init(actual_gpus, allocator);
    defer mm.deinit();

    var comm = try nccl_mod.NcclComm.init(actual_gpus, allocator);
    defer comm.deinit();

    const efla_cfg = efla_mod.EFLAConfig{
        .model_dim              = cfg.model_dim,
        .num_layers             = cfg.num_layers,
        .num_heads              = cfg.num_heads,
        .head_dim               = cfg.head_dim,
        .ffn_dim                = cfg.ffn_dim,
        .vocab_size             = cfg.vocab_size,
        .max_seq_len            = cfg.max_seq_len,
        .num_gpus               = actual_gpus,
        .tensor_parallel        = cfg.tensor_parallel,
        .low_rank               = cfg.low_rank,
        .precision              = cfg.precision,
        .gradient_checkpointing = cfg.gradient_checkpointing,
        .use_fp8_weights        = cfg.use_fp8_weights,
        .tie_embeddings         = cfg.tie_embeddings,
        .rotary_base            = cfg.rotary_base,
    };

    std.log.info("Initializing model...", .{});
    var model = try efla_mod.EFLAModel.init(efla_cfg, &mm, &comm, allocator);
    defer model.deinit();
    model.initWeights();
    mm.printMemoryStats();

    if (cfg.smoke_test) {
        std.log.info("Running smoke test...", .{});
        const fake_tokens = try allocator.alloc(u32, @intCast(cfg.max_seq_len));
        defer allocator.free(fake_tokens);
        for (fake_tokens, 0..) |*t, i| t.* = @intCast((i + 1) % cfg.vocab_size);
        var tok_gpu = try mm.allocOnGPU(fake_tokens.len * @sizeOf(u32), 0);
        defer mm.freeGPU(&tok_gpu);
        _ = c.cudaMemcpy(tok_gpu.gpu_ptr.?, fake_tokens.ptr, fake_tokens.len * @sizeOf(u32), c.cudaMemcpyHostToDevice);
        var prev_loss: f64 = 1e9;
        const smoke_steps: u32 = 5;
        for (0..smoke_steps) |si| {
            model.zeroGrads();
            const loss = try model.forwardAndLoss(tok_gpu.gpu_ptr.?, fake_tokens.len, 0);
            std.log.info("Smoke step {}/{}: loss={d:.4}", .{ si + 1, smoke_steps, loss });
            _ = prev_loss;
            prev_loss = loss;
        }
        std.log.info("Smoke test PASSED.", .{});
        return;
    }

    var ckpt_mgr = try checkpoint_mod.CheckpointManager.init(
        cfg.checkpoint_dir, 3, cfg.checkpoint_interval, allocator,
    );
    defer ckpt_mgr.deinit();

    var fault = fault_mod.FaultTolerance.init(
        &ckpt_mgr, 30_000, 5, allocator,
    );
    defer fault.deinit();

    fault_mod.installSignalHandlers();

    var shutdown = fault_mod.GracefulShutdown.init(true, allocator);

    var prof = profiler_mod.Profiler.init(true, allocator);
    defer prof.deinit();

    var throughput = try profiler_mod.ThroughputTracker.init(50, allocator);
    defer throughput.deinit();

    const total_steps = cfg.total_tokens / cfg.max_seq_len;
    const muon_cfg = muon_mod.MuonConfig{
        .lr           = cfg.muon_lr,
        .momentum     = cfg.muon_momentum,
        .weight_decay = cfg.muon_wd,
        .nesterov     = true,
        .ns_steps     = 5,
        .warmup_steps = cfg.warmup_steps,
        .total_steps  = total_steps,
    };
    const lion_cfg = lion_mod.LionConfig{
        .lr           = cfg.lion_lr,
        .beta1        = cfg.lion_beta1,
        .beta2        = cfg.lion_beta2,
        .weight_decay = cfg.lion_wd,
        .warmup_steps = cfg.warmup_steps,
        .total_steps  = total_steps,
    };

    var muon = muon_mod.MuonOptimizer.init(muon_cfg, &mm, allocator);
    defer muon.deinit();
    var lion = lion_mod.LionOptimizer.init(lion_cfg, &mm, allocator);
    defer lion.deinit();

    for (model.layers, 0..) |*layer, li| {
        const dev = layer.device_id;
        const d   = cfg.model_dim;
        const nh  = cfg.num_heads / cfg.tensor_parallel;
        const hd  = cfg.head_dim;
        const fd  = cfg.ffn_dim / cfg.tensor_parallel;
        _ = dev;
        try muon.addParamGroup(layer.qkv_weight, model.grads[li].d_qkv_weight,
            d, 3 * nh * hd);
        try muon.addParamGroup(layer.out_weight, model.grads[li].d_out_weight,
            nh * hd, d);
        try muon.addParamGroup(layer.ffn_up, model.grads[li].d_ffn_up, d, fd);
        try muon.addParamGroup(layer.ffn_gate, model.grads[li].d_ffn_gate, d, fd);
        try muon.addParamGroup(layer.ffn_down, model.grads[li].d_ffn_down, fd, d);
        try lion.addParamGroup(layer.norm1_scale, model.grads[li].d_norm1_scale, d);
        try lion.addParamGroup(layer.norm2_scale, model.grads[li].d_norm2_scale, d);
    }

    var data_loader = DataLoader.init(cfg.data_path, @intCast(cfg.max_seq_len), allocator) catch |e| blk: {
        std.log.warn("Could not open data file: {}. Using random tokens.", .{e});
        break :blk try DataLoader.init("/dev/urandom", @intCast(cfg.max_seq_len), allocator);
    };
    defer data_loader.deinit();

    if (cfg.resume_step > 0) {
        std.log.info("Resuming from step {}...", .{cfg.resume_step});
        muon.global_step = cfg.resume_step;
        lion.global_step = cfg.resume_step;
    }

    var tok_gpu = try mm.allocOnGPU(@intCast(cfg.max_seq_len * @sizeOf(u32)), 0);
    defer mm.freeGPU(&tok_gpu);

    std.log.info("Training start: {} steps, {} tokens total", .{ total_steps, cfg.total_tokens });
    var global_step: u64 = cfg.resume_step;

    while (global_step < total_steps) {
        if (shutdown.waitForSafePoint(global_step, cfg.checkpoint_interval)) break;

        const chunk_opt = data_loader.nextChunk() catch null;
        const tokens = chunk_opt orelse blk: {
            data_loader.current_pos = 0;
            break :blk (data_loader.nextChunk() catch null) orelse break;
        };

        _ = c.cudaSetDevice(0);
        _ = c.cudaMemcpy(
            tok_gpu.gpu_ptr.?,
            tokens.ptr,
            tokens.len * @sizeOf(u32),
            c.cudaMemcpyHostToDevice,
        );

        prof.startStep(tokens.len);

        model.zeroGrads();
        muon.zeroGrads();
        lion.zeroGrads();

        prof.beginTimer("forward", 0, mm.getStream(0));
        const loss = model.forwardAndLoss(
            tok_gpu.gpu_ptr.?,
            tokens.len,
            global_step * cfg.max_seq_len,
        ) catch |e| blk: {
            std.log.err("Forward pass error at step {}: {}", .{ global_step, e });
            break :blk std.math.nan(f64);
        };
        prof.endTimer("forward", mm.getStream(0));

        const action = fault.recordLoss(loss, global_step) catch .continue_training;
        var current_lr: f32 = muon.getLR();
        const should_continue = fault.handleAction(action, global_step, &current_lr) catch true;
        if (!should_continue) {
            global_step += 1;
            continue;
        }

        prof.beginTimer("optimizer", 0, mm.getStream(0));
        try muon.step();
        try lion.step();
        prof.endTimer("optimizer", mm.getStream(0));

        throughput.record(tokens.len);
        global_step += 1;

        if (global_step % cfg.log_interval == 0) {
            const tps = throughput.tokensPerSecond();
            const mfu = throughput.mfuEstimate(
                model.estimateMFLOPsPerToken(),
                312e12,
                @floatFromInt(actual_gpus),
            );
            std.log.info(
                "step={d:>8} loss={d:.4} lr={e:.3} tok/s={d:.0}K mfu={d:.1}% data={d:.1}%",
                .{
                    global_step, loss, muon.getLR(),
                    tps / 1000.0, mfu,
                    data_loader.epochProgress(),
                },
            );
        }

        if (global_step % 500 == 0) {
            prof.printReport();
            mm.printMemoryStats();
            prof.resetCounters();
        }

        if (global_step % cfg.checkpoint_interval == 0) {
            var param_blocks = std.ArrayList(mem.MemoryBlock).init(allocator);
            defer param_blocks.deinit();
            var optim_blocks = std.ArrayList(mem.MemoryBlock).init(allocator);
            defer optim_blocks.deinit();
            for (model.layers) |*layer| {
                try param_blocks.append(layer.qkv_weight);
                try param_blocks.append(layer.out_weight);
                try param_blocks.append(layer.ffn_up);
                try param_blocks.append(layer.ffn_gate);
                try param_blocks.append(layer.ffn_down);
                try param_blocks.append(layer.norm1_scale);
                try param_blocks.append(layer.norm2_scale);
            }
            for (muon.states.items) |*state| {
                try optim_blocks.append(state.momentum_buf);
            }
            for (lion.states.items) |*state| {
                try optim_blocks.append(state.momentum_buf);
            }
            var streams = try allocator.alloc(c.cudaStream_t, actual_gpus);
            defer allocator.free(streams);
            for (0..actual_gpus) |i| streams[i] = mm.getCheckpointStream(@intCast(i));
            const header = checkpoint_mod.CheckpointHeader{
                .step            = global_step,
                .loss            = loss,
                .lr              = muon.getLR(),
                .tokens_seen     = global_step * cfg.max_seq_len,
                .num_layers      = cfg.num_layers,
                .model_dim       = cfg.model_dim,
                .num_heads       = cfg.num_heads,
                .head_dim        = cfg.head_dim,
                .ffn_dim         = cfg.ffn_dim,
                .vocab_size      = cfg.vocab_size,
                .max_seq_len     = cfg.max_seq_len,
                .num_gpus        = actual_gpus,
                .precision       = @intFromEnum(cfg.precision),
                .timestamp_unix  = std.time.timestamp(),
                .wall_time_seconds = @as(f64, @floatFromInt(std.time.timestamp() - ckpt_mgr.wall_time_start)),
                .grad_norm       = 1.0,
                .weight_decay    = cfg.muon_wd,
            };
            ckpt_mgr.save(
                global_step, header,
                param_blocks.items,
                optim_blocks.items,
                streams,
            ) catch |e| std.log.err("Checkpoint save failed: {}", .{e});
        }
    }

    std.log.info("Training complete at step {}.", .{global_step});
}
