**`build.zig`**
```zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target   = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name   = "underdog-llm",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    exe.addIncludePath(b.path("include"));
    exe.addIncludePath(.{ .cwd_relative = "/usr/local/cuda/include" });
    exe.addLibraryPath(.{ .cwd_relative = "/usr/local/cuda/lib64" });
    exe.addLibraryPath(.{ .cwd_relative = "/usr/lib/x86_64-linux-gnu" });
    exe.addLibraryPath(b.path("kernels"));

    exe.linkSystemLibrary("cudart");
    exe.linkSystemLibrary("cublas");
    exe.linkSystemLibrary("nccl");
    exe.linkSystemLibrary("curand");
    exe.linkSystemLibrary("uring");
    exe.linkSystemLibrary("c");

    exe.addObjectFile(b.path("kernels/libcudakernels.so"));

    exe.linkLibC();

    exe.root_module.addRPathSpecial("$ORIGIN/../kernels");
    exe.root_module.addRPathSpecial("/usr/local/cuda/lib64");
    exe.root_module.addRPathSpecial("/usr/lib/x86_64-linux-gnu");

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the training binary");
    run_step.dependOn(&run_cmd.step);

    const unit_tests = b.addTest(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });
    unit_tests.addIncludePath(b.path("include"));
    unit_tests.addIncludePath(.{ .cwd_relative = "/usr/local/cuda/include" });
    unit_tests.addLibraryPath(.{ .cwd_relative = "/usr/local/cuda/lib64" });
    unit_tests.addLibraryPath(.{ .cwd_relative = "/usr/lib/x86_64-linux-gnu" });
    unit_tests.addLibraryPath(b.path("kernels"));
    unit_tests.linkSystemLibrary("cudart");
    unit_tests.linkSystemLibrary("cublas");
    unit_tests.linkSystemLibrary("nccl");
    unit_tests.linkSystemLibrary("c");
    unit_tests.addObjectFile(b.path("kernels/libcudakernels.so"));
    unit_tests.linkLibC();

    const run_unit_tests = b.addRunArtifact(unit_tests);
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&run_unit_tests.step);
}
